  @json_schema_draft "https://json-schema.org/draft/2020-12/schema"
  @stable_id_pattern "^[A-Za-z0-9][A-Za-z0-9._:@-]*$"
  @stable_id_regex ~r/^[A-Za-z0-9][A-Za-z0-9._:@-]*$/
  @sha256_pattern "^[0-9a-f]{64}$"
  @sha256_regex ~r/\A[0-9a-f]{64}\z/
  @compatibility_policy %{
    "policy_version" => 1,
    "validation_mode" => "top_level_compatibility_export",
    "compatible_changes" => [
      "add_optional_fields",
      "add_optional_nested_contracts",
      "tighten_executable_semantic_validation_without_changing_exported_required_fields"
    ],
    "breaking_changes" => [
      "remove_required_fields",
      "change_required_field_type",
      "change_schema_contract_identifier",
      "change_schema_version_const",
      "change_required_field_semantics"
    ],
    "breaking_change_action" =>
      "mint a new schema_contract name or increment the artifact schema_version before publishing"
  }
  @identity_policy %{
    "policy_version" => 1,
    "stable_id_pattern" => @stable_id_pattern,
    "description" =>
      "Public artifact identifiers are non-empty machine identifiers without whitespace.",
    "compatible_changes" => [
      "add_optional_identifier_fields",
      "add_more_specific_semantic_source_metadata_without_changing_existing_ids"
    ],
    "semantic_invariants" => [
      "source_record_order_must_not_change_generated_identity",
      "semantic_source_identity_must_remain_stable_across_manifest_export",
      "scenario_and_activity_identity_must_not_depend_on_wall_clock_time"
    ],
    "generated_id_scopes" => [
      %{
        "scope" => "candidate_refresh.v1.candidate_activities",
        "identity_fields" => [
          "scenario_id",
          "type",
          "source_window_id",
          "target_id",
          "ground_station_id"
        ],
        "ordering" => ["result_event_type", "scenario_id", "source_window_id", "starts_at_s"]
      },
      %{
        "scope" => "candidate_refresh.v1.refreshed_windows.generated_window_id",
        "generated_id_field" => "id",
        "identity_fields" => [
          "type",
          "scenario_id",
          "target_id",
          "ground_station_id",
          "starts_at_s",
          "ends_at_s"
        ],
        "ordering" => [
          "type",
          "scenario_id",
          "target_id",
          "ground_station_id",
          "starts_at_s",
          "id"
        ],
        "semantic_invariants" => [
          "source_record_order_must_not_change_generated_window_id",
          "canonical_source_event_sort_key_must_drive_window_index",
          "same_semantic_source_window_must_keep_generated_window_id"
        ]
      },
      %{
        "scope" => "accepted_planning_state.v1.spacecraft_states",
        "identity_fields" => ["spacecraft_id", "scenario_id", "epoch.seconds_since_j2000"],
        "ordering" => ["spacecraft_id", "scenario_id", "epoch.seconds_since_j2000"]
      },
      %{
        "scope" => "contact_contention_report.v1.conflict_groups.generated_group_id",
        "generated_id_field" => "id",
        "identity_fields" => [
          "resource_scope",
          "ground_station_id",
          "spacecraft_id",
          "starts_at_s",
          "ends_at_s",
