  @doc """
  Returns the known executable artifact contracts.
  """
  def contracts, do: @contracts

  @doc """
  Returns public capability metadata for the executable artifact registry.
  """
  def capabilities do
    %{
      model: :executable_artifact_contract_registry,
      artifact_contracts: @contracts |> Map.keys() |> Enum.sort(),
      artifact_contract_count: map_size(@contracts),
      json_schema_draft: @json_schema_draft,
      compatibility_policy_version: @compatibility_policy["policy_version"],
      identity_policy_version: @identity_policy["policy_version"],
      validation_report_contracts: [
        @schema_validation_report,
        @schema_validation_batch_report,
        @schema_migration_report
      ],
      validation_report_semantics: [
        :schema_validation_validated_contract_metadata,
        :schema_validation_status_and_issue_counts,
        :schema_validation_remediation_rows,
        :schema_validation_model_limit_enforcement,
        :schema_validation_batch_file_artifact_and_skip_counts,
        :schema_validation_batch_nested_report_entries,
        :schema_validation_batch_skipped_artifact_rows,
        :schema_migration_deprecation_warning_rollups,
        :schema_migration_status_and_action_counts
      ],
      compatibility_export_semantics: [
        :compatibility_policy_version_breadcrumbs,
        :identity_policy_version_breadcrumbs,
        :top_level_json_schema_compatibility_export,
        :direct_declared_nested_contract_defs,
        :executable_validator_source_of_truth
      ],
      known_limits: schema_validation_model_limits()
    }
  end

  @doc """
  Returns the schema export compatibility policy.

  The current JSON Schema documents are top-level compatibility exports. Nested
  and semantic checks remain in the executable Elixir validators, so published
  contract compatibility is evaluated against required fields, their coarse
  exported types, and schema contract/version identifiers.
  """
  def compatibility_policy, do: @compatibility_policy

  @doc """
  Returns the stable identity policy for public artifact IDs.
  """
  def identity_policy, do: @identity_policy

  @doc """
  Returns one known contract by name.
  """
  def contract(name) when is_binary(name), do: Map.fetch(@contracts, name)

  @doc """
  Exports one executable contract as a machine-readable JSON Schema document.

  The generated schema is intentionally a top-level compatibility contract. The
  Elixir validators remain the source of truth for nested rows and semantic
  checks while artifact shapes are still maturing.
  """
  def json_schema(@candidate_activity) do
    {:ok,
     candidate_activity_json_schema()
     |> Map.put("$schema", @json_schema_draft)
     |> Map.put("$id", "https://orbital-dynamics.local/schemas/candidate_activity.v1.schema.json")
     |> Map.put("title", "OrbitalDynamics candidate_activity.v1")
     |> Map.put("x-orbital-dynamics", %{
       "schema_contract" => @candidate_activity,
       "artifact_family" => "candidate_activity",
       "schema_version" => 1,
       "nested_contracts" => [],
       "validation_mode" => "top_level_compatibility_export",
       "nested_contract_definition_scope" => "direct_declared_contracts",
       "compatibility_policy" => @compatibility_policy,
       "identity_policy" => @identity_policy,
       "compatibility_policy_version" => @compatibility_policy["policy_version"],
       "identity_policy_version" => @identity_policy["policy_version"],
       "executable_contract" => true
     })}
  end

  def json_schema(name) when is_binary(name) do
    with {:ok, contract} <- contract(name) do
      {:ok, json_schema_document(name, contract)}
    end
  end

  @doc """
  Exports all executable contracts as a deterministic registry bundle.
  """
  def json_schema_bundle do
    schemas =
      @contracts
      |> Map.keys()
      |> Enum.sort()
      |> Map.new(fn name ->
        {:ok, schema} = json_schema(name)
        {name, schema}
      end)

    %{
      "$schema" => @json_schema_draft,
      "$id" => "https://orbital-dynamics.local/schemas/orbital_dynamics.schema_bundle.v1.json",
      "title" => "OrbitalDynamics Artifact Schema Bundle",
      "schema_contract" => "orbital_dynamics.schema_bundle.v1",
      "schema_count" => map_size(schemas),
      "compatibility_policy" => @compatibility_policy,
      "identity_policy" => @identity_policy,
      "schemas" => schemas
    }
  end

  @doc """
  Writes one exported JSON Schema document to disk.
  """
  def write_json_schema!(name, path) when is_binary(name) and is_binary(path) do
    {:ok, schema} = json_schema(name)
    write_json!(schema, path)
  end

  @doc """
  Writes the exported JSON Schema registry bundle to disk.
  """
  def write_json_schema_bundle!(path) when is_binary(path) do
    json_schema_bundle()
    |> write_json!(path)
  end

  @doc """
  Writes every exported contract schema to a directory.
  """
  def write_json_schema_files!(directory) when is_binary(directory) do
    @contracts
    |> Map.keys()
    |> Enum.sort()
    |> Enum.map(fn name ->
      write_json_schema!(name, Path.join(directory, "#{name}.schema.json"))
    end)
  end

  @doc """
  Declares the model limits for schema validation reports.
  """
  def schema_validation_model_limits do
    [
      "top_level_json_schema_compatibility_export",
      "executable_elixir_validator_is_source_of_truth",
      "semantic_checks_are_not_fully_represented_in_json_schema"
    ]
  end

  @doc """
  Validates an artifact map against the inferred or requested contract.

  Returns `{:ok, report}` when the artifact satisfies the contract and
  `{:error, report}` otherwise. Reports are JSON-serializable maps.
  """
  def validate_artifact(%{} = artifact, opts \\ []) do
    with {:ok, contract_name, artifact} <- artifact_for_validation(artifact, opts),
         {:ok, contract} <- contract(contract_name) do
      issues = validate_contract(contract_name, contract, artifact)
      errors = Enum.filter(issues, &(&1["severity"] == "error"))
      warnings = Enum.filter(issues, &(&1["severity"] == "warning"))

      report = %{
        "schema_contract" => contract_name,
        "artifact_family" => contract["artifact_family"],
        "schema_version" => contract["schema_version"],
        "status" => if(errors == [], do: "pass", else: "fail"),
        "errors" => errors,
        "warnings" => warnings
      }

      if errors == [], do: {:ok, report}, else: {:error, report}
    else
      {:error, reason} ->
        report = %{
          "schema_contract" => contract_name_from_opts(opts),
          "artifact_family" => nil,
          "schema_version" => nil,
          "status" => "fail",
          "errors" => [error("$", reason)],
          "warnings" => []
        }

        {:error, report}

      :error ->
        report = %{
          "schema_contract" => contract_name_from_opts(opts),
          "artifact_family" => nil,
          "schema_version" => nil,
          "status" => "fail",
          "errors" => [
            error(
              "$",
              "unknown schema contract: #{contract_name_from_opts(opts) || "not declared"}"
            )
          ],
          "warnings" => []
        }

        {:error, report}
    end
  end

  @doc """
  Wraps artifact validation in a `schema_validation_report.v1` artifact.
  """
  def validation_report(%{} = artifact, opts \\ []) do
    validation_mode = opts |> Keyword.get(:validation_mode, "artifact_map") |> to_string()
    artifact_path = Keyword.get(opts, :artifact_path)

    {_status, report} =
      case validate_artifact(artifact, opts) do
        {:ok, report} -> {:ok, report}
        {:error, report} -> {:error, report}
      end

    schema_validation_report(report, validation_mode, artifact_path)
  end

  @doc """
  Validates a JSON artifact file.

  If the file is a study result artifact with an embedded `campaign_plan`, the
  nested campaign artifact is validated by default.
  """
  def lint_file(path, opts \\ []) when is_binary(path) do
    artifact =
      path
      |> File.read!()
      |> :json.decode()

    validate_artifact(artifact, opts)
  end

  @doc """
  Validates a JSON artifact file and returns `schema_validation_report.v1`.
  """
  def lint_file_report(path, opts \\ []) when is_binary(path) do
    artifact =
      path
      |> File.read!()
      |> :json.decode()

    validation_report(
      artifact,
      opts
      |> Keyword.put(:validation_mode, "artifact_file")
      |> Keyword.put(:artifact_path, path)
    )
  end

  defp schema_validation_report(report, validation_mode, artifact_path) do
    errors = Map.get(report, "errors", [])
    warnings = Map.get(report, "warnings", [])
    remediation = validation_remediation(report, errors)

    %{
      "schema_contract" => @schema_validation_report,
      "model" => "executable_artifact_contract_validation",
      "validation_mode" => validation_mode,
      "validated_contract" => Map.get(report, "schema_contract") || "unknown",
      "validated_artifact_family" => Map.get(report, "artifact_family"),
      "validated_schema_version" => Map.get(report, "schema_version"),
      "status" => Map.get(report, "status"),
      "model_limits" => schema_validation_model_limits(),
      "error_count" => length(errors),
      "warning_count" => length(warnings),
      "errors" => errors,
      "warnings" => warnings,
      "remediation_count" => length(remediation),
      "remediation" => remediation,
      "assumptions" => %{
        "validator" => "OrbitalDynamics.Schema.validate_artifact",
        "validation_scope" => "executable_contract_required_fields_and_semantic_checks",
        "json_schema_export_scope" => "top_level_compatibility"
      }
    }
    |> maybe_put("artifact_path", artifact_path)
  end

  defp validation_remediation(report, errors) do
    contract_name = Map.get(report, "schema_contract") || "artifact"

    errors
    |> Enum.map(&remediation_for_issue(&1, contract_name))
    |> Enum.reject(&is_nil/1)
  end

  defp remediation_for_issue(%{"path" => path, "message" => "is required"} = issue, contract_name) do
    %{
      "path" => path,
      "category" => "missing_required_field",
      "action" => "Populate this required field for #{contract_name}",
      "source_message" => issue["message"]
    }
  end

  defp remediation_for_issue(
         %{"path" => path, "message" => "could not infer schema contract from artifact"} = issue,
         _contract_name
       ) do
    %{
      "path" => path,
      "category" => "contract_inference_failure",
      "action" => "Declare schema_contract or pass an explicit contract before validation",
      "source_message" => issue["message"]
    }
  end

  defp remediation_for_issue(
         %{"path" => path, "message" => "unknown schema contract: " <> _} = issue,
         _contract_name
       ) do
    %{
      "path" => path,
      "category" => "unsupported_schema_contract",
      "action" => "Use a supported schema contract or publish a compatible artifact contract",
      "source_message" => issue["message"]
    }
  end

  defp remediation_for_issue(
         %{"path" => path, "message" => "must be a " <> type} = issue,
         contract_name
       ) do
    %{
      "path" => path,
      "category" => "type_mismatch",
      "action" => "Set this field to a #{type} value for #{contract_name}",
      "source_message" => issue["message"]
    }
  end

  defp remediation_for_issue(
         %{"path" => path, "message" => "must equal " <> expected} = issue,
         contract_name
       ) do
    %{
      "path" => path,
      "category" => "constant_mismatch",
      "action" => "Set this field to #{expected} for #{contract_name}",
      "source_message" => issue["message"]
    }
  end

  defp remediation_for_issue(
         %{"path" => path, "message" => "must be one of " <> allowed} = issue,
         contract_name
       ) do
    %{
      "path" => path,
      "category" => "unsupported_value",
      "action" => "Set this field to one of #{allowed} for #{contract_name}",
      "source_message" => issue["message"]
    }
  end

  defp remediation_for_issue(%{"path" => path, "message" => message} = issue, contract_name)
       when is_binary(path) and is_binary(message) do
    %{
      "path" => path,
      "category" => "semantic_validation_failure",
      "action" => "Review this executable validation failure for #{contract_name}",
      "source_message" => issue["message"]
    }
  end

  defp remediation_for_issue(_issue, _contract_name), do: nil

  defp maybe_put(map, _key, nil), do: map
  defp maybe_put(map, key, value), do: Map.put(map, key, value)
  defp maybe_put_non_empty(map, _key, value) when value == %{}, do: map
  defp maybe_put_non_empty(map, key, value), do: Map.put(map, key, value)

  defp artifact_for_validation(%{} = artifact, opts) do
    contract_name = contract_name_from_opts(opts)

    if contract_name == @result_artifact do
      {:ok, @result_artifact, artifact}
    else
      artifact_for_validation_inferred(artifact, contract_name)
    end
  end

  defp artifact_for_validation_inferred(%{"campaign_plan" => %{} = campaign_plan}, contract_name) do
    contract_name = contract_name || @campaign_plan
    {:ok, contract_name, campaign_plan}
  end

  defp artifact_for_validation_inferred(
         %{"candidate_refresh" => %{} = candidate_refresh},
         contract_name
       ) do
    contract_name = contract_name || @candidate_refresh
    {:ok, contract_name, candidate_refresh}
  end

  defp artifact_for_validation_inferred(
         %{"schema_version" => 1, "study_id" => _study_id, "execution_report" => %{}} = artifact,
         nil
       ) do
    {:ok, @result_artifact, artifact}
  end

  defp artifact_for_validation_inferred(
         %{"execution_report" => %{} = execution_report},
         contract_name
       ) do
    contract_name = contract_name || @execution_report
    {:ok, contract_name, execution_report}
  end

  defp artifact_for_validation_inferred(%{} = artifact, contract_name) do
    case contract_name || infer_contract(artifact) do
      nil -> {:error, "could not infer schema contract from artifact"}
      contract_name -> {:ok, contract_name, artifact}
    end
  end

  defp contract_name_from_opts(opts) do
    Keyword.get(opts, :contract) || Keyword.get(opts, :schema_contract)
  end

