  defp infer_contract(_artifact), do: nil

  defp json_schema_document(name, contract) do
    required_fields = contract["required_fields"]
    optional_fields = Map.get(contract, "optional_fields", [])
    property_fields = Enum.uniq(required_fields ++ optional_fields)
    nested_defs = nested_schema_definitions(contract["nested_contracts"])

    %{
      "$schema" => @json_schema_draft,
      "$id" => "https://orbital-dynamics.local/schemas/#{name}.schema.json",
      "title" => "OrbitalDynamics #{name}",
      "type" => "object",
      "additionalProperties" => true,
      "required" => required_fields,
      "properties" =>
        property_fields
        |> Enum.sort()
        |> Map.new(&{&1, json_schema_property(&1, name, contract)}),
      "x-orbital-dynamics" => %{
        "schema_contract" => name,
        "artifact_family" => contract["artifact_family"],
        "schema_version" => contract["schema_version"],
        "nested_contracts" => contract["nested_contracts"],
        "validation_mode" => "top_level_compatibility_export",
        "nested_contract_definition_scope" => "direct_declared_contracts",
        "compatibility_policy" => @compatibility_policy,
        "identity_policy" => @identity_policy,
        "compatibility_policy_version" => @compatibility_policy["policy_version"],
        "identity_policy_version" => @identity_policy["policy_version"],
        "executable_contract" => true
      }
    }
    |> maybe_put_non_empty("$defs", nested_defs)
    |> maybe_add_trust_boundary_requirement(name)
    |> maybe_add_accepted_planning_state_import_requirement(name)
    |> maybe_add_realized_activity_provider_requirement(name)
    |> maybe_add_planned_activity_type_requirement(name)
    |> maybe_add_constraint_report_model_limit_conditions(name)
    |> maybe_add_environment_model_capability_known_limit_conditions(name)
    |> maybe_add_environment_provider_capability_known_limit_conditions(name)
    |> maybe_add_validation_record_registry_conditions(name)
  end

  defp maybe_add_planned_activity_type_requirement(schema, @planned_activity) do
    Map.put(schema, "anyOf", [
      %{"required" => ["type"]},
      %{"required" => ["activity_type"]}
    ])
  end

  defp maybe_add_planned_activity_type_requirement(schema, _name), do: schema

  defp maybe_add_trust_boundary_requirement(schema, name)
       when name in [
              @station_calendar_provider,
              @spacecraft_state_estimate,
              @maneuver_execution_delta
            ] do
    Map.put(schema, "anyOf", [
      %{"required" => ["trust_boundary"]},
      %{
        "required" => ["provenance"],
        "properties" => %{
          "provenance" => %{
            "type" => "object",
            "required" => ["trust_boundary"],
            "properties" => %{"trust_boundary" => %{"type" => "string"}},
            "additionalProperties" => true
          }
        }
      }
    ])
  end

  defp maybe_add_trust_boundary_requirement(schema, _name), do: schema

  defp maybe_add_accepted_planning_state_import_requirement(schema, @accepted_planning_state) do
    Map.put(schema, "allOf", [
      %{
        "if" => %{
          "properties" => %{
            "provenance" => %{
              "type" => "object",
              "anyOf" => [
                %{"required" => ["input_format"]},
                %{"required" => ["import_adapter"]},
                %{"required" => ["provider"]},
                %{"required" => ["adapter"]},
                %{"required" => ["adapter_version"]}
              ]
            }
          }
        },
        "then" => %{
          "properties" => %{
            "provenance" => %{
              "type" => "object",
              "required" => ["trust_boundary"],
              "properties" => %{"trust_boundary" => %{"type" => "string"}},
              "additionalProperties" => true
            }
          }
        }
      }
    ])
  end

  defp maybe_add_accepted_planning_state_import_requirement(schema, _name), do: schema

  defp maybe_add_realized_activity_provider_requirement(schema, @realized_activity) do
    Map.put(schema, "allOf", [
      %{
        "if" => %{
          "anyOf" => [
            %{"required" => ["provider"]},
            %{"required" => ["adapter"]},
            %{"required" => ["adapter_version"]},
            %{"required" => ["external_id"]}
          ]
        },
        "then" => %{
          "required" => ["external_id"],
          "anyOf" => [
            %{"required" => ["trust_boundary"]},
            %{
              "required" => ["provenance"],
              "properties" => %{
                "provenance" => %{
                  "type" => "object",
                  "required" => ["trust_boundary"],
                  "properties" => %{"trust_boundary" => %{"type" => "string"}},
                  "additionalProperties" => true
                }
              }
            }
          ]
        }
      }
    ])
  end

  defp maybe_add_realized_activity_provider_requirement(schema, _name), do: schema

  defp maybe_add_constraint_report_model_limit_conditions(schema, @constraint_report) do
    conditions =
      for {model, limits} <- constraint_report_model_limits_by_model() do
        %{
          "if" => %{"properties" => %{"model" => %{"const" => model}}},
          "then" => %{"properties" => %{"model_limits" => %{"const" => limits}}}
        }
      end

    Map.update(schema, "allOf", conditions, &(List.wrap(&1) ++ conditions))
  end

  defp maybe_add_constraint_report_model_limit_conditions(schema, _name), do: schema

  defp maybe_add_environment_model_capability_known_limit_conditions(
         schema,
         @environment_model_capability
       ) do
    conditions =
      for %{"id" => id, "known_limits" => limits} <-
            OrbitalDynamics.Environment.model_capabilities() do
        %{
          "if" => %{"properties" => %{"id" => stable_id_const_json_schema(id)}},
          "then" => %{"properties" => %{"known_limits" => %{"const" => limits}}}
        }
      end

    Map.update(schema, "allOf", conditions, &(List.wrap(&1) ++ conditions))
  end

  defp maybe_add_environment_model_capability_known_limit_conditions(schema, _name), do: schema

  defp maybe_add_environment_provider_capability_known_limit_conditions(
         schema,
         @environment_provider_capability
       ) do
    conditions =
      for %{"id" => id, "known_limits" => limits} <-
            OrbitalDynamics.Environment.provider_capabilities() do
        %{
          "if" => %{"properties" => %{"id" => stable_id_const_json_schema(id)}},
          "then" => %{"properties" => %{"known_limits" => %{"const" => limits}}}
        }
      end

    Map.update(schema, "allOf", conditions, &(List.wrap(&1) ++ conditions))
  end

  defp maybe_add_environment_provider_capability_known_limit_conditions(schema, _name), do: schema

  defp maybe_add_validation_record_registry_conditions(schema, @validation_record) do
    conditions = validation_record_registry_conditions()

    Map.update(schema, "allOf", conditions, &(List.wrap(&1) ++ conditions))
  end

  defp maybe_add_validation_record_registry_conditions(schema, _name), do: schema

  defp nested_schema_definitions(contracts) do
    contracts
    |> Enum.uniq()
    |> Enum.sort()
    |> Enum.flat_map(fn name ->
      case contract(name) do
        {:ok, contract} ->
          [
            {name,
             name
             |> json_schema_document(contract)
             |> Map.delete("$defs")
             |> scrub_nested_schema_metadata()}
          ]

        :error ->
          []
      end
    end)
    |> Map.new()
  end

  defp scrub_nested_schema_metadata(schema) do
    update_in(schema, ["x-orbital-dynamics"], fn
      nil ->
        nil

      metadata ->
        metadata
        |> Map.delete("compatibility_policy")
        |> Map.delete("identity_policy")
    end)
  end

  defp candidate_diff_reason_json_schema do
    %{
      "type" => "string",
      "enum" => [
        "present_in_prior_candidate_set",
        "present_in_prior_candidate_set_with_semantic_changes",
        "not_present_in_prior_candidate_set",
        "semantically_similar_prior_candidate_changed",
        "ambiguous_semantic_prior_candidate_match"
      ]
