  defp validation_record_registry_conditions do
    OrbitalDynamics.Validation.registry()
    |> Map.values()
    |> Enum.sort_by(& &1["id"])
    |> Enum.map(fn %{"id" => id, "model" => model, "known_limits" => limits} ->
      %{
        "if" => %{"properties" => %{"id" => stable_id_const_json_schema(id)}},
        "then" => %{
          "properties" => %{
            "model" => %{"const" => model},
            "known_limits" => %{"const" => limits}
          }
        }
      }
    end)
  end

