  defp maybe_add_const(property, "schema_contract", name, _contract) do
    property
    |> Map.put("const", name)
    |> Map.put("description", "Stable executable contract identifier")
  end

  defp maybe_add_const(property, "schema_version", _name, contract) do
    property
    |> Map.put("const", contract["schema_version"])
    |> Map.put("description", "Artifact schema version")
  end

  defp maybe_add_const(property, "artifact_type", _name, contract) do
    Map.put(property, "const", contract["artifact_family"])
  end

  defp maybe_add_const(property, _field, _name, _contract), do: property

  defp maybe_add_stable_id_pattern(%{"type" => "string"} = property, field) do
    if stable_id_field?(field) do
      Map.put(property, "pattern", @stable_id_pattern)
    else
      property
    end
  end

  defp maybe_add_stable_id_pattern(property, _field), do: property

  defp stable_id_field?(field), do: field == "id" or String.ends_with?(field, "_id")

  defp write_json!(artifact, path) do
    path
    |> Path.dirname()
    |> File.mkdir_p!()

    json =
      artifact
      |> :json.encode()
      |> IO.iodata_to_binary()

    File.write!(path, json <> "\n")
    path
  end

  defp validate_candidate_refresh_source_report_provenance(
         issues,
         %{"provenance" => %{} = provenance}
       ) do
    issues
    |> expect_optional_type("$.provenance", provenance, "source_reports", :map)
    |> validate_candidate_refresh_source_report_summaries(Map.get(provenance, "source_reports"))
  end

  defp validate_candidate_refresh_source_report_provenance(issues, _artifact), do: issues

  defp validate_candidate_refresh_source_report_summaries(issues, nil), do: issues

  defp validate_candidate_refresh_source_report_summaries(issues, source_reports)
       when is_map(source_reports) do
    Enum.reduce(source_reports, issues, fn {family, summary}, issues ->
      path = "$.provenance.source_reports.#{family}"

      issues =
        expect_type(
          issues,
          "$.provenance.source_reports",
          source_reports,
          family,
          :map
        )

      if is_map(summary) do
        issues
        |> expect_optional_type(path, summary, "contract", :binary)
        |> expect_optional_type(path, summary, "paths", :list)
        |> validate_string_list_items(path, summary, "paths")
        |> expect_optional_non_negative_integer(path, summary, "count")
        |> expect_optional_non_negative_integer(path, summary, "row_count")
        |> validate_non_negative_integer_count_map(
          path <> ".analysis_mode_counts",
          Map.get(summary, "analysis_mode_counts")
        )
        |> expect_optional_type(path, summary, "trust_boundary_status", :binary)
        |> expect_optional_type(path, summary, "trust_boundaries", :list)
        |> validate_string_list_items(path, summary, "trust_boundaries")
        |> expect_optional_non_negative_integer(
          path,
          summary,
          "station_reservation_evidence_row_count"
        )
        |> expect_optional_non_negative_integer(
          path,
          summary,
          "station_reservation_expiration_evidence_row_count"
        )
        |> validate_operational_readiness_resource_context(path, summary)
        |> validate_operational_readiness_adapter_boundary_context(path, summary)
        |> validate_operational_readiness_cadence_import_context(path, summary)
        |> validate_candidate_refresh_link_capacity_context(path, summary)
        |> validate_candidate_refresh_constraint_context(path, summary)
        |> validate_candidate_refresh_resource_projection_context(path, summary)
        |> validate_candidate_refresh_resource_filter_context(path, summary)
        |> validate_candidate_refresh_contact_contention_context(path, summary)
        |> validate_candidate_refresh_candidate_rejection_context(path, summary)
        |> validate_candidate_refresh_provider_counteroffer_context(path, summary)
        |> validate_candidate_refresh_maneuver_review_context(path, summary)
        |> validate_candidate_refresh_station_pressure_context(path, summary)
        |> validate_candidate_refresh_contact_intent_context(path, summary)
        |> validate_candidate_refresh_contact_filter_context(path, summary)
        |> validate_candidate_refresh_station_calendar_context(path, summary)
        |> validate_candidate_refresh_timeline_activity_context(path, summary)
        |> validate_candidate_refresh_timeline_activity_lifecycle_context(path, summary)
        |> validate_candidate_refresh_timeline_lifecycle_state_context(path, summary)
        |> validate_candidate_refresh_timeline_activity_precondition_context(path, summary)
        |> validate_candidate_refresh_timeline_integrity_context(path, summary)
        |> validate_candidate_refresh_timeline_publication_context(path, summary)
        |> validate_candidate_refresh_timeline_dependency_impact_context(path, summary)
        |> validate_candidate_refresh_timeline_feedback_context(path, summary)
        |> validate_candidate_refresh_timeline_diff_context(path, summary)
        |> validate_candidate_refresh_timeline_transition_application_context(path, summary)
        |> validate_candidate_refresh_operational_timeline_context(path, summary)
        |> validate_candidate_refresh_quality_gate_context(path, summary)
        |> validate_candidate_refresh_schema_validation_context(path, summary)
        |> validate_candidate_refresh_model_acceptance_context(path, summary)
        |> validate_candidate_refresh_freshness_context(path, summary)
        |> validate_candidate_refresh_objective_gap_context(path, summary)
        |> validate_candidate_refresh_refresh_budget_context(path, summary)
        |> validate_candidate_refresh_validation_safety_case_context(path, summary)
      else
        issues
      end
    end)
  end

  defp validate_candidate_refresh_source_report_summaries(issues, _source_reports), do: issues

  defp validate_candidate_refresh_provider_counteroffer_context(issues, path, summary) do
    issues
    |> expect_optional_non_negative_integer(path, summary, "reviewable_count")
    |> expect_optional_non_negative_integer(path, summary, "counteroffer_cost_delta_count")
    |> expect_optional_non_negative_integer(path, summary, "counteroffer_timing_shift_count")
    |> expect_optional_non_negative_integer(path, summary, "counteroffer_start_delta_count")
    |> expect_optional_non_negative_integer(path, summary, "counteroffer_end_delta_count")
    |> expect_optional_non_negative_integer(path, summary, "counteroffer_duration_delta_count")
    |> expect_optional_non_negative_integer(path, summary, "counteroffer_lock_deadline_count")
    |> expect_optional_number(path, summary, "counteroffer_cost_delta_total")
    |> expect_optional_number(path, summary, "earliest_counteroffer_lock_deadline_s")
    |> expect_optional_type(path, summary, "counteroffer_status_counts", :map)
    |> validate_non_negative_integer_count_map(
      path <> ".counteroffer_status_counts",
      Map.get(summary, "counteroffer_status_counts")
    )
    |> expect_optional_type(path, summary, "required_operator_action_counts", :map)
    |> validate_non_negative_integer_count_map(
      path <> ".required_operator_action_counts",
      Map.get(summary, "required_operator_action_counts")
    )
    |> expect_optional_non_negative_integer(path, summary, "plan_impact_summary_count")
    |> expect_optional_non_negative_integer(path, summary, "import_readiness_summary_count")
    |> validate_non_negative_integer_count_map(
      path <> ".plan_impact_status_counts",
      Map.get(summary, "plan_impact_status_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".import_readiness_status_counts",
      Map.get(summary, "import_readiness_status_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".import_classification_counts",
      Map.get(summary, "import_classification_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".provider_counteroffer_import_status_counts",
      Map.get(summary, "provider_counteroffer_import_status_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".counteroffer_lock_deadline_status_counts",
      Map.get(summary, "counteroffer_lock_deadline_status_counts")
