  defp validate_manifest_field_reference_rows(issues, path, artifact) do
    case Map.get(artifact, "fields") do
      fields when is_list(fields) ->
        row_paths =
          fields
          |> Enum.filter(&is_map/1)
          |> Enum.map(&Map.get(&1, "path"))
          |> Enum.filter(&is_binary/1)

        path_set = MapSet.new(row_paths)
        rows_by_path = Map.new(Enum.filter(fields, &is_map/1), &{Map.get(&1, "path"), &1})

        issues
        |> expect_field_equals(path, artifact, "field_count", length(fields))
        |> validate_manifest_field_reference_duplicate_paths(path, row_paths)
        |> validate_manifest_field_reference_top_level_required(path, artifact, rows_by_path)
        |> validate_manifest_field_reference_activation_sections(path, artifact, rows_by_path)
        |> validate_manifest_field_reference_supported_vocabularies(
          path,
          artifact,
          rows_by_path
        )
        |> validate_manifest_field_reference_row_integrity(path, fields, path_set)

      _fields ->
        issues
    end
  end

  defp validate_manifest_field_reference_row_integrity(issues, path, fields, path_set) do
    fields
    |> Enum.with_index()
    |> Enum.reduce(issues, fn
      {%{} = row, index}, acc ->
        row_path = "#{path}.fields[#{index}]"

        acc
        |> require_fields(row_path, row, [
          "path",
          "parent_path",
          "section",
          "type",
          "required",
          "array_item"
        ])
        |> expect_type(row_path, row, "path", :binary)
        |> expect_type(row_path, row, "parent_path", :binary)
        |> expect_type(row_path, row, "section", :binary)
        |> validate_manifest_field_reference_row_type(row_path, row)
        |> expect_type(row_path, row, "required", :boolean)
        |> expect_type(row_path, row, "array_item", :boolean)
        |> validate_manifest_field_reference_parent_path(row_path, row, path_set)
        |> validate_manifest_field_reference_section(row_path, row)
        |> validate_manifest_field_reference_array_item(row_path, row)

      {_row, index}, acc ->
        [error("#{path}.fields[#{index}]", "must be an object") | acc]
    end)
  end

  defp validate_manifest_field_reference_duplicate_paths(issues, path, row_paths) do
    row_paths
    |> Enum.frequencies()
    |> Enum.filter(fn {_row_path, count} -> count > 1 end)
    |> Enum.reduce(issues, fn {duplicate_path, _count}, acc ->
      [error("#{path}.fields", "contains duplicate field path #{inspect(duplicate_path)}") | acc]
    end)
  end

  defp validate_manifest_field_reference_top_level_required(
         issues,
         path,
         artifact,
         rows_by_path
       ) do
    case Map.get(artifact, "top_level_required") do
      fields when is_list(fields) ->
        issues
        |> validate_manifest_field_reference_top_level_required_fields(
          path,
          fields,
          rows_by_path
        )
        |> expect_string_list_set_equals(
          path <> ".top_level_required",
          fields,
          manifest_field_reference_top_level_required(rows_by_path),
          "must equal row-derived top-level required fields"
        )

      _fields ->
        issues
    end
  end

  defp validate_manifest_field_reference_top_level_required_fields(
         issues,
         path,
         fields,
         rows_by_path
       ) do
    fields
    |> Enum.with_index()
    |> Enum.reduce(issues, fn
      {field, index}, acc when is_binary(field) ->
        validate_manifest_field_reference_top_level_required_field(
          acc,
          path,
          index,
          field,
          rows_by_path
        )

      {_field, index}, acc ->
        [error("#{path}.top_level_required[#{index}]", "must be a string") | acc]
    end)
  end

  defp manifest_field_reference_top_level_required(rows_by_path) do
    rows_by_path
    |> Map.values()
    |> Enum.filter(&(Map.get(&1, "parent_path") == "$" and Map.get(&1, "required") == true))
    |> Enum.map(&(&1 |> Map.fetch!("path") |> String.trim_leading("$.")))
    |> Enum.sort()
  end

  defp validate_manifest_field_reference_top_level_required_field(
         issues,
         path,
         index,
         field,
         rows_by_path
       ) do
    row = Map.get(rows_by_path, "$.#{field}")

    cond do
      not is_map(row) ->
        [
          error("#{path}.top_level_required[#{index}]", "must reference a top-level field")
          | issues
        ]

      Map.get(row, "parent_path") != "$" ->
        [
          error("#{path}.top_level_required[#{index}]", "must reference a top-level field")
          | issues
        ]

      Map.get(row, "required") != true ->
        [
          error("#{path}.top_level_required[#{index}]", "must reference a required field row")
          | issues
        ]

      true ->
        issues
    end
  end

  defp validate_manifest_field_reference_activation_sections(issues, path, artifact, rows_by_path) do
    case Map.get(artifact, "activation_sections") do
      sections when is_list(sections) ->
        validate_manifest_field_reference_activation_section_entries(
          issues,
          path,
          sections,
          rows_by_path
        )

      _sections ->
        issues
    end
  end

  defp validate_manifest_field_reference_activation_section_entries(
         issues,
         path,
         sections,
         rows_by_path
       ) do
    sections
    |> Enum.with_index()
    |> Enum.reduce(issues, fn
      {section, index}, acc when is_binary(section) ->
        validate_manifest_field_reference_activation_section(
          acc,
          path,
          index,
          section,
          rows_by_path
        )

      {_section, index}, acc ->
        [error("#{path}.activation_sections[#{index}]", "must be a string") | acc]
    end)
  end

  defp validate_manifest_field_reference_activation_section(
         issues,
         path,
         index,
         section,
         rows_by_path
       ) do
    row = Map.get(rows_by_path, "$.#{section}")

    cond do
      not is_map(row) ->
        [
          error("#{path}.activation_sections[#{index}]", "must reference a top-level field")
          | issues
        ]

      Map.get(row, "parent_path") != "$" ->
        [
          error("#{path}.activation_sections[#{index}]", "must reference a top-level field")
          | issues
        ]

      Map.get(row, "section") != section ->
        [
          error("#{path}.activation_sections[#{index}]", "must match the activated field section")
          | issues
        ]

      true ->
        issues
    end
  end

  defp validate_manifest_field_reference_supported_vocabularies(
         issues,
         path,
         artifact,
         rows_by_path
       ) do
    supported = Map.get(artifact, "supported", %{})

    issues
    |> validate_manifest_field_reference_supported_enum(
      "#{path}.supported",
      supported,
      "outputs",
      Map.get(rows_by_path, "$.outputs.[]")
    )
    |> validate_manifest_field_reference_supported_enum(
      "#{path}.supported",
      supported,
      "propagators",
      Map.get(rows_by_path, "$.propagator")
    )
    |> validate_manifest_field_reference_supported_enum(
      "#{path}.supported",
      supported,
      "search_objectives",
      Map.get(rows_by_path, "$.search.objective")
    )
    |> validate_manifest_field_reference_supported_enum(
      "#{path}.supported",
      supported,
      "search_objectives",
      Map.get(rows_by_path, "$.monte_carlo.objective")
    )
  end

  defp validate_manifest_field_reference_supported_enum(issues, path, supported, field, row)
       when is_map(supported) and is_map(row) do
    case {Map.get(supported, field), Map.get(row, "enum")} do
      {values, enum_values} when is_list(values) and is_list(enum_values) ->
        cond do
          not Enum.all?(values, &is_binary/1) ->
            [error("#{path}.#{field}", "must be a list of strings") | issues]

          Enum.sort(values) == Enum.sort(enum_values) ->
            issues

          true ->
            [error("#{path}.#{field}", "must match manifest schema enum values") | issues]
        end

      {values, _enum_values} when is_list(values) ->
        [error("#{path}.#{field}", "must have matching manifest field enum evidence") | issues]

      {_values, _enum_values} ->
        [error("#{path}.#{field}", "must be a list") | issues]
    end
  end

  defp validate_manifest_field_reference_supported_enum(issues, path, supported, field, _row)
       when is_map(supported) do
    [error("#{path}.#{field}", "must have matching manifest field enum evidence") | issues]
  end

  defp validate_manifest_field_reference_supported_enum(issues, _path, _supported, _field, _row) do
    issues
  end

  defp expect_string_list_set_equals(issues, path, values, expected, message) do
    cond do
      not is_list(values) ->
        issues

      Enum.any?(values, &(not is_binary(&1))) ->
        issues

      Enum.sort(values) == Enum.sort(expected) ->
        issues

      true ->
        [error(path, message) | issues]
    end
  end

  defp validate_manifest_field_reference_row_type(issues, path, row) do
    case Map.get(row, "type") do
      type when is_binary(type) ->
        issues

      types when is_list(types) ->
        if Enum.all?(types, &is_binary/1) do
          issues
        else
          [error("#{path}.type", "must be a string or list of strings") | issues]
        end

      _type ->
        [error("#{path}.type", "must be a string or list of strings") | issues]
    end
  end

  defp validate_manifest_field_reference_parent_path(issues, path, row, path_set) do
    case {Map.get(row, "path"), Map.get(row, "parent_path")} do
      {row_path, "$"} when is_binary(row_path) ->
        issues

      {_row_path, parent_path} when is_binary(parent_path) ->
        if MapSet.member?(path_set, parent_path) do
          issues
        else
          [error("#{path}.parent_path", "must reference another field path or $") | issues]
        end

      _values ->
        issues
    end
  end

  defp validate_manifest_field_reference_section(issues, path, row) do
    case {Map.get(row, "path"), Map.get(row, "section")} do
      {row_path, section} when is_binary(row_path) and is_binary(section) ->
        expected_section =
          row_path
          |> String.trim_leading("$.")
          |> String.split(".", parts: 2)
          |> List.first()

        if section == expected_section do
          issues
        else
          [error("#{path}.section", "must match the top-level field section") | issues]
        end

      _values ->
        issues
    end
  end

  defp validate_manifest_field_reference_array_item(issues, path, row) do
    case {Map.get(row, "path"), Map.get(row, "array_item")} do
      {row_path, array_item?} when is_binary(row_path) and is_boolean(array_item?) ->
        if array_item? == String.ends_with?(row_path, ".[]") do
          issues
        else
          [error("#{path}.array_item", "must match whether path ends with .[]") | issues]
        end

      _values ->
        issues
    end
  end

  defp require_accepted_planning_state_import_trust_boundary(issues, artifact) do
    provenance = Map.get(artifact, "provenance")

    import_context_fields = [
      "input_format",
      "import_adapter",
      "provider",
      "adapter",
      "adapter_version"
    ]

    has_import_context? =
      is_map(provenance) and
        Enum.any?(import_context_fields, fn field ->
          value = Map.get(provenance, field)
          is_binary(value) and value != ""
        end)

    trust_boundary = if is_map(provenance), do: Map.get(provenance, "trust_boundary")

    cond do
      not has_import_context? ->
        issues

      is_binary(trust_boundary) and trust_boundary != "" ->
        issues

      true ->
        [
          error(
            "$.provenance.trust_boundary",
            "accepted_planning_state.v1 import provenance requires trust_boundary"
          )
          | issues
        ]
    end
  end

  defp validate_result_artifact_nested(issues, artifact) do
    issues =
      case Map.get(artifact, "execution_report") do
        %{} = execution_report ->
          validate_contract(@execution_report, @contracts[@execution_report], execution_report) ++
            issues

        _value ->
          issues
      end

    issues
    |> validate_result_payload_metrics(artifact)
    |> validate_rows(
      "$.ground_track_crossings",
      Map.get(artifact, "ground_track_crossings", []),
      &validate_result_ground_track_crossing/3
    )
  end

  defp validate_result_payload_metrics(issues, %{"payload_metrics" => %{} = metrics} = artifact) do
    issues
    |> require_fields("$.payload_metrics", metrics, [
      "schema_contract",
      "artifact_body_bytes",
      "top_level_key_count",
      "sections"
    ])
    |> expect_equal(
      "$.payload_metrics",
      metrics,
      "schema_contract",
      "result_payload_metrics.v1"
    )
    |> expect_non_negative_integer("$.payload_metrics", metrics, "artifact_body_bytes")
    |> expect_non_negative_integer("$.payload_metrics", metrics, "top_level_key_count")
    |> expect_type("$.payload_metrics", metrics, "sections", :map)
    |> validate_result_payload_metrics_counts(artifact, metrics)
  end

  defp validate_result_payload_metrics(issues, _artifact), do: issues

  defp validate_result_payload_metrics_counts(issues, artifact, metrics) do
    expected_section_keys =
      artifact
      |> Map.delete("payload_metrics")
      |> Map.keys()
      |> Enum.sort()

    sections = Map.get(metrics, "sections")

    issues
    |> expect_field_equals(
      "$.payload_metrics",
      metrics,
      "top_level_key_count",
      length(expected_section_keys),
      "must equal top-level artifact key count excluding payload_metrics"
    )
    |> validate_result_payload_metric_section_keys(sections, expected_section_keys)
    |> validate_result_payload_metric_sections(sections)
  end

  defp validate_result_payload_metric_section_keys(issues, sections, expected_section_keys)
       when is_map(sections) do
    section_keys =
      sections
      |> Map.keys()
      |> Enum.sort()

    if section_keys == expected_section_keys do
      issues
    else
      [
        error(
          "$.payload_metrics.sections",
          "must contain one section per top-level artifact key excluding payload_metrics"
        )
        | issues
      ]
    end
  end

  defp validate_result_payload_metric_section_keys(issues, _sections, _expected_section_keys),
    do: issues

  defp validate_result_payload_metric_sections(issues, sections) when is_map(sections) do
    Enum.reduce(sections, issues, fn
      {section, %{} = metrics}, acc ->
        acc
        |> expect_non_negative_integer("$.payload_metrics.sections.#{section}", metrics, "bytes")
        |> expect_optional_non_negative_integer(
          "$.payload_metrics.sections.#{section}",
          metrics,
          "row_count"
        )

      {section, _metrics}, acc ->
        [error("$.payload_metrics.sections.#{section}", "must be an object") | acc]
    end)
  end

  defp validate_result_payload_metric_sections(issues, _sections), do: issues

