  defp validate_candidate_activity_score(issues, path, %{"score" => score, "score_terms" => terms})
       when is_number(score) and is_map(terms) do
    numeric_terms = Enum.filter(Map.values(terms), &is_number/1)

    if length(numeric_terms) == map_size(terms) do
      expected_score = Enum.sum(numeric_terms)

      if abs(score - expected_score) <= 1.0e-9 do
        issues
      else
        [
          error(
            path <> ".score",
            "must equal numeric score_terms sum"
          )
          | issues
        ]
      end
    else
      issues
    end
  end

  defp validate_candidate_activity_score(issues, _path, _activity), do: issues

