  defp require_activity_type_alias(issues, path, activity) do
    cond do
      present_string?(Map.get(activity, "type")) ->
        issues

      present_string?(Map.get(activity, "activity_type")) ->
        issues

      true ->
        [error(path, "must include type or activity_type") | issues]
    end
