  defp validate_refreshed_windows(issues, _refreshed_windows), do: issues

  defp validate_refreshed_window(issues, path, window) do
    issues
    |> require_fields(path, window, ["id", "type", "scenario_id", "starts_at_s", "ends_at_s"])
    |> validate_stable_ids(path, window, ["id", "scenario_id", "target_id", "ground_station_id"])
    |> expect_number(path, window, "starts_at_s")
    |> expect_number(path, window, "ends_at_s")
    |> expect_optional_non_negative_integer(path, window, "sample_count")
    |> expect_optional_type(path, window, "assumptions", :map)
    |> validate_refreshed_window_assumptions(path, window)
    |> validate_interval(path, window)
    |> validate_refreshed_window_sample_coverage(path, window)
  end

  defp validate_refreshed_window_assumptions(issues, path, %{
         "assumptions" => %{} = assumptions
       }) do
    issues
    |> expect_optional_number(path <> ".assumptions", assumptions, "event_time_tolerance_s")
    |> expect_optional_number(path <> ".assumptions", assumptions, "max_sample_step_s")
    |> expect_optional_type(path <> ".assumptions", assumptions, "event_detector", :binary)
    |> expect_optional_type(path <> ".assumptions", assumptions, "event_timing_policy", :binary)
  end

  defp validate_refreshed_window_assumptions(issues, _path, _window), do: issues

  defp validate_refreshed_window_sample_coverage(
         issues,
         path,
         %{
           "starts_at_s" => starts_at_s,
           "ends_at_s" => ends_at_s,
           "sample_count" => sample_count,
           "assumptions" => %{"max_sample_step_s" => max_sample_step_s}
         }
       )
       when is_number(starts_at_s) and is_number(ends_at_s) and is_integer(sample_count) and
              is_number(max_sample_step_s) do
    duration_s = ends_at_s - starts_at_s

    if duration_s > max(sample_count, 0) * max_sample_step_s + 1.0e-9 do
      [
        error(
          path <> ".sample_count",
          "must cover window duration using assumptions.max_sample_step_s"
        )
        | issues
      ]
    else
      issues
    end
  end

  defp validate_refreshed_window_sample_coverage(issues, _path, _window), do: issues

  defp validate_contact_intent(issues, path, intent) do
    issues
    |> require_fields(path, intent, [
      "schema_contract",
      "id",
      "activity_id",
      "scenario_id",
      "ground_station_id",
      "direction",
      "starts_at_s",
      "ends_at_s"
    ])
    |> validate_stable_ids(path, intent, [
      "id",
      "activity_id",
      "scenario_id",
      "spacecraft_id",
      "timeline_id",
      "ground_station_id",
      "source_window_id"
    ])
    |> expect_equal(path, intent, "schema_contract", "contact_intent.v1")
    |> expect_one_of(path, intent, "direction", [
      "downlink",
      "uplink",
      "command",
      "tracking",
      "health_check"
    ])
    |> expect_number(path, intent, "starts_at_s")
    |> expect_number(path, intent, "ends_at_s")
    |> expect_optional_probability(path, intent, "capacity_fraction")
    |> expect_optional_probability(path, intent, "capacity_fraction_min")
    |> expect_optional_probability(path, intent, "capacity_fraction_max")
    |> expect_optional_non_negative_integer(path, intent, "station_calendar_overlap_count")
    |> expect_optional_type(path, intent, "station_calendar_overlap_entry_ids", :list)
    |> validate_optional_stable_id_list(path, intent, "station_calendar_overlap_entry_ids")
    |> expect_optional_non_negative_integer(
      path,
      intent,
      "station_calendar_ambiguous_entry_count"
    )
    |> expect_optional_type(path, intent, "station_calendar_ambiguous_entry_ids", :list)
    |> validate_optional_stable_id_list(path, intent, "station_calendar_ambiguous_entry_ids")
    |> expect_optional_non_negative_integer(
      path,
      intent,
      "station_calendar_reservation_overlap_count"
    )
    |> expect_optional_type(path, intent, "station_calendar_reservation_ids", :list)
    |> validate_optional_stable_id_list(path, intent, "station_calendar_reservation_ids")
    |> expect_optional_non_negative_integer(path, intent, "timeline_integrity_issue_count")
    |> expect_optional_type(path, intent, "timeline_integrity_issue_types", :list)
    |> validate_string_list_allowed(
      path,
      intent,
      "timeline_integrity_issue_types",
