  defp validate_contact_filter_report_model_limits(issues, path, report) do
    case Map.get(report, "model_limits") do
      nil ->
        issues

      :null ->
        issues

      limits when is_list(limits) ->
        if limits == contact_filter_report_model_limits() do
          issues
        else
          [
            error("#{path}.model_limits", "must match contact filter report model limits")
            | issues
          ]
        end

      _value ->
        issues
    end
  end

