  defp validate_contact_allocation_capacity_pack_group(issues, path, group) do
    issues
    |> validate_stable_ids(path, group, ["contention_group_id", "ground_station_id"])
    |> expect_optional_probability(path, group, "capacity_fraction")
    |> expect_optional_probability(path, group, "used_capacity_fraction")
    |> expect_optional_probability(path, group, "unused_capacity_fraction")
    |> expect_optional_probability(path, group, "default_required_capacity_fraction")
    |> expect_optional_type(path, group, "input_contact_ids", :list)
    |> expect_optional_type(path, group, "selected_contact_ids", :list)
    |> expect_optional_type(path, group, "capacity_packed_contact_ids", :list)
    |> expect_optional_type(path, group, "deferred_contact_ids", :list)
    |> expect_optional_type(path, group, "capacity_requirement_rows", :list)
    |> validate_stable_id_list(
      path <> ".input_contact_ids",
      Map.get(group, "input_contact_ids")
    )
    |> validate_stable_id_list(
      path <> ".selected_contact_ids",
      Map.get(group, "selected_contact_ids")
    )
    |> validate_stable_id_list(
      path <> ".capacity_packed_contact_ids",
      Map.get(group, "capacity_packed_contact_ids")
    )
    |> validate_stable_id_list(
      path <> ".deferred_contact_ids",
      Map.get(group, "deferred_contact_ids")
    )
    |> validate_contact_allocation_capacity_pack_group_derived_fields(path, group)
    |> validate_optional_rows(
      path <> ".capacity_requirement_rows",
      Map.get(group, "capacity_requirement_rows"),
      &validate_contact_allocation_capacity_requirement_row/3
    )
  end

  defp validate_contact_allocation_capacity_requirement_row(issues, path, row) do
    issues
    |> require_fields(path, row, [
      "contact_id",
      "required_capacity_fraction",
      "required_capacity_fraction_source"
    ])
    |> validate_stable_ids(path, row, ["contact_id"])
    |> expect_optional_type(path, row, "allocation_status", :binary)
    |> expect_optional_type(path, row, "allocation_reason", :binary)
    |> expect_optional_type(path, row, "capacity_pack_status", :binary)
    |> expect_number(path, row, "required_capacity_fraction")
    |> expect_probability_range(path, row, "required_capacity_fraction")
    |> expect_type(path, row, "required_capacity_fraction_source", :binary)
  end

  defp validate_contact_allocation_capacity_pack_group_derived_fields(issues, path, group) do
    rows = Map.get(group, "capacity_requirement_rows")

    issues
    |> expect_field_equals(
      path,
      group,
      "selected_contact_ids",
      capacity_pack_contact_ids(rows, "selected_by_contention_resolution"),
      "must equal capacity requirement rows selected contact IDs"
    )
    |> expect_field_equals(
      path,
      group,
      "capacity_packed_contact_ids",
      capacity_pack_contact_ids(rows, "selected_by_reduced_station_capacity_pack"),
      "must equal capacity requirement rows packed contact IDs"
    )
    |> expect_field_equals(
      path,
      group,
      "deferred_contact_ids",
      capacity_pack_contact_ids(rows, "deferred_by_reduced_station_capacity_pack"),
      "must equal capacity requirement rows deferred contact IDs"
    )
    |> expect_number_field_equals(
      path,
      group,
      "used_capacity_fraction",
      capacity_pack_used_capacity_fraction(rows),
      "must equal capacity requirement rows selected capacity"
    )
    |> expect_number_field_equals(
      path,
      group,
      "unused_capacity_fraction",
      capacity_pack_unused_capacity_fraction(group, rows),
      "must equal capacity minus selected capacity"
    )
  end

  defp capacity_pack_contact_ids(rows, status) when is_list(rows) do
    rows
    |> Enum.filter(&(Map.get(&1, "capacity_pack_status") == status))
    |> Enum.map(&Map.get(&1, "contact_id"))
    |> Enum.reject(&is_nil/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp capacity_pack_contact_ids(_rows, _status), do: nil

  defp capacity_pack_used_capacity_fraction(rows) when is_list(rows) do
    rows
    |> Enum.filter(fn row ->
      Map.get(row, "capacity_pack_status") in [
        "selected_by_contention_resolution",
        "selected_by_reduced_station_capacity_pack"
      ]
    end)
    |> Enum.map(&Map.get(&1, "required_capacity_fraction"))
    |> Enum.reduce(0.0, fn
      value, acc when is_number(value) -> acc + value
      _value, acc -> acc
    end)
  end

  defp capacity_pack_used_capacity_fraction(_rows), do: nil

  defp capacity_pack_unused_capacity_fraction(group, rows) when is_list(rows) do
    capacity_fraction = Map.get(group, "capacity_fraction")
    used_fraction = capacity_pack_used_capacity_fraction(rows)

    if is_number(capacity_fraction) and is_number(used_fraction) do
      max(capacity_fraction - used_fraction, 0.0)
    end
  end

  defp capacity_pack_unused_capacity_fraction(_group, _rows), do: nil

  defp validate_contact_contention_group(issues, path, group) do
    issues
    |> require_fields(path, group, [
      "id",
      "ground_station_id",
      "contact_count",
      "starts_at_s",
      "ends_at_s",
      "direction",
      "required_operator_action",
      "approval_status",
      "contact_ids",
      "source_window_ids",
      "scenario_ids"
    ])
    |> validate_stable_ids(path, group, ["id", "ground_station_id", "spacecraft_id"])
    |> expect_optional_type(path, group, "resource_scope", :binary)
    |> expect_optional_type(path, group, "directions", :list)
    |> validate_string_list_items(path, group, "directions")
    |> expect_optional_type(path, group, "ground_station_ids", :list)
    |> validate_optional_stable_id_list(path, group, "ground_station_ids")
    |> expect_optional_type(path, group, "spacecraft_ids", :list)
    |> validate_optional_stable_id_list(path, group, "spacecraft_ids")
    |> expect_non_negative_integer(path, group, "contact_count")
    |> expect_number(path, group, "starts_at_s")
    |> expect_number(path, group, "ends_at_s")
    |> expect_optional_number(path, group, "contention_window_s")
    |> expect_optional_number(path, group, "total_contact_duration_s")
    |> expect_optional_number(path, group, "overlap_duration_s")
    |> expect_optional_non_negative_integer(path, group, "max_concurrent_contacts")
    |> expect_optional_non_negative_integer(path, group, "overlap_contact_pair_count")
    |> expect_type(path, group, "direction", :binary)
    |> expect_type(path, group, "required_operator_action", :binary)
    |> expect_type(path, group, "approval_status", :binary)
    |> expect_optional_one_of(path, group, "review_status", [
      "operator_review_required",
      "review_required",
      "pending_operator_review",
      "ready_for_review"
    ])
    |> expect_optional_type(path, group, "operator_action_reason", :binary)
    |> expect_optional_number(path, group, "actual_throughput_mb")
    |> expect_optional_type(path, group, "actual_data_rate_throughput_derivations", :list)
    |> validate_optional_actual_data_rate_throughput_derivations(
      path,
      group,
      "actual_data_rate_throughput_derivations"
    )
    |> expect_optional_type(path, group, "station_availability", :binary)
    |> expect_optional_type(path, group, "station_calendar_status", :binary)
    |> expect_optional_type(path, group, "station_calendar_reservation_expires_at_s", :list)
    |> validate_number_list_items(path, group, "station_calendar_reservation_expires_at_s")
    |> expect_optional_probability(path, group, "capacity_fraction")
    |> expect_optional_probability(path, group, "capacity_fraction_min")
    |> expect_optional_probability(path, group, "capacity_fraction_max")
    |> expect_type(path, group, "contact_ids", :list)
    |> expect_type(path, group, "source_window_ids", :list)
    |> expect_type(path, group, "scenario_ids", :list)
    |> expect_optional_non_negative_integer(path, group, "duplicate_contact_candidate_count")
    |> expect_optional_non_negative_integer(path, group, "duplicate_contact_id_count")
    |> expect_optional_type(path, group, "duplicate_contact_ids", :list)
    |> validate_optional_stable_id_list(path, group, "duplicate_contact_ids")
    |> expect_optional_type(path, group, "source_contact_candidates", :list)
    |> validate_optional_rows(
      path <> ".source_contact_candidates",
      Map.get(group, "source_contact_candidates"),
      &validate_contact_contention_source_contact_candidate/3
    )
    |> expect_field_equals(
      path,
      group,
      "contact_count",
      list_count(group, "contact_ids")
    )
    |> expect_field_equals(
      path,
      group,
      "duplicate_contact_id_count",
      list_count(group, "duplicate_contact_ids")
    )
  end

  defp validate_optional_contact_contention_resolution_report(issues, nil), do: issues

  defp validate_optional_contact_contention_resolution_report(issues, %{} = report) do
    issues
    |> validate_contact_contention_resolution_report(
      "$.contact_contention_resolution_report",
      report
    )
  end

  defp validate_optional_contact_contention_resolution_report(issues, _report),
    do: [error("$.contact_contention_resolution_report", "must be an object") | issues]

  defp validate_contact_contention_resolution_report(issues, path, report) do
    issues
    |> require_fields(path, report, [
      "schema_contract",
      "model",
      "policy",
      "conflict_group_count",
      "recommendation_count",
      "recommendations"
    ])
    |> expect_equal(path, report, "schema_contract", "contact_contention_resolution_report.v1")
    |> expect_equal(path, report, "model", "deterministic_contact_contention_recommendation")
    |> expect_type(path, report, "policy", :map)
    |> validate_contact_contention_resolution_policy(path <> ".policy", Map.get(report, "policy"))
    |> expect_non_negative_integer(path, report, "conflict_group_count")
    |> expect_non_negative_integer(path, report, "recommendation_count")
    |> expect_type(path, report, "recommendations", :list)
    |> expect_optional_type(path, report, "assumptions", :map)
    |> expect_optional_type(path, report, "model_limits", :list)
    |> validate_string_list_items(path, report, "model_limits")
    |> validate_contact_contention_resolution_report_model_limits(path, report)
    |> validate_rows(
      path <> ".recommendations",
      Map.get(report, "recommendations", []),
      &validate_contact_contention_recommendation/3
    )
    |> validate_contact_contention_resolution_report_counts(path, report)
  end

  defp validate_contact_contention_resolution_report_model_limits(issues, path, report) do
    case Map.get(report, "model_limits") do
      nil ->
        issues

      :null ->
        issues

      limits when is_list(limits) ->
        if limits == contact_contention_report_model_limits() do
          issues
        else
          [
            error(
              "#{path}.model_limits",
              "must match contact contention resolution report model limits"
            )
            | issues
          ]
        end

      _value ->
        issues
    end
  end

  defp validate_contact_contention_resolution_report_counts(issues, path, report) do
    recommendations =
      report
      |> Map.get("recommendations", [])
      |> Enum.filter(&is_map/1)

    issues
    |> expect_field_equals(path, report, "recommendation_count", length(recommendations))
    |> expect_field_equals(
      path,
      report,
      "conflict_group_count",
      length(recommendations),
      "must equal recommendation_count for one recommendation per contention group"
    )
  end

