  defp validate_contact_contention_recommendation_counts(issues, path, recommendation) do
    issues
    |> expect_field_equals(
      path,
      recommendation,
      "candidate_count",
      list_count(recommendation, "source_contact_candidates"),
      "must equal source_contact_candidates count"
    )
    |> expect_field_equals(
      path,
      recommendation,
      "candidate_count",
      contact_contention_selected_deferred_candidate_count(recommendation),
      "must equal selected plus deferred contact count"
    )
  end

  defp contact_contention_selected_deferred_candidate_count(%{
         "selected_contact_id" => selected_contact_id,
         "deferred_contact_ids" => deferred_contact_ids
       })
       when is_binary(selected_contact_id) and is_list(deferred_contact_ids) do
    1 + length(deferred_contact_ids)
  end

  defp contact_contention_selected_deferred_candidate_count(_recommendation), do: nil

