      "must match contact contention resolution summary model limits"
    )
    |> validate_contact_contention_resolution_summary_field_types(path, summary)
    |> expect_type(path, summary, "assumptions", :map)
    |> validate_contact_contention_resolution_summary_assumptions(path, summary)
    |> validate_contact_contention_resolution_summary_counts(path, summary)
  end

  defp validate_contact_contention_resolution_summary_field_types(issues, path, summary) do
    issues =
      Enum.reduce(contact_contention_resolution_summary_count_fields(), issues, fn field, acc ->
        expect_non_negative_integer(acc, path, summary, field)
      end)

    issues =
      Enum.reduce(contact_contention_resolution_summary_count_map_fields(), issues, fn field,
                                                                                       acc ->
        acc
        |> expect_type(path, summary, field, :map)
        |> validate_non_negative_integer_count_map(path <> ".#{field}", Map.get(summary, field))
      end)

    issues =
      Enum.reduce(contact_contention_resolution_summary_stable_id_list_fields(), issues, fn field,
                                                                                            acc ->
        acc
        |> expect_type(path, summary, field, :list)
        |> validate_stable_id_list(path <> ".#{field}", Map.get(summary, field))
      end)

    issues =
      Enum.reduce(contact_contention_resolution_summary_stable_id_array_map_fields(), issues, fn
        field, acc ->
          acc
          |> expect_type(path, summary, field, :map)
          |> validate_stable_id_array_map(path <> ".#{field}", Map.get(summary, field))
      end)

    issues =
      Enum.reduce(
        contact_contention_resolution_summary_optional_number_fields(),
        issues,
        fn field, acc ->
          expect_optional_non_negative_number(acc, path, summary, field)
        end
      )

    Enum.reduce(contact_contention_resolution_summary_optional_number_map_fields(), issues, fn
      field, acc ->
        acc
        |> expect_optional_type(path, summary, field, :map)
        |> validate_non_negative_number_map(path <> ".#{field}", Map.get(summary, field))
    end)
  end

