  defp validate_branch_event_trust_boundary_status_counts(issues, path, row) do
    counts = Map.get(row, "branch_event_trust_boundary_status_counts")

    issues
    |> validate_branch_event_trust_boundary_status_count_map(
      path <> ".branch_event_trust_boundary_status_counts",
      counts
    )
    |> validate_branch_event_trust_boundary_status_count_total(path, row, counts)
  end

  defp validate_branch_event_trust_boundary_status_count_map(issues, path, counts)
       when is_map(counts) do
    Enum.reduce(counts, issues, fn {field, count}, acc ->
      cond do
        field not in ["declared", "missing", "untrusted"] ->
          [error("#{path}.#{inspect(field)}", "must be declared, missing, or untrusted") | acc]

        not is_integer(count) or count < 0 ->
          [error("#{path}.#{field}", "must be a non-negative integer") | acc]

        true ->
          acc
      end
    end)
  end

  defp validate_branch_event_trust_boundary_status_count_map(issues, _path, _counts),
    do: issues

  defp validate_branch_event_trust_boundary_status_count_total(issues, path, row, counts)
       when is_map(counts) do
    case Map.get(row, "branch_event_count") do
      event_count when is_integer(event_count) ->
        count_total =
          counts
          |> Map.values()
          |> Enum.filter(&is_integer/1)
          |> Enum.sum()

        if count_total == event_count do
          issues
        else
          [
            error(
              path <> ".branch_event_trust_boundary_status_counts",
              "must add up to branch_event_count"
            )
            | issues
          ]
        end

      _value ->
        issues
    end
  end

  defp validate_branch_event_trust_boundary_status_count_total(issues, _path, _row, _counts),
    do: issues

