    |> expect_one_of(path, summary, "source_artifact_type", ["station_calendar_report.v1"])
    |> expect_optional_type(path, summary, "source", :binary)
    |> expect_non_negative_integer(path, summary, "affected_contact_count")
    |> expect_one_of(path, summary, "precedence_review_status", ["clear", "review_required"])
