    issues
    |> validate_station_reservation_review_summary_row(path, row)
    |> validate_station_reservation_hold_summary_row_status(path, row)
  end

  defp validate_station_reservation_hold_summary_row_status(issues, path, row) do
    statuses = list_or_empty(Map.get(row, "reservation_statuses"))

    if Enum.any?(statuses, &station_reservation_hold_status?/1) do
      issues
    else
      [error("#{path}.reservation_statuses", "must include a hold reservation status") | issues]
    end
  end

  defp station_reservation_hold_status?(status) when is_binary(status) do
    normalized =
      status
      |> String.trim()
      |> String.downcase()
      |> String.replace(~r/[\s_-]+/, "_")

    normalized == "held" or String.contains?(normalized, "hold")
  end

  defp station_reservation_hold_status?(_status), do: false

  defp validate_station_reservation_hold_summary_counts(issues, path, summary) do
    rows =
      summary
      |> Map.get("review_rows", [])
