  defp validate_realized_activity_metadata_identity(
         issues,
         path,
         %{
           "metadata" => %{} = metadata
         } = activity
       ) do
    issues
    |> expect_field_equals(
      path <> ".metadata",
      metadata,
      "planned_activity_id",
      Map.get(activity, "planned_activity_id"),
      "must match top-level planned_activity_id"
    )
    |> expect_field_equals(
      path <> ".metadata",
      metadata,
      "planned_timeline_id",
      Map.get(activity, "timeline_id"),
      "must match top-level timeline_id"
    )
  end

  defp validate_realized_activity_metadata_identity(issues, _path, _activity), do: issues

  defp require_realized_activity_provider_trust_boundary(issues, path, activity) do
    provider_context_fields = ["provider", "adapter", "adapter_version", "external_id"]

    provider_context? =
      Enum.any?(provider_context_fields, fn field ->
        case Map.get(activity, field) do
          value when is_binary(value) -> value != ""
          _value -> false
        end
      end)

    trust_boundary = Map.get(activity, "trust_boundary")
    provenance_trust_boundary = get_in(activity, ["provenance", "trust_boundary"])

    cond do
      not provider_context? ->
        issues

      Map.get(activity, "external_id") in [nil, ""] ->
        [error(path <> ".external_id", "is required for provider realized feedback") | issues]

      is_binary(trust_boundary) and trust_boundary != "" ->
        issues

      is_binary(provenance_trust_boundary) and provenance_trust_boundary != "" ->
        issues

      true ->
        [
          error(
            path <> ".trust_boundary",
            "provider realized feedback requires trust_boundary or provenance.trust_boundary"
          )
          | issues
        ]
    end
  end

  defp validate_realized_activity_identity_objects(issues, path, activity) do
    issues
    |> validate_identity_object(path, activity, "target", ["id", "target_id"])
    |> validate_identity_object(path, activity, "station", [
      "id",
      "station_id",
      "ground_station_id"
    ])
    |> validate_identity_object(path, activity, "ground_station", [
      "id",
      "station_id",
      "ground_station_id"
    ])
    |> validate_identity_object(path, activity, "spacecraft", [
      "id",
      "spacecraft_id",
      "satellite_id"
    ])
    |> validate_identity_object(path, activity, "satellite", [
      "id",
      "spacecraft_id",
      "satellite_id"
    ])
  end

  defp validate_identity_object(issues, path, activity, field, identity_fields) do
    case Map.get(activity, field) do
      nil ->
        issues

      %{} = identity ->
        validate_stable_ids(issues, "#{path}.#{field}", identity, identity_fields)

      _value ->
        [error("#{path}.#{field}", "must be a map") | issues]
    end
  end

  defp validate_operational_feedback(issues, _path, nil), do: issues
  defp validate_operational_feedback(issues, _path, :null), do: issues

  defp validate_operational_feedback(issues, path, %{} = feedback) do
    issues
    |> validate_operational_feedback_probability_maps(path, feedback, [
      "contact_success_rate",
      "observation_success_rate",
      "image_quality_score",
      "cloud_cover_fraction",
      "blur_score",
      "maneuver_success_rate",
      "command_success_rate",
      "station_throughput_factor"
    ])
    |> validate_operational_feedback_number_maps(path, feedback, [
      "downlink_demand_mb",
      "target_priority_overrides"
    ])
    |> validate_operational_feedback_string_maps(path, feedback, [
      "image_quality_status",
      "image_quality_source"
    ])
    |> validate_operational_feedback_string_list_maps(path, feedback, ["downlink_demand_sources"])
    |> validate_operational_feedback_object_maps(path, feedback, [
      "downlink_demand_context",
      "maneuver_execution_uncertainty",
      "resource_margin_overrides",
      "resource_availability_overrides"
    ])
    |> validate_optional_rows(
      "#{path}.operational_feedback.realized_activities",
      Map.get(feedback, "realized_activities"),
      &validate_realized_activity/3
    )
  end

  defp validate_operational_feedback(issues, path, _feedback),
    do: [error("#{path}.operational_feedback", "must be an object") | issues]

  defp validate_operational_feedback_probability_maps(issues, path, feedback, fields) do
    Enum.reduce(fields, issues, fn field, acc ->
      validate_operational_feedback_map(acc, path, feedback, field, fn entry_path,
                                                                       value,
                                                                       issues ->
        case value do
          value when is_number(value) and value >= 0.0 and value <= 1.0 ->
            issues

          value when is_number(value) ->
            [error(entry_path, "must be between 0.0 and 1.0") | issues]

          _value ->
            [error(entry_path, "must be a number") | issues]
        end
      end)
    end)
  end

  defp validate_operational_feedback_number_maps(issues, path, feedback, fields) do
    Enum.reduce(fields, issues, fn field, acc ->
      validate_operational_feedback_map(acc, path, feedback, field, fn entry_path,
                                                                       value,
                                                                       issues ->
        case value do
          value when is_number(value) and value >= 0.0 ->
            issues

          value when is_number(value) ->
            [error(entry_path, "must be non-negative") | issues]

          _value ->
            [error(entry_path, "must be a number") | issues]
        end
      end)
    end)
  end

  defp validate_operational_feedback_string_maps(issues, path, feedback, fields) do
    Enum.reduce(fields, issues, fn field, acc ->
      validate_operational_feedback_map(acc, path, feedback, field, fn entry_path,
                                                                       value,
                                                                       issues ->
        if is_binary(value) do
          issues
        else
          [error(entry_path, "must be a string") | issues]
        end
      end)
    end)
  end

  defp validate_operational_feedback_string_list_maps(issues, path, feedback, fields) do
    Enum.reduce(fields, issues, fn field, acc ->
      validate_operational_feedback_map(acc, path, feedback, field, fn entry_path,
                                                                       value,
                                                                       issues ->
        cond do
          not is_list(value) ->
            [error(entry_path, "must be an array") | issues]

          Enum.all?(value, &is_binary/1) ->
            issues

          true ->
            [error(entry_path, "must contain only strings") | issues]
        end
      end)
    end)
  end

  defp validate_operational_feedback_object_maps(issues, path, feedback, fields) do
    Enum.reduce(fields, issues, fn field, acc ->
      validate_operational_feedback_map(acc, path, feedback, field, fn entry_path,
                                                                       value,
                                                                       issues ->
        if is_map(value) do
          issues
        else
          [error(entry_path, "must be an object") | issues]
        end
      end)
    end)
  end

  defp validate_operational_feedback_map(issues, path, feedback, field, entry_validator) do
    case Map.get(feedback, field) do
      nil ->
        issues

      :null ->
        issues

      %{} = values ->
        Enum.reduce(values, issues, fn {key, value}, acc ->
          entry_validator.("#{path}.operational_feedback.#{field}.#{key}", value, acc)
        end)

      _value ->
        [error("#{path}.operational_feedback.#{field}", "must be an object") | issues]
    end
  end

  defp validate_timeline_feedback_report(issues, path, report) do
    issues
    |> expect_equal(path, report, "schema_contract", "timeline_feedback_report.v1")
    |> expect_equal(path, report, "model", "planned_vs_realized_activity_reconciliation")
    |> expect_non_negative_integer(path, report, "planned_count")
    |> expect_non_negative_integer(path, report, "realized_count")
    |> expect_non_negative_integer(path, report, "row_count")
    |> expect_type(path, report, "status_counts", :map)
    |> expect_optional_type(path, report, "feedback_kind_counts", :map)
    |> expect_optional_type(path, report, "match_strategy_counts", :map)
    |> expect_optional_type(path, report, "cadence_import_status_counts", :map)
    |> expect_optional_type(path, report, "planned_protection_decision_counts", :map)
    |> expect_optional_non_negative_integer(
      path,
      report,
      "execution_uncertainty_declared_count"
    )
    |> expect_optional_non_negative_integer(path, report, "execution_uncertainty_missing_count")
    |> expect_optional_non_negative_integer(path, report, "operational_feedback_excluded_count")
    |> expect_optional_non_negative_integer(path, report, "ambiguous_timeline_match_count")
    |> expect_optional_non_negative_integer(path, report, "ambiguous_timeline_feedback_count")
    |> expect_optional_non_negative_integer(path, report, "duplicate_realized_match_count")
    |> expect_optional_non_negative_integer(path, report, "duplicate_realized_feedback_count")
    |> expect_optional_type(path, report, "model_limits", :list)
    |> validate_string_list_items(path, report, "model_limits")
    |> validate_optional_exact_model_limits(
      path,
      report,
      timeline_feedback_report_model_limits(),
      "must match timeline feedback report model limits"
    )
    |> expect_optional_type(path, report, "operational_feedback", :map)
    |> validate_operational_feedback(path, Map.get(report, "operational_feedback"))
    |> expect_optional_type(path, report, "operational_feedback_provenance", :map)
    |> expect_optional_type(path, report, "cadence_import_manifest", :map)
    |> expect_type(path, report, "assumptions", :map)
    |> validate_timeline_feedback_report_counts(path, report)
    |> validate_rows(
      path <> ".rows",
      Map.get(report, "rows", []),
      &validate_timeline_feedback_row/3
    )
    |> validate_optional_operator_review_package(Map.get(report, "operator_review_package"))
  end

  defp validate_timeline_feedback_report_counts(issues, path, report) do
    rows =
      report
      |> Map.get("rows", [])
      |> Enum.filter(&is_map/1)

    issues
    |> validate_non_negative_integer_count_map(
      path <> ".status_counts",
      Map.get(report, "status_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".feedback_kind_counts",
      Map.get(report, "feedback_kind_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".match_strategy_counts",
      Map.get(report, "match_strategy_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".cadence_import_status_counts",
      Map.get(report, "cadence_import_status_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".planned_protection_decision_counts",
      Map.get(report, "planned_protection_decision_counts")
    )
    |> expect_field_equals(path, report, "row_count", length(rows))
    |> expect_field_equals(
      path,
      report,
      "status_counts",
      frequency_map(rows, "status"),
      "must equal row-derived status_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "feedback_kind_counts",
      frequency_map(rows, "feedback_kind"),
      "must equal row-derived feedback_kind_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "match_strategy_counts",
      frequency_map(rows, "match_strategy"),
      "must equal row-derived match_strategy_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "cadence_import_status_counts",
      frequency_map(rows, "cadence_import_status"),
      "must equal row-derived cadence_import_status_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "planned_protection_decision_counts",
      frequency_map(rows, "planned_protection_decision"),
      "must equal row-derived planned_protection_decision_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "execution_uncertainty_declared_count",
      Enum.count(rows, &(&1["execution_uncertainty_status"] == "declared"))
    )
    |> expect_field_equals(
      path,
      report,
      "execution_uncertainty_missing_count",
      Enum.count(rows, &(&1["execution_uncertainty_status"] == "missing"))
    )
    |> expect_field_equals(
      path,
      report,
      "operational_feedback_excluded_count",
      Enum.count(rows, &(&1["operational_feedback_excluded"] == true))
    )
    |> expect_field_equals(
      path,
      report,
      "ambiguous_timeline_match_count",
      Enum.count(rows, &(&1["match_strategy"] == "ambiguous_timeline_id"))
    )
    |> expect_field_equals(
      path,
      report,
      "ambiguous_timeline_feedback_count",
      sum_ambiguous_timeline_feedback_count(rows)
    )
    |> expect_field_equals(
      path,
      report,
      "duplicate_realized_match_count",
      Enum.count(rows, &(Map.get(&1, "realized_match_count", 0) > 1))
    )
    |> expect_field_equals(
      path,
      report,
      "duplicate_realized_feedback_count",
      sum_duplicate_realized_feedback_count(rows)
    )
  end

  defp sum_ambiguous_timeline_feedback_count(rows) do
    Enum.reduce(rows, 0, fn row, count ->
      case row["ambiguous_planned_match_count"] do
        match_count when is_integer(match_count) and match_count > 1 -> count + match_count
        _other -> count
      end
    end)
  end

  defp sum_duplicate_realized_feedback_count(rows) do
    Enum.reduce(rows, 0, fn row, count ->
      case row["realized_match_count"] do
        match_count when is_integer(match_count) and match_count > 1 -> count + match_count - 1
        _other -> count
      end
    end)
  end

