  defp validate_maneuver_recommendation(issues, path, maneuver) do
    issues
    |> require_fields(path, maneuver, [
      "schema_contract",
      "id",
      "scenario_id",
      "type",
      "epoch_s",
      "frame",
      "delta_v_km_s",
      "maneuver_model",
      "assumptions"
    ])
    |> validate_stable_ids(path, maneuver, ["id", "scenario_id"])
    |> expect_equal(path, maneuver, "schema_contract", "maneuver_recommendation.v1")
    |> expect_equal(path, maneuver, "type", "impulsive_burn")
    |> expect_number(path, maneuver, "epoch_s")
    |> expect_optional_type(path, maneuver, "epoch_scale", :binary)
    |> expect_type(path, maneuver, "frame", :binary)
    |> expect_number_vector(path <> ".delta_v_km_s", Map.get(maneuver, "delta_v_km_s"))
    |> expect_optional_number(path, maneuver, "delta_v_magnitude_km_s")
    |> validate_maneuver_recommendation_delta_v_magnitude(path, maneuver)
    |> expect_type(path, maneuver, "maneuver_model", :binary)
    |> expect_optional_type(path, maneuver, "validation_level", :binary)
    |> expect_optional_type(path, maneuver, "model_limits", :list)
    |> validate_string_list_items(path, maneuver, "model_limits")
    |> validate_maneuver_recommendation_model_limits(path, maneuver)
    |> expect_type(path, maneuver, "assumptions", :map)
  end

  defp validate_maneuver_recommendation_delta_v_magnitude(issues, path, %{
         "delta_v_km_s" => [x, y, z],
         "delta_v_magnitude_km_s" => magnitude
       })
       when is_number(x) and is_number(y) and is_number(z) and is_number(magnitude) do
    expected = :math.sqrt(x * x + y * y + z * z)

    if abs(magnitude - expected) <= 1.0e-9 do
      issues
    else
      [
        error(
          "#{path}.delta_v_magnitude_km_s",
          "must equal magnitude derived from delta_v_km_s"
        )
        | issues
      ]
    end
  end

  defp validate_maneuver_recommendation_delta_v_magnitude(issues, _path, _maneuver),
    do: issues

  defp validate_maneuver_recommendation_model_limits(issues, path, maneuver) do
    case Map.get(maneuver, "model_limits") do
      nil ->
        issues

      :null ->
        issues

      limits when is_list(limits) ->
        if limits == maneuver_recommendation_model_limits() do
          issues
        else
          [
            error("#{path}.model_limits", "must match maneuver recommendation model limits")
            | issues
          ]
        end

      _value ->
        issues
    end
  end

  defp validate_maneuver_review_report(issues, path, report) do
    issues
    |> expect_equal(path, report, "schema_contract", "maneuver_review_report.v1")
    |> expect_equal(path, report, "model", "artifact_only_maneuver_review_report")
    |> expect_type(path, report, "source", :binary)
    |> validate_stable_ids(path, report, ["source_artifact_id"])
    |> expect_non_negative_integer(path, report, "maneuver_count")
    |> expect_non_negative_integer(path, report, "review_required_count")
    |> expect_number(path, report, "total_delta_v_km_s")
    |> expect_optional_non_negative_integer(path, report, "invalid_maneuver_recommendation_count")
    |> expect_optional_type(path, report, "invalid_maneuver_recommendation_ids", :list)
    |> validate_optional_stable_id_list(path, report, "invalid_maneuver_recommendation_ids")
    |> expect_optional_non_negative_integer(path, report, "execution_uncertainty_declared_count")
    |> expect_optional_non_negative_integer(path, report, "execution_uncertainty_missing_count")
    |> expect_optional_type(path, report, "approval_status_counts", :map)
    |> expect_optional_type(path, report, "required_operator_action_counts", :map)
    |> expect_optional_type(path, report, "model_limits", :list)
    |> validate_string_list_items(path, report, "model_limits")
    |> validate_maneuver_review_report_model_limits(path, report)
    |> expect_type(path, report, "rows", :list)
    |> expect_type(path, report, "assumptions", :map)
    |> validate_maneuver_review_report_counts(path, report)
    |> validate_rows(
      path <> ".rows",
      Map.get(report, "rows", []),
      &validate_maneuver_review_row/3
    )
  end

  defp validate_maneuver_review_report_counts(issues, path, report) do
    rows =
      report
      |> Map.get("rows", [])
      |> Enum.filter(&is_map/1)

    invalid_ids =
      rows
      |> Enum.filter(&(&1["invalid_maneuver_recommendation"] == true))
      |> Enum.map(&Map.get(&1, "maneuver_id"))

    issues
    |> expect_field_equals(path, report, "maneuver_count", length(rows))
    |> expect_field_equals(path, report, "review_required_count", length(rows))
    |> expect_field_equals(
      path,
      report,
      "invalid_maneuver_recommendation_count",
      length(invalid_ids)
    )
    |> expect_field_equals(
      path,
      report,
      "invalid_maneuver_recommendation_ids",
      invalid_ids,
      "must match invalid maneuver recommendation row IDs"
    )
    |> expect_field_equals(
      path,
      report,
      "execution_uncertainty_declared_count",
      Enum.count(rows, &(&1["execution_uncertainty_status"] == "declared"))
    )
    |> expect_field_equals(
      path,
      report,
      "execution_uncertainty_missing_count",
      Enum.count(rows, &(&1["execution_uncertainty_status"] == "missing"))
    )
    |> expect_field_equals(
      path,
      report,
      "total_delta_v_km_s",
      maneuver_review_report_total_delta_v(rows),
      "must equal row-derived total_delta_v_km_s"
    )
    |> expect_field_equals(
      path,
      report,
      "approval_status_counts",
      frequency_map(rows, "approval_status"),
      "must equal row-derived approval_status_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "required_operator_action_counts",
      frequency_map(rows, "required_operator_action"),
      "must equal row-derived required_operator_action_counts"
    )
  end

  defp validate_maneuver_review_report_model_limits(issues, path, report) do
    expect_field_equals(
      issues,
      path,
      report,
      "model_limits",
      maneuver_review_report_model_limits(),
      "must match maneuver review report model limits"
    )
  end

  defp maneuver_review_report_total_delta_v(rows) do
    rows
    |> Enum.map(&Map.get(&1, "delta_v_magnitude_km_s"))
    |> Enum.filter(&is_number/1)
    |> Enum.sum()
  end

