  defp validate_timeline_diff_report_counts(issues, path, report) do
    rows =
      report
      |> Map.get("rows", [])
      |> Enum.filter(&is_map/1)

    issues
    |> validate_non_negative_integer_count_map(
      path <> ".diff_status_counts",
      Map.get(report, "diff_status_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".required_operator_action_counts",
      Map.get(report, "required_operator_action_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".transition_decision_counts",
      Map.get(report, "transition_decision_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".changed_field_counts",
      Map.get(report, "changed_field_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".status_transition_counts",
      Map.get(report, "status_transition_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".approval_transition_counts",
      Map.get(report, "approval_transition_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".status_transition_category_counts",
      Map.get(report, "status_transition_category_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".approval_transition_category_counts",
      Map.get(report, "approval_transition_category_counts")
    )
    |> expect_field_equals(path, report, "row_count", length(rows))
    |> expect_field_equals(
      path,
      report,
      "added_count",
      Enum.count(rows, &(&1["diff_status"] == "added"))
    )
    |> expect_field_equals(
      path,
      report,
      "removed_count",
      Enum.count(rows, &(&1["diff_status"] == "removed"))
    )
    |> expect_field_equals(
      path,
      report,
      "changed_count",
      Enum.count(rows, &(&1["diff_status"] == "changed"))
    )
    |> expect_field_equals(
      path,
      report,
      "unchanged_count",
      Enum.count(rows, &(&1["diff_status"] == "unchanged"))
    )
    |> expect_field_equals(
      path,
      report,
      "review_required_count",
      Enum.count(rows, &(&1["requires_operator_review"] == true))
    )
    |> expect_field_equals(
      path,
      report,
      "diff_status_counts",
      frequency_map(rows, "diff_status"),
      "must equal row-derived diff_status_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "required_operator_action_counts",
      frequency_map(rows, "required_operator_action"),
      "must equal row-derived required_operator_action_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "transition_decision_counts",
      frequency_map(rows, "transition_decision"),
      "must equal row-derived transition_decision_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "changed_field_counts",
      changed_field_frequency_map(rows),
      "must equal row-derived changed_field_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "status_transition_counts",
      nested_frequency_map(rows, "status_transition", "transition_type"),
      "must equal row-derived status_transition_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "approval_transition_counts",
      nested_frequency_map(rows, "approval_transition", "transition_type"),
      "must equal row-derived approval_transition_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "status_transition_category_counts",
      nested_frequency_map(rows, "status_transition", "transition_category"),
      "must equal row-derived status_transition_category_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "approval_transition_category_counts",
      nested_frequency_map(rows, "approval_transition", "transition_category"),
      "must equal row-derived approval_transition_category_counts"
    )
  end

  defp validate_timeline_diff_row(issues, path, row) do
    issues
    |> require_fields(path, row, [
      "id",
      "rank",
      "timeline_id",
      "diff_status",
      "changed_fields",
      "requires_operator_review",
      "required_operator_action",
      "reason"
    ])
    |> validate_stable_ids(path, row, [
      "id",
      "timeline_id",
      "source_activity_id",
      "replacement_activity_id",
      "scenario_id",
      "source_spacecraft_id",
      "replacement_spacecraft_id",
      "source_ground_station_id",
      "replacement_ground_station_id",
      "source_target_id",
      "replacement_target_id",
      "source_source_window_id",
      "replacement_source_window_id"
    ])
    |> expect_type(path, row, "diff_status", :binary)
    |> expect_one_of(
      path,
      row,
      "diff_status",
      OrbitalDynamics.Timeline.capabilities().timeline_diff_statuses
    )
    |> expect_optional_one_of(
      path,
      row,
      "transition_decision",
      OrbitalDynamics.Timeline.capabilities().transition_decisions
    )
    |> expect_optional_type(path, row, "transition_decision_reason", :binary)
    |> expect_number(path, row, "rank")
    |> expect_type(path, row, "changed_fields", :list)
    |> expect_type(path, row, "requires_operator_review", :boolean)
    |> expect_type(path, row, "required_operator_action", :binary)
    |> expect_one_of(
      path,
      row,
      "required_operator_action",
      OrbitalDynamics.Timeline.capabilities().timeline_diff_required_operator_actions
    )
    |> expect_optional_type(path, row, "operator_action_reason", :binary)
    |> expect_type(path, row, "reason", :binary)
    |> expect_optional_number(path, row, "source_starts_at_s")
    |> expect_optional_number(path, row, "source_ends_at_s")
    |> expect_optional_number(path, row, "replacement_starts_at_s")
    |> expect_optional_number(path, row, "replacement_ends_at_s")
    |> expect_optional_number(path, row, "start_delta_s")
    |> expect_optional_number(path, row, "end_delta_s")
    |> expect_optional_type(path, row, "source_allow_overlap", :boolean)
    |> expect_optional_type(path, row, "replacement_allow_overlap", :boolean)
    |> expect_optional_type(path, row, "status_transition", :map)
    |> expect_optional_type(path, row, "approval_transition", :map)
    |> validate_optional_lifecycle_transition(path, row, "status_transition")
    |> validate_optional_lifecycle_transition(path, row, "approval_transition")
    |> expect_optional_type(path, row, "source_timeline_identity", :map)
    |> expect_optional_type(path, row, "replacement_timeline_identity", :map)
    |> validate_optional_timeline_identity(path, row, "source_timeline_identity")
    |> validate_optional_timeline_identity(path, row, "replacement_timeline_identity")
    |> expect_optional_type(path, row, "source_activity_context", :map)
    |> expect_optional_type(path, row, "replacement_activity_context", :map)
    |> validate_optional_activity_context(path, row, "source_activity_context")
    |> validate_optional_activity_context(path, row, "replacement_activity_context")
    |> expect_optional_type(path, row, "source_protection_category", :binary)
    |> expect_optional_type(path, row, "replacement_protection_category", :binary)
    |> expect_optional_type(path, row, "source_protection_decision", :map)
    |> expect_optional_type(path, row, "replacement_protection_decision", :map)
    |> validate_optional_protection_decision(path, row, "source_protection_decision")
    |> validate_optional_protection_decision(path, row, "replacement_protection_decision")
    |> expect_optional_type(path, row, "source_protection_reason", :binary)
    |> expect_optional_type(path, row, "replacement_protection_reason", :binary)
    |> validate_timeline_identity_collision_fields(path, row)
  end

  defp validate_timeline_diff_summary(issues, path, summary) do
    review_rows =
      summary
      |> Map.get("review_rows", [])
      |> Enum.filter(&is_map/1)

    issues
    |> expect_equal(path, summary, "schema_contract", "timeline_diff_summary.v1")
    |> expect_equal(path, summary, "model", "artifact_only_timeline_diff_summary")
    |> expect_equal(path, summary, "validation_level", "artifact_contract")
    |> expect_equal(path, summary, "source_artifact_type", @timeline_diff_report)
    |> expect_type(path, summary, "source", :binary)
    |> validate_timeline_diff_summary_count_fields(path, summary)
    |> validate_timeline_diff_summary_id_fields(path, summary)
    |> expect_type(path, summary, "review_rows", :list)
    |> expect_type(path, summary, "assumptions", :map)
    |> expect_type(path, summary, "model_limits", :list)
    |> validate_string_list_items(path, summary, "model_limits")
    |> validate_optional_exact_model_limits(
      path,
      summary,
      timeline_report_model_limits(),
      "must match timeline report model limits"
    )
    |> validate_timeline_diff_summary_row_derived_fields(path, summary, review_rows)
    |> validate_rows(
      path <> ".review_rows",
      Map.get(summary, "review_rows", []),
      &validate_timeline_diff_row/3
    )
  end

  defp validate_timeline_diff_summary_count_fields(issues, path, summary) do
    count_fields = [
      "source_activity_count",
      "replacement_activity_count",
      "row_count",
      "added_count",
      "removed_count",
      "changed_count",
      "unchanged_count",
      "review_required_count"
    ]

    optional_count_fields = [
      "duplicate_timeline_identity_count",
      "invalid_source_activity_input_count",
      "invalid_replacement_activity_input_count"
    ]

    count_map_fields = [
      "diff_status_counts",
      "transition_decision_counts",
      "required_operator_action_counts",
      "changed_field_counts",
      "status_transition_category_counts",
      "approval_transition_category_counts"
    ]

    issues =
      Enum.reduce(count_fields, issues, fn field, acc ->
        expect_non_negative_integer(acc, path, summary, field)
      end)

    issues =
      Enum.reduce(optional_count_fields, issues, fn field, acc ->
        expect_optional_non_negative_integer(acc, path, summary, field)
      end)

    Enum.reduce(count_map_fields, issues, fn field, acc ->
      acc
      |> expect_type(path, summary, field, :map)
      |> validate_non_negative_integer_count_map(path <> ".#{field}", Map.get(summary, field))
    end)
  end

  defp validate_timeline_diff_summary_id_fields(issues, path, summary) do
    id_fields = [
      "added_timeline_ids",
      "removed_timeline_ids",
      "changed_timeline_ids",
      "unchanged_timeline_ids",
      "duplicate_timeline_identity_ids",
      "invalid_source_activity_input_ids",
      "invalid_replacement_activity_input_ids",
      "review_timeline_ids"
    ]

    map_fields = [
      "review_timeline_ids_by_required_operator_action",
      "review_timeline_ids_by_status_transition_category",
      "review_timeline_ids_by_approval_transition_category",
      "timeline_ids_by_changed_field"
    ]

    issues =
      Enum.reduce(id_fields, issues, fn field, acc ->
        acc
        |> expect_type(path, summary, field, :list)
        |> validate_optional_stable_id_list(path, summary, field)
      end)

    Enum.reduce(map_fields, issues, fn field, acc ->
      acc
      |> expect_type(path, summary, field, :map)
      |> validate_stable_id_array_map(path <> ".#{field}", Map.get(summary, field))
    end)
  end

  defp validate_timeline_diff_summary_row_derived_fields(issues, path, summary, review_rows) do
    issues
    |> expect_field_equals(
      path,
      summary,
      "review_required_count",
      length(review_rows),
      "must equal row-derived review_required_count"
    )
    |> expect_field_equals(
      path,
      summary,
      "review_timeline_ids",
      timeline_diff_summary_row_ids(review_rows, "timeline_id"),
      "must equal row-derived review_timeline_ids"
    )
    |> expect_field_equals(
      path,
      summary,
      "review_timeline_ids_by_required_operator_action",
      timeline_diff_summary_ids_by_field(review_rows, "required_operator_action"),
      "must equal row-derived review_timeline_ids_by_required_operator_action"
    )
    |> expect_field_equals(
      path,
      summary,
      "review_timeline_ids_by_status_transition_category",
      timeline_diff_summary_ids_by_nested_field(
        review_rows,
        "status_transition",
        "transition_category"
      ),
      "must equal row-derived review_timeline_ids_by_status_transition_category"
    )
    |> expect_field_equals(
      path,
      summary,
      "review_timeline_ids_by_approval_transition_category",
      timeline_diff_summary_ids_by_nested_field(
        review_rows,
        "approval_transition",
        "transition_category"
      ),
      "must equal row-derived review_timeline_ids_by_approval_transition_category"
    )
  end

  defp timeline_diff_summary_row_ids(rows, id_field) do
    rows
    |> Enum.map(&Map.get(&1, id_field))
    |> sorted_unique_binary_values()
  end

  defp timeline_diff_summary_ids_by_field(rows, field) do
    rows
    |> Enum.group_by(&Map.get(&1, field), &Map.get(&1, "timeline_id"))
    |> timeline_diff_summary_id_map()
  end

  defp timeline_diff_summary_ids_by_nested_field(rows, field, nested_field) do
    rows
    |> Enum.group_by(&get_in(&1, [field, nested_field]), &Map.get(&1, "timeline_id"))
    |> timeline_diff_summary_id_map()
  end

  defp timeline_diff_summary_id_map(grouped_ids) do
    grouped_ids
    |> Enum.reject(fn {group, ids} -> group in [nil, ""] or Enum.all?(ids, &is_nil/1) end)
    |> Map.new(fn {group, ids} -> {group, sorted_unique_binary_values(ids)} end)
  end

  defp validate_optional_timeline_diff_summary_source(issues, _path, nil), do: issues

  defp validate_optional_timeline_diff_summary_source(issues, path, %{} = summary),
    do: validate_timeline_diff_summary(issues, path, summary)

  defp validate_optional_timeline_diff_summary_source(issues, path, _summary),
    do: [error(path, "must be an object") | issues]

  defp validate_optional_timeline_publication_summary_source(issues, _path, nil), do: issues

  defp validate_optional_timeline_publication_summary_source(issues, path, %{} = summary),
    do: validate_timeline_publication_summary(issues, path, summary)

  defp validate_optional_timeline_publication_summary_source(issues, path, _summary),
    do: [error(path, "must be an object") | issues]

  defp validate_timeline_publication_handoff_matches_source(issues, path, row) do
    source_summary = Map.get(row, "source_timeline_publication_summary")

    issues
    |> expect_optional_type(path, row, "source_timeline_publication_summary", :map)
    |> validate_optional_timeline_publication_summary_source(
      path <> ".source_timeline_publication_summary",
      source_summary
    )
    |> validate_timeline_publication_handoff_matches_source_summary(path, row, source_summary)
  end

  defp validate_timeline_publication_handoff_matches_source_summary(
         issues,
         path,
         row,
         %{} = source_summary
       ) do
    timeline_publication_handoff_fields()
    |> Enum.reduce(issues, fn field, acc ->
      acc
      |> require_timeline_publication_handoff_field(path, row, source_summary, field)
      |> expect_field_equals(
        path,
        row,
        field,
        Map.get(source_summary, field),
        "must equal source_timeline_publication_summary.#{field}"
      )
    end)
  end

  defp validate_timeline_publication_handoff_matches_source_summary(issues, path, row, _source) do
    if Enum.any?(timeline_publication_unique_handoff_fields(), &Map.has_key?(row, &1)) do
      [
        error(
          path <> ".source_timeline_publication_summary",
          "must be present when timeline publication handoff fields are present"
        )
        | issues
      ]
    else
      issues
    end
  end

  defp require_timeline_publication_handoff_field(issues, path, row, source_summary, field) do
    if Map.has_key?(source_summary, field) and not Map.has_key?(row, field) do
      [
        error(
          "#{path}.#{field}",
          "must be present when source_timeline_publication_summary.#{field} is present"
        )
        | issues
      ]
    else
      issues
    end
  end

