  defp validate_timeline_dependency_impact_row(issues, path, row) do
    issues
    |> require_fields(path, row, [
      "id",
      "scope",
      "dependency_impact_status",
      "required_operator_action",
      "operator_action_reason",
      "activity_id",
      "timeline_id",
      "activity_type"
    ])
    |> validate_stable_ids(path, row, ["id", "activity_id", "timeline_id"])
    |> expect_one_of(path, row, "scope", ["source", "replacement"])
    |> expect_equal(path, row, "dependency_impact_status", "review_required")
    |> expect_one_of(
      path,
      row,
      "required_operator_action",
      OrbitalDynamics.Timeline.capabilities().required_operator_actions
    )
    |> expect_one_of(
      path,
      row,
      "operator_action_reason",
      [
        "dependency_changed_or_removed_source_activity",
        "exclusivity_changed_or_removed_source_activity",
        "dependency_and_exclusivity_changed_or_removed_source_activity"
      ]
    )
    |> expect_type(path, row, "activity_type", :binary)
    |> expect_optional_type(path, row, "status", :binary)
    |> expect_optional_type(path, row, "approval_status", :binary)
    |> validate_timeline_dependency_impact_row_id_lists(path, row)
  end

  defp validate_optional_timeline_dependency_impact_source_row(issues, _path, nil), do: issues

  defp validate_optional_timeline_dependency_impact_source_row(issues, path, %{} = row),
    do: validate_timeline_dependency_impact_row(issues, path, row)

  defp validate_optional_timeline_dependency_impact_source_row(issues, path, _row),
    do: [error(path, "must be an object") | issues]

  defp validate_timeline_dependency_impact_row_id_lists(issues, path, row) do
    [
      "dependency_activity_ids",
      "dependency_timeline_ids",
      "exclusive_with_activity_ids",
      "exclusive_with_timeline_ids",
      "impacted_dependency_activity_ids",
      "impacted_dependency_timeline_ids",
      "impacted_exclusive_with_activity_ids",
      "impacted_exclusive_with_timeline_ids"
    ]
    |> Enum.reduce(issues, fn field, acc ->
      acc
      |> expect_optional_type(path, row, field, :list)
      |> validate_optional_stable_id_list(path, row, field)
    end)
  end

  defp timeline_dependency_impact_row_ids(rows, field) do
    rows
    |> Enum.map(&Map.get(&1, field))
    |> sorted_unique_binary_values()
  end

  defp timeline_dependency_impact_row_ids_by_scope(rows, scope, field) do
    rows
    |> Enum.filter(&(&1["scope"] == scope))
    |> timeline_dependency_impact_row_ids(field)
  end

  defp timeline_dependency_impact_row_list_ids(rows, field) do
    rows
    |> Enum.flat_map(&list_value(&1, field))
    |> sorted_unique_binary_values()
  end

  defp validate_timeline_publication_summary(issues, path, summary) do
    issues
    |> expect_equal(path, summary, "schema_contract", "timeline_publication_summary.v1")
    |> expect_equal(path, summary, "model", "artifact_only_timeline_publication_summary")
    |> expect_equal(path, summary, "validation_level", "artifact_contract")
    |> expect_type(path, summary, "source", :binary)
    |> expect_type(path, summary, "source_artifact_type", :binary)
    |> expect_field_equals(
      path,
      summary,
      "source",
      Map.get(summary, "source_artifact_type"),
      "must equal source_artifact_type"
    )
    |> validate_stable_ids(path, summary, [
      "publication_id",
      "publication_authority",
      "source_artifact_id"
    ])
    |> expect_non_negative_integer(path, summary, "publication_sequence")
    |> expect_one_of(path, summary, "publication_status", [
      "published",
      "published_with_downstream_invalidations",
      "review_required"
    ])
    |> expect_one_of(path, summary, "dependency_impact_status", [
      "clear",
      "not_evaluated",
      "review_required"
    ])
    |> expect_non_negative_integer(path, summary, "dependency_impact_row_count")
    |> validate_timeline_publication_summary_id_fields(path, summary)
    |> expect_type(path, summary, "assumptions", :map)
    |> expect_type(path, summary, "model_limits", :list)
    |> validate_string_list_items(path, summary, "model_limits")
    |> validate_optional_exact_model_limits(
      path,
      summary,
      timeline_report_model_limits(),
      "must match timeline report model limits"
    )
    |> validate_timeline_publication_summary_diff_audit(path, summary)
    |> validate_timeline_publication_summary_derived_fields(path, summary)
  end

  defp validate_timeline_publication_summary_id_fields(issues, path, summary) do
    [
      "supersedes_artifact_ids",
      "downstream_product_ids",
      "invalidated_downstream_product_ids",
      "impacted_dependency_activity_ids",
      "impacted_dependency_timeline_ids",
      "impacted_exclusive_with_activity_ids",
      "impacted_exclusive_with_timeline_ids"
    ]
    |> Enum.reduce(issues, fn field, acc ->
      acc
      |> expect_type(path, summary, field, :list)
      |> validate_optional_stable_id_list(path, summary, field)
    end)
  end

  defp validate_timeline_publication_summary_derived_fields(issues, path, summary) do
    expected_status =
      cond do
        list_value(summary, "invalidated_downstream_product_ids") != [] ->
          "published_with_downstream_invalidations"

        summary["dependency_impact_status"] == "review_required" ->
          "review_required"

        true ->
          "published"
      end

    issues
    |> expect_field_equals(
      path,
      summary,
      "publication_status",
      expected_status,
      "must equal downstream invalidation and dependency impact state"
    )
    |> validate_timeline_publication_summary_dependency_count(path, summary)
    |> validate_timeline_publication_summary_no_impact_without_review(path, summary)
    |> validate_timeline_publication_summary_invalidation_subset(path, summary)
  end

  defp validate_timeline_publication_summary_diff_audit(issues, path, summary) do
    source_summary = Map.get(summary, "source_timeline_diff_summary")

    issues
    |> expect_optional_type(path, summary, "source_timeline_diff_summary", :map)
    |> validate_timeline_publication_summary_diff_audit_count_fields(path, summary)
    |> validate_timeline_publication_summary_diff_audit_routing_fields(path, summary)
    |> validate_optional_timeline_diff_summary_source(
      path <> ".source_timeline_diff_summary",
      source_summary
    )
    |> validate_timeline_publication_summary_diff_audit_source(path, summary, source_summary)
  end

  defp validate_timeline_publication_summary_diff_audit_count_fields(issues, path, summary) do
    count_fields = [
      "timeline_diff_row_count",
      "timeline_diff_changed_count",
      "timeline_diff_review_required_count"
    ]

    issues =
      Enum.reduce(count_fields, issues, fn field, acc ->
        expect_optional_non_negative_integer(acc, path, summary, field)
      end)

    issues
    |> expect_optional_type(path, summary, "changed_field_counts", :map)
    |> validate_non_negative_integer_count_map(
      path <> ".changed_field_counts",
      Map.get(summary, "changed_field_counts")
    )
  end

  defp validate_timeline_publication_summary_diff_audit_routing_fields(issues, path, summary) do
    id_fields = [
      "changed_timeline_ids",
      "review_timeline_ids"
    ]

    issues =
      Enum.reduce(id_fields, issues, fn field, acc ->
        acc
        |> expect_optional_type(path, summary, field, :list)
        |> validate_optional_stable_id_list(path, summary, field)
      end)

    issues
    |> expect_optional_type(path, summary, "timeline_ids_by_changed_field", :map)
    |> validate_stable_id_array_map(
      path <> ".timeline_ids_by_changed_field",
      Map.get(summary, "timeline_ids_by_changed_field")
    )
  end

  defp validate_timeline_publication_summary_diff_audit_source(
         issues,
         path,
         summary,
         %{} = source_summary
       ) do
    issues
    |> require_timeline_publication_summary_diff_audit_fields(path, summary)
    |> expect_field_equals(
      path,
      summary,
      "timeline_diff_row_count",
      Map.get(source_summary, "row_count"),
      "must equal source_timeline_diff_summary.row_count"
    )
    |> expect_field_equals(
      path,
      summary,
      "timeline_diff_changed_count",
      Map.get(source_summary, "changed_count"),
      "must equal source_timeline_diff_summary.changed_count"
    )
    |> expect_field_equals(
      path,
      summary,
      "timeline_diff_review_required_count",
      Map.get(source_summary, "review_required_count"),
      "must equal source_timeline_diff_summary.review_required_count"
    )
    |> expect_field_equals(
      path,
      summary,
      "changed_field_counts",
      Map.get(source_summary, "changed_field_counts"),
      "must equal source_timeline_diff_summary.changed_field_counts"
    )
    |> expect_field_equals(
      path,
      summary,
      "changed_timeline_ids",
      Map.get(source_summary, "changed_timeline_ids"),
      "must equal source_timeline_diff_summary.changed_timeline_ids"
    )
    |> expect_field_equals(
      path,
      summary,
      "review_timeline_ids",
      Map.get(source_summary, "review_timeline_ids"),
      "must equal source_timeline_diff_summary.review_timeline_ids"
    )
    |> expect_field_equals(
      path,
      summary,
      "timeline_ids_by_changed_field",
      Map.get(source_summary, "timeline_ids_by_changed_field"),
      "must equal source_timeline_diff_summary.timeline_ids_by_changed_field"
    )
  end

  defp validate_timeline_publication_summary_diff_audit_source(issues, path, summary, _source) do
    audit_fields = [
      "timeline_diff_row_count",
      "timeline_diff_changed_count",
      "timeline_diff_review_required_count",
      "changed_field_counts",
      "changed_timeline_ids",
      "review_timeline_ids",
      "timeline_ids_by_changed_field"
    ]

    if Enum.any?(audit_fields, &Map.has_key?(summary, &1)) do
      [
        error(
          path <> ".source_timeline_diff_summary",
          "must be present when timeline diff audit fields are present"
        )
        | issues
      ]
    else
      issues
    end
  end

  defp require_timeline_publication_summary_diff_audit_fields(issues, path, summary) do
    [
      "timeline_diff_row_count",
      "timeline_diff_changed_count",
      "timeline_diff_review_required_count",
      "changed_field_counts",
      "changed_timeline_ids",
      "review_timeline_ids",
      "timeline_ids_by_changed_field"
    ]
    |> Enum.reduce(issues, fn field, acc ->
      if Map.has_key?(summary, field) do
        acc
      else
        [
          error(
            "#{path}.#{field}",
            "must be present when source_timeline_diff_summary is present"
          )
          | acc
        ]
      end
    end)
  end

  defp validate_timeline_publication_summary_dependency_count(issues, path, summary) do
    if summary["dependency_impact_status"] in ["clear", "not_evaluated"] do
      expect_field_equals(
        issues,
        path,
        summary,
        "dependency_impact_row_count",
        0,
        "must be zero unless dependency_impact_status is review_required"
      )
    else
      issues
    end
  end

  defp validate_timeline_publication_summary_no_impact_without_review(issues, path, summary) do
    if summary["dependency_impact_status"] in ["clear", "not_evaluated"] do
      [
        "impacted_dependency_activity_ids",
        "impacted_dependency_timeline_ids",
        "impacted_exclusive_with_activity_ids",
        "impacted_exclusive_with_timeline_ids"
      ]
      |> Enum.reduce(issues, fn field, acc ->
        expect_field_equals(
          acc,
          path,
          summary,
          field,
          [],
          "must be empty unless dependency_impact_status is review_required"
        )
      end)
    else
      issues
    end
  end

  defp validate_timeline_publication_summary_invalidation_subset(issues, path, summary) do
    downstream_product_ids =
      case Map.get(summary, "downstream_product_ids") do
        ids when is_list(ids) -> MapSet.new(ids)
        _ids -> MapSet.new()
      end

    case Map.get(summary, "invalidated_downstream_product_ids") do
      ids when is_list(ids) ->
        ids
        |> Enum.with_index()
        |> Enum.reduce(issues, fn {id, index}, acc ->
          if is_binary(id) and not MapSet.member?(downstream_product_ids, id) do
            [
              error(
                "#{path}.invalidated_downstream_product_ids[#{index}]",
                "must be included in downstream_product_ids"
              )
              | acc
            ]
          else
            acc
          end
        end)

      _ids ->
        issues
    end
  end

  defp validate_timeline_activity_state(issues, path, state) do
    rows =
      case Map.get(state, "rows") do
        rows when is_list(rows) -> Enum.filter(rows, &is_map/1)
        _rows -> []
      end

    issues
    |> expect_equal(path, state, "schema_contract", "timeline_activity_state.v1")
    |> expect_equal(path, state, "model", "artifact_only_timeline_activity_state")
    |> expect_equal(path, state, "validation_level", "artifact_contract")
    |> expect_one_of(
      path,
      state,
      "state_status",
      [
        "empty",
        "review_required" | OrbitalDynamics.TimelineFeedback.capabilities().report_statuses
      ]
    )
    |> validate_stable_ids(path, state, [
      "activity_id",
      "timeline_id",
      "planned_timeline_id",
      "realized_timeline_id"
    ])
    |> expect_optional_type(path, state, "activity_ids", :list)
    |> validate_optional_stable_id_list(path, state, "activity_ids")
    |> expect_type(path, state, "review_required", :boolean)
    |> expect_type(path, state, "review_activity_ids", :list)
    |> validate_optional_stable_id_list(path, state, "review_activity_ids")
    |> expect_type(path, state, "rows", :list)
    |> expect_type(path, state, "assumptions", :map)
    |> expect_type(path, state, "model_limits", :list)
    |> validate_string_list_items(path, state, "model_limits")
    |> validate_optional_exact_model_limits(
      path,
      state,
      timeline_feedback_report_model_limits(),
      "must match timeline activity state model limits"
    )
    |> validate_timeline_activity_state_assumptions(path, state, [
      "artifact_only",
      "no_schedule_mutation",
      "no_command_execution"
    ])
    |> expect_optional_type(path, state, "status_transition", :map)
    |> expect_optional_type(path, state, "approval_transition", :map)
    |> validate_optional_lifecycle_transition(path, state, "status_transition")
    |> validate_optional_lifecycle_transition(path, state, "approval_transition")
    |> expect_optional_type(path, state, "planned_status_category", :binary)
    |> expect_optional_type(path, state, "realized_status_category", :binary)
    |> expect_optional_type(path, state, "planned_approval_status", :binary)
    |> expect_optional_type(path, state, "realized_approval_status", :binary)
    |> expect_optional_type(path, state, "planned_approval_category", :binary)
    |> expect_optional_type(path, state, "realized_approval_category", :binary)
    |> expect_optional_type(path, state, "planned_locked", :boolean)
    |> expect_optional_type(path, state, "realized_locked", :boolean)
    |> expect_optional_type(path, state, "planned_executed", :boolean)
    |> expect_optional_type(path, state, "realized_executed", :boolean)
    |> expect_optional_type(path, state, "source_protection_decision", :map)
    |> expect_optional_type(path, state, "realized_protection_decision", :map)
    |> expect_optional_type(path, state, "realized_provider_counts", :map)
    |> expect_optional_type(path, state, "realized_source_quality_counts", :map)
    |> expect_optional_type(path, state, "realized_trust_boundary_status", :binary)
    |> expect_optional_type(path, state, "realized_trust_boundaries", :list)
    |> validate_string_list_items(path, state, "realized_trust_boundaries")
    |> validate_optional_protection_decision(path, state, "source_protection_decision")
    |> validate_optional_protection_decision(path, state, "realized_protection_decision")
    |> expect_optional_type(path, state, "source_activity_context", :map)
    |> expect_optional_type(path, state, "realized_activity_context", :map)
    |> validate_optional_activity_context(path, state, "source_activity_context")
    |> validate_optional_activity_context(path, state, "realized_activity_context")
    |> validate_timeline_activity_state_count_maps(path, state, rows)
    |> expect_field_equals(
      path,
      state,
      "state_status",
      timeline_activity_state_status(rows),
      "must equal row-derived state_status"
    )
    |> expect_field_equals(
      path,
      state,
      "activity_ids",
      timeline_activity_state_ids(rows),
      "must equal row-derived activity_ids"
    )
    |> expect_field_equals(
      path,
      state,
      "review_required",
      timeline_activity_state_review_required?(rows),
      "must equal row-derived review_required"
    )
    |> expect_field_equals(
      path,
      state,
      "review_activity_ids",
      timeline_activity_state_review_ids(rows),
      "must equal row-derived review_activity_ids"
    )
    |> validate_rows(
      path <> ".rows",
      Map.get(state, "rows", []),
      &validate_timeline_feedback_row/3
    )
  end

  defp validate_timeline_activity_state_count_maps(issues, path, state, rows) do
    issues
    |> validate_non_negative_integer_count_map(
      path <> ".status_counts",
      Map.get(state, "status_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".feedback_kind_counts",
      Map.get(state, "feedback_kind_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".match_strategy_counts",
      Map.get(state, "match_strategy_counts")
    )
