    |> expect_field_equals(
      path,
      state,
      "realized_trust_boundaries",
      timeline_activity_state_realized_trust_boundaries(rows),
      "must equal row-derived realized_trust_boundaries"
    )
  end

  defp timeline_activity_state_optional_frequency_map(rows, field) do
    case frequency_map(rows, field) do
      counts when map_size(counts) == 0 -> nil
      counts -> counts
    end
  end

  defp timeline_activity_state_realized_trust_boundary_status(rows) do
    if timeline_activity_state_realized_row_count(rows) == 0 do
      nil
    else
      case timeline_activity_state_realized_trust_boundary_values(rows) do
        [] -> "missing"
        _boundaries -> "declared"
      end
    end
  end

  defp timeline_activity_state_realized_trust_boundaries(rows) do
    case timeline_activity_state_realized_trust_boundary_values(rows) do
      [] -> nil
      boundaries -> boundaries
    end
  end

  defp timeline_activity_state_realized_trust_boundary_values(rows) do
    rows
    |> Enum.map(&Map.get(&1, "realized_trust_boundary"))
    |> Enum.filter(&present_string?/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp timeline_activity_state_realized_row_count(rows) do
    Enum.count(rows, fn row ->
      Map.get(row, "status") in ["matched", "realized_only"] or
        present_string?(Map.get(row, "realized_activity_id")) or
        present_string?(Map.get(row, "realized_status"))
    end)
  end

  defp timeline_activity_state_status([]), do: "empty"
  defp timeline_activity_state_status([%{"status" => status}]), do: status

  defp timeline_activity_state_status(rows) do
    if Enum.any?(rows, &(&1["status"] == "matched")) do
      "matched"
    else
      "review_required"
    end
  end

  defp timeline_activity_state_ids(rows) do
    rows
    |> Enum.map(&Map.get(&1, "activity_id"))
    |> Enum.filter(&(is_binary(&1) and &1 != ""))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp timeline_activity_state_review_required?(rows) do
    Enum.any?(rows, fn row ->
      Map.get(row, "status") != "matched" or
        Map.get(row, "planned_protection_decision") == "review_change" or
        present_timeline_activity_state_review_action?(Map.get(row, "required_operator_action")) or
        present_timeline_activity_state_review_action?(
          get_in(row, ["status_transition", "required_operator_action"])
        )
    end)
  end

  defp timeline_activity_state_review_ids(rows) do
    rows
    |> Enum.filter(&timeline_activity_state_review_required?([&1]))
    |> timeline_activity_state_ids()
  end

  defp present_timeline_activity_state_review_action?(action) when action in [nil, "", "none"],
    do: false

  defp present_timeline_activity_state_review_action?(_action), do: true

  defp validate_timeline_activity_precondition_summary(issues, path, summary) do
    preconditions = timeline_activity_precondition_summary_rows(summary)

    issues
    |> expect_equal(
      path,
      summary,
      "schema_contract",
      "timeline_activity_precondition_summary.v1"
    )
    |> expect_equal(
      path,
      summary,
      "model",
      "artifact_only_timeline_activity_precondition_summary"
    )
    |> expect_equal(path, summary, "validation_level", "artifact_contract")
    |> validate_stable_ids(path, summary, ["activity_id", "timeline_id"])
    |> expect_optional_type(path, summary, "activity_type", :binary)
    |> expect_one_of(
      path,
      summary,
      "precondition_status",
      OrbitalDynamics.Timeline.capabilities().activity_precondition_statuses
    )
    |> expect_optional_non_negative_integer(path, summary, "blocked_precondition_count")
    |> expect_optional_non_negative_integer(path, summary, "review_precondition_count")
    |> expect_optional_type(path, summary, "blocked_precondition_types", :list)
    |> validate_optional_string_list(path, summary, "blocked_precondition_types")
    |> expect_optional_type(path, summary, "review_precondition_types", :list)
    |> validate_optional_string_list(path, summary, "review_precondition_types")
    |> expect_optional_type(path, summary, "preconditions", :list)
    |> validate_optional_timeline_preconditions(path, summary, "preconditions")
    |> validate_timeline_activity_precondition_summary_row_derived_fields(
      path,
      summary,
      preconditions
    )
    |> expect_optional_type(path, summary, "dependency_activity_ids", :list)
    |> validate_optional_stable_id_list(path, summary, "dependency_activity_ids")
    |> expect_optional_type(path, summary, "dependency_timeline_ids", :list)
    |> validate_optional_stable_id_list(path, summary, "dependency_timeline_ids")
    |> expect_optional_type(path, summary, "exclusive_with_activity_ids", :list)
    |> validate_optional_stable_id_list(path, summary, "exclusive_with_activity_ids")
    |> expect_optional_type(path, summary, "exclusive_with_timeline_ids", :list)
    |> validate_optional_stable_id_list(path, summary, "exclusive_with_timeline_ids")
    |> expect_optional_type(path, summary, "allow_overlap", :boolean)
    |> expect_optional_type(path, summary, "timeline_identity", :map)
    |> validate_optional_timeline_identity(path, summary, "timeline_identity")
    |> expect_optional_type(path, summary, "invalid_activity_input", :boolean)
    |> expect_optional_type(path, summary, "invalid_activity_input_reason", :binary)
    |> expect_optional_type(path, summary, "source_activity", :map)
    |> expect_optional_type(path, summary, "assumptions", :map)
  end

  defp validate_optional_timeline_activity_precondition_summary_source(issues, _path, nil),
    do: issues

  defp validate_optional_timeline_activity_precondition_summary_source(
         issues,
         path,
         %{} = summary
       ) do
    validate_timeline_activity_precondition_summary(issues, path, summary)
  end

  defp validate_optional_timeline_activity_precondition_summary_source(issues, path, _summary),
    do: [error(path, "must be an object") | issues]

  defp timeline_activity_precondition_summary_rows(summary) do
    case Map.get(summary, "preconditions", []) do
      rows when is_list(rows) -> Enum.filter(rows, &is_map/1)
      _rows -> []
    end
  end

  defp validate_timeline_activity_precondition_summary_row_derived_fields(
         issues,
         path,
         %{"invalid_activity_input" => true} = summary,
         _preconditions
       ) do
    issues
    |> expect_field_equals(
      path,
      summary,
      "precondition_status",
      "review_required",
      "must be review_required for invalid activity input"
    )
    |> expect_field_equals(
      path,
      summary,
      "blocked_precondition_count",
      0,
      "must equal 0 for invalid activity input"
    )
    |> expect_field_equals(
      path,
      summary,
      "review_precondition_count",
      0,
      "must equal 0 for invalid activity input"
    )
    |> expect_field_equals(
      path,
      summary,
      "blocked_precondition_types",
      [],
      "must equal [] for invalid activity input"
    )
    |> expect_field_equals(
      path,
      summary,
      "review_precondition_types",
      [],
      "must equal [] for invalid activity input"
    )
  end

  defp validate_timeline_activity_precondition_summary_row_derived_fields(
         issues,
         path,
         summary,
         preconditions
       ) do
    issues
    |> expect_field_equals(
      path,
      summary,
      "precondition_status",
      timeline_activity_precondition_summary_status(preconditions),
      "must equal row-derived precondition_status"
    )
    |> expect_field_equals(
      path,
      summary,
      "blocked_precondition_count",
      timeline_activity_precondition_summary_count(preconditions, "blocked"),
      "must equal row-derived blocked_precondition_count"
    )
    |> expect_field_equals(
      path,
      summary,
      "review_precondition_count",
      timeline_activity_precondition_summary_count(preconditions, "review_required"),
      "must equal row-derived review_precondition_count"
    )
    |> expect_field_equals(
      path,
      summary,
      "blocked_precondition_types",
      timeline_activity_precondition_summary_types(preconditions, "blocked"),
      "must equal row-derived blocked_precondition_types"
    )
    |> expect_field_equals(
      path,
      summary,
      "review_precondition_types",
      timeline_activity_precondition_summary_types(preconditions, "review_required"),
      "must equal row-derived review_precondition_types"
    )
  end

  defp timeline_activity_precondition_summary_status(preconditions) do
    cond do
      Enum.any?(preconditions, &(&1["status"] == "blocked")) -> "blocked"
      Enum.any?(preconditions, &(&1["status"] == "review_required")) -> "review_required"
      true -> "clear"
    end
  end

  defp timeline_activity_precondition_summary_count(preconditions, status) do
    Enum.count(preconditions, &(&1["status"] == status))
  end

  defp timeline_activity_precondition_summary_types(preconditions, status) do
    preconditions
    |> Enum.filter(&(&1["status"] == status))
    |> Enum.map(&Map.get(&1, "type"))
    |> sorted_unique_binary_values()
  end

