  defp validate_timeline_activity_lifecycle_state(issues, path, state) do
    status_decision =
      timeline_activity_state_transition_decision(Map.get(state, "status_transition"))

    approval_decision =
      timeline_activity_state_transition_decision(Map.get(state, "approval_transition"))

    protections = [
      Map.get(state, "planned_protection_decision"),
      Map.get(state, "realized_protection_decision")
    ]

    transition_decision =
      timeline_activity_lifecycle_transition_decision(
        status_decision,
        approval_decision,
        protections
      )

    required_operator_actions =
      timeline_activity_lifecycle_required_actions(
        status_decision,
        approval_decision,
        protections,
        transition_decision
      )

    issues
    |> validate_timeline_activity_state_common(
      path,
      state,
      "timeline_activity_lifecycle_state.v1",
      "artifact_only_timeline_activity_lifecycle_state",
      [
        "artifact_only",
        "no_schedule_mutation",
        "no_operator_authority_grant",
        "no_cadence_import",
        "no_command_execution"
      ]
    )
    |> expect_optional_type(path, state, "model_limits", :list)
    |> validate_string_list_items(path, state, "model_limits")
    |> validate_optional_exact_model_limits(
      path,
      state,
      timeline_report_model_limits(),
      "must match timeline report model limits"
    )
    |> expect_optional_one_of(
      path,
      state,
      "status_transition_decision",
      OrbitalDynamics.Timeline.capabilities().transition_decisions
    )
    |> expect_optional_one_of(
      path,
      state,
      "approval_transition_decision",
      OrbitalDynamics.Timeline.capabilities().transition_decisions
    )
    |> expect_optional_type(path, state, "required_operator_actions", :list)
    |> expect_optional_type(path, state, "operator_action_reasons", :list)
    |> validate_optional_string_list(path, state, "required_operator_actions")
    |> validate_optional_string_list(path, state, "operator_action_reasons")
    |> expect_optional_type(path, state, "status_transition", :map)
    |> expect_optional_type(path, state, "approval_transition", :map)
    |> validate_optional_lifecycle_transition(path, state, "status_transition")
    |> validate_optional_lifecycle_transition(path, state, "approval_transition")
    |> expect_optional_type(path, state, "planned_status", :binary)
    |> expect_optional_type(path, state, "realized_status", :binary)
    |> expect_optional_type(path, state, "planned_status_category", :binary)
    |> expect_optional_type(path, state, "realized_status_category", :binary)
    |> expect_optional_type(path, state, "planned_approval_status", :binary)
    |> expect_optional_type(path, state, "realized_approval_status", :binary)
    |> expect_optional_type(path, state, "planned_approval_category", :binary)
    |> expect_optional_type(path, state, "realized_approval_category", :binary)
    |> expect_optional_type(path, state, "planned_activity_context", :map)
    |> expect_optional_type(path, state, "realized_activity_context", :map)
    |> validate_optional_activity_context(path, state, "planned_activity_context")
    |> validate_optional_activity_context(path, state, "realized_activity_context")
    |> expect_optional_type(path, state, "planned_protection_decision", :map)
    |> expect_optional_type(path, state, "realized_protection_decision", :map)
    |> validate_optional_protection_decision(path, state, "planned_protection_decision")
    |> validate_optional_protection_decision(path, state, "realized_protection_decision")
    |> expect_optional_type(path, state, "planned_locked", :boolean)
    |> expect_optional_type(path, state, "realized_locked", :boolean)
    |> expect_optional_type(path, state, "planned_executed", :boolean)
    |> expect_optional_type(path, state, "realized_executed", :boolean)
    |> validate_optional_timeline_activity_invalid_input(path, state)
    |> expect_field_equals(
      path,
      state,
      "status_transition_decision",
      status_decision,
      "must equal status-transition-derived decision"
    )
    |> expect_field_equals(
      path,
      state,
      "approval_transition_decision",
      approval_decision,
      "must equal approval-transition-derived decision"
    )
    |> expect_field_equals(
      path,
      state,
      "transition_decision",
      transition_decision,
      "must equal lifecycle-derived transition_decision"
    )
    |> expect_field_equals(
      path,
      state,
      "review_required",
      transition_decision == "review",
      "must equal lifecycle-derived review_required"
    )
    |> expect_field_equals(
      path,
      state,
      "required_operator_actions",
      required_operator_actions,
      "must equal lifecycle-derived required_operator_actions"
    )
    |> expect_field_equals(
      path,
      state,
      "required_operator_action",
      timeline_activity_lifecycle_required_action(required_operator_actions, transition_decision),
      "must equal lifecycle-derived required_operator_action"
    )
    |> expect_field_equals(
      path,
      state,
      "operator_action_reasons",
      timeline_activity_lifecycle_reasons(state, protections),
      "must equal lifecycle-derived operator_action_reasons"
    )
    |> expect_field_equals(
      path,
      state,
      "import_action",
      timeline_activity_state_import_action(transition_decision),
      "must equal lifecycle-derived import_action"
    )
  end

  defp validate_timeline_activity_state_common(
         issues,
         path,
         state,
         schema_contract,
         model,
         assumption_fields
       ) do
    issues
    |> expect_equal(path, state, "schema_contract", schema_contract)
    |> expect_equal(path, state, "model", model)
    |> expect_equal(path, state, "validation_level", "artifact_contract")
    |> validate_stable_ids(path, state, [
      "activity_id",
      "planned_activity_id",
      "realized_activity_id",
      "timeline_id",
      "planned_timeline_id",
      "realized_timeline_id"
    ])
    |> expect_one_of(
      path,
      state,
      "transition_decision",
      OrbitalDynamics.Timeline.capabilities().transition_decisions
    )
    |> expect_type(path, state, "review_required", :boolean)
    |> expect_type(path, state, "required_operator_action", :binary)
    |> expect_type(path, state, "import_action", :binary)
    |> expect_type(path, state, "assumptions", :map)
    |> validate_timeline_activity_state_assumptions(path, state, assumption_fields)
  end

  defp validate_timeline_activity_state_assumptions(issues, path, state, fields) do
    case Map.get(state, "assumptions") do
      assumptions when is_map(assumptions) ->
        Enum.reduce(fields, issues, fn field, acc ->
          expect_equal(acc, path <> ".assumptions", assumptions, field, true)
        end)

      _assumptions ->
        issues
    end
  end

  defp validate_optional_timeline_activity_invalid_input(issues, path, state) do
    issues
    |> expect_optional_type(path, state, "invalid_activity_input", :boolean)
    |> expect_optional_non_negative_integer(path, state, "invalid_activity_input_count")
    |> expect_optional_type(path, state, "invalid_activity_input_reasons", :list)
    |> validate_optional_string_list(path, state, "invalid_activity_input_reasons")
  end

  defp timeline_activity_state_transition_decision(nil), do: "none"

  defp timeline_activity_state_transition_decision(%{"requires_operator_review" => true}),
    do: "review"

  defp timeline_activity_state_transition_decision(%{}), do: "record"
  defp timeline_activity_state_transition_decision(_transition), do: "none"

  defp timeline_activity_state_reason(nil, fallback), do: fallback

  defp timeline_activity_state_reason(%{"operator_action_reason" => reason}, _fallback),
    do: reason

  defp timeline_activity_state_reason(_transition, fallback), do: fallback

  defp timeline_activity_status_state_action("none"), do: "none"
  defp timeline_activity_status_state_action("review"), do: "review_activity_transition"
  defp timeline_activity_status_state_action("record"), do: "record_timeline_change"

  defp timeline_activity_approval_state_action("none"), do: "none"
  defp timeline_activity_approval_state_action("review"), do: "review_activity_approval"
  defp timeline_activity_approval_state_action("record"), do: "record_timeline_change"

  defp timeline_activity_state_import_action("none"), do: "record_preserved_activity"
  defp timeline_activity_state_import_action("review"), do: "review_timeline_diff"
  defp timeline_activity_state_import_action("record"), do: "import_replacement_activity"

  defp timeline_activity_lifecycle_transition_decision(
         status_decision,
         approval_decision,
         protections
       ) do
    cond do
      status_decision == "review" or approval_decision == "review" or
          timeline_activity_lifecycle_protection_review?(protections) ->
        "review"

      status_decision == "record" or approval_decision == "record" ->
        "record"

      true ->
        "none"
    end
  end

  defp timeline_activity_lifecycle_required_actions(
         status_decision,
         approval_decision,
         protections,
         transition_decision
       ) do
    actions =
      [
        timeline_activity_status_state_action(status_decision),
        timeline_activity_approval_state_action(approval_decision)
      ] ++ timeline_activity_lifecycle_protection_actions(protections)

    actions =
      actions
      |> Enum.reject(&(&1 in [nil, "none"]))
      |> sorted_unique_binary_values()

    case {transition_decision, actions} do
      {"none", []} -> ["none"]
      {"record", []} -> ["record_timeline_change"]
      {_decision, actions} -> actions
    end
  end

  defp timeline_activity_lifecycle_required_action(actions, "review") do
    cond do
      "review_activity_transition" in actions -> "review_activity_transition"
      "review_activity_approval" in actions -> "review_activity_approval"
      "review_timeline_change" in actions -> "review_timeline_change"
      true -> List.first(actions) || "review_activity_transition"
    end
  end

  defp timeline_activity_lifecycle_required_action(_actions, "record"),
    do: "record_timeline_change"

  defp timeline_activity_lifecycle_required_action(_actions, "none"), do: "none"

  defp timeline_activity_lifecycle_reasons(state, protections) do
    [
      timeline_activity_state_reason(Map.get(state, "status_transition"), "no_status_change"),
      timeline_activity_state_reason(
        Map.get(state, "approval_transition"),
        "no_approval_status_change"
      )
    ]
    |> Kernel.++(timeline_activity_lifecycle_protection_reasons(protections))
    |> Enum.reject(&(&1 in [nil, "no_status_change", "no_approval_status_change"]))
    |> sorted_unique_binary_values()
    |> case do
      [] -> nil
      reasons -> reasons
    end
  end

  defp timeline_activity_lifecycle_protection_review?(protections) do
    Enum.any?(protections, fn
      %{"protection_decision" => "review_change"} -> true
      _protection -> false
    end)
  end

  defp timeline_activity_lifecycle_protection_actions(protections) do
    Enum.flat_map(protections, fn
      %{"protection_decision" => "review_change"} -> ["review_timeline_change"]
      _protection -> []
    end)
  end

  defp timeline_activity_lifecycle_protection_reasons(protections) do
    protections
    |> Enum.filter(&(Map.get(&1 || %{}, "protection_decision") == "review_change"))
    |> Enum.map(&Map.get(&1, "reason"))
  end

  defp validate_timeline_preservation_report(issues, path, report) do
    decision_counts = Map.get(report, "protection_decision_counts", %{})
    preserve_count = protection_count(decision_counts, "preserve")
    review_count = protection_count(decision_counts, "review_change")
    mutable_count = protection_count(decision_counts, "mutable")

    issues
    |> expect_equal(path, report, "schema_contract", "timeline_preservation_report.v1")
    |> expect_equal(path, report, "model", "artifact_only_lifecycle_preservation_summary")
    |> expect_type(path, report, "source", :binary)
    |> expect_non_negative_integer(path, report, "activity_count")
    |> expect_non_negative_integer(path, report, "mutable_activity_count")
    |> expect_non_negative_integer(path, report, "preserve_activity_count")
    |> expect_non_negative_integer(path, report, "review_change_activity_count")
    |> expect_non_negative_integer(path, report, "preservation_sensitive_activity_count")
    |> expect_one_of(
      path,
      report,
      "timeline_preservation_status",
      ["clear", "preservation_required", "review_required"]
    )
    |> expect_type(path, report, "protection_decision_counts", :map)
    |> expect_type(path, report, "protection_category_counts", :map)
    |> expect_type(path, report, "protection_reason_counts", :map)
    |> validate_non_negative_integer_count_map(
      path <> ".protection_decision_counts",
      decision_counts
    )
    |> validate_non_negative_integer_count_map(
      path <> ".protection_category_counts",
      Map.get(report, "protection_category_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".protection_reason_counts",
      Map.get(report, "protection_reason_counts")
    )
    |> expect_optional_type(path, report, "model_limits", :list)
    |> validate_string_list_items(path, report, "model_limits")
    |> validate_optional_exact_model_limits(
      path,
      report,
      timeline_report_model_limits(),
      "must match timeline report model limits"
    )
    |> validate_timeline_preservation_report_id_sets(path, report)
    |> expect_type(path, report, "rows", :list)
    |> validate_rows(path <> ".rows", Map.get(report, "rows", []), &validate_protection_row/3)
    |> expect_type(path, report, "assumptions", :map)
    |> validate_timeline_preservation_assumptions(
      path,
      report,
      "lifecycle_lock_approval_and_executed_preservation_review"
    )
    |> expect_field_equals(
      path,
      report,
      "activity_count",
      non_negative_integer_map_sum(decision_counts),
      "must equal protection_decision_counts total"
    )
    |> expect_field_equals(
      path,
      report,
      "mutable_activity_count",
      mutable_count,
      "must equal protection_decision_counts mutable"
    )
    |> expect_field_equals(
      path,
      report,
      "preserve_activity_count",
      preserve_count,
      "must equal protection_decision_counts preserve"
    )
    |> expect_field_equals(
      path,
      report,
      "review_change_activity_count",
      review_count,
      "must equal protection_decision_counts review_change"
    )
    |> expect_field_equals(
      path,
      report,
      "preservation_sensitive_activity_count",
      preserve_count + review_count,
      "must equal preserve_activity_count plus review_change_activity_count"
    )
    |> expect_field_equals(
      path,
      report,
      "timeline_preservation_status",
      preservation_status_from_counts(preserve_count, review_count),
      "must equal count-derived timeline_preservation_status"
    )
    |> validate_timeline_preservation_report_derived_sets(path, report)
  end

  defp validate_timeline_preservation_status(issues, path, status) do
    decision = Map.get(status, "protection_decision")
    expected_status = preservation_status_from_decision(decision)

    issues
    |> expect_equal(path, status, "schema_contract", "timeline_preservation_status.v1")
    |> expect_equal(path, status, "model", "artifact_only_lifecycle_preservation_status")
    |> expect_one_of(
      path,
      status,
      "timeline_preservation_status",
      ["clear", "preservation_required", "review_required"]
    )
    |> expect_type(path, status, "requires_preservation", :boolean)
    |> expect_type(path, status, "requires_operator_review", :boolean)
    |> validate_stable_ids(path, status, ["activity_id", "timeline_id"])
    |> expect_type(path, status, "protection_decision", :binary)
    |> expect_type(path, status, "protection_category", :binary)
    |> expect_type(path, status, "protection_reason", :binary)
    |> expect_optional_type(path, status, "locked", :boolean)
    |> expect_optional_type(path, status, "approved", :boolean)
    |> expect_optional_type(path, status, "invalid_activity_input", :boolean)
    |> expect_optional_type(path, status, "timeline_identity", :map)
    |> validate_optional_timeline_identity(path, status, "timeline_identity")
    |> expect_optional_type(path, status, "model_limits", :list)
    |> validate_string_list_items(path, status, "model_limits")
    |> validate_optional_exact_model_limits(
      path,
      status,
      timeline_report_model_limits(),
      "must match timeline report model limits"
    )
    |> expect_type(path, status, "assumptions", :map)
    |> validate_timeline_preservation_assumptions(
      path,
      status,
      "single_activity_lifecycle_preservation_preflight"
    )
    |> expect_field_equals(
      path,
      status,
      "timeline_preservation_status",
      expected_status,
      "must equal protection-decision-derived timeline_preservation_status"
    )
    |> expect_field_equals(
      path,
      status,
      "requires_preservation",
      expected_status == "preservation_required",
      "must equal timeline_preservation_status-derived requires_preservation"
    )
    |> expect_field_equals(
      path,
      status,
      "requires_operator_review",
      expected_status == "review_required",
      "must equal timeline_preservation_status-derived requires_operator_review"
    )
  end

