    do: [error(path, "must be an object") | issues]

  defp validate_optional_timeline_activity_state_source(issues, _path, nil), do: issues

  defp validate_optional_timeline_activity_state_source(issues, path, %{} = state) do
    validate_timeline_activity_state(issues, path, state)
  end

  defp validate_optional_timeline_activity_state_source(issues, path, _state),
    do: [error(path, "must be an object") | issues]

  defp validate_optional_lifecycle_state_source_protection_decision(issues, path, row, field) do
    case Map.get(row, field) do
      nil -> issues
      %{} -> validate_optional_protection_decision(issues, path, row, field)
      value when is_binary(value) -> issues
      _value -> [error("#{path}.#{field}", "must be a map or string") | issues]
    end
  end

  defp lifecycle_state_timeline_ids(rows, predicate) do
    rows
    |> Enum.filter(predicate)
    |> Enum.map(&Map.get(&1, "timeline_id"))
    |> sorted_unique_binary_values()
  end

  defp lifecycle_state_activity_ids(rows) do
    rows
    |> Enum.flat_map(fn row ->
      [
        row["activity_id"],
        row["planned_activity_id"],
        row["realized_activity_id"]
        | list_value(row, "planned_activity_ids") ++ list_value(row, "realized_activity_ids")
      ]
    end)
    |> sorted_unique_binary_values()
  end

  defp lifecycle_state_timeline_ids_by(rows, key_fun) do
    rows
    |> Enum.reduce(%{}, fn row, acc ->
      key = key_fun.(row)
      timeline_id = Map.get(row, "timeline_id")

      if is_binary(key) and is_binary(timeline_id) do
        Map.update(acc, key, [timeline_id], &[timeline_id | &1])
      else
        acc
      end
    end)
    |> Map.new(fn {key, ids} -> {key, sorted_unique_binary_values(ids)} end)
  end

  defp validate_timeline_transition_application_report(issues, path, report) do
    issues
    |> expect_equal(path, report, "schema_contract", "timeline_transition_application_report.v1")
    |> expect_equal(path, report, "model", "artifact_only_timeline_transition_application")
    |> expect_type(path, report, "source", :binary)
