      ),
      "must equal review-application-derived review_timeline_ids_by_required_operator_action"
    )
    |> expect_field_equals(
      path,
      summary,
      "review_timeline_ids_by_status_transition_category",
      timeline_transition_application_summary_ids_by_nested_field(
        review_applications,
        "status_transition",
        "transition_category"
      ),
      "must equal review-application-derived review_timeline_ids_by_status_transition_category"
    )
    |> expect_field_equals(
      path,
      summary,
      "review_timeline_ids_by_approval_transition_category",
      timeline_transition_application_summary_ids_by_nested_field(
        review_applications,
        "approval_transition",
        "transition_category"
      ),
      "must equal review-application-derived review_timeline_ids_by_approval_transition_category"
    )
    |> expect_field_equals(
      path,
      summary,
      "withheld_review_timeline_ids",
      timeline_transition_application_summary_row_ids(
        review_applications,
        &(&1["application_status"] == "operator_review_required")
      ),
      "must equal review-application-derived withheld_review_timeline_ids"
    )
  end

  defp timeline_transition_application_summary_row_ids(rows, predicate) do
    rows
    |> Enum.filter(predicate)
    |> Enum.map(&Map.get(&1, "timeline_id"))
    |> sorted_unique_binary_values()
  end

  defp timeline_transition_application_summary_activity_ids(rows) do
    rows
    |> Enum.flat_map(&[Map.get(&1, "source_activity_id"), Map.get(&1, "replacement_activity_id")])
    |> sorted_unique_binary_values()
  end

  defp timeline_transition_application_summary_ids_by_field(rows, field) do
    rows
    |> Enum.group_by(&Map.get(&1, field), &Map.get(&1, "timeline_id"))
    |> timeline_transition_application_summary_id_map()
  end

  defp timeline_transition_application_summary_ids_by_nested_field(rows, field, nested_field) do
    rows
    |> Enum.group_by(&get_in(&1, [field, nested_field]), &Map.get(&1, "timeline_id"))
    |> timeline_transition_application_summary_id_map()
  end

  defp timeline_transition_application_summary_id_map(grouped_ids) do
    grouped_ids
    |> Enum.reject(fn {group, ids} -> group in [nil, ""] or Enum.all?(ids, &is_nil/1) end)
    |> Map.new(fn {group, ids} -> {group, sorted_unique_binary_values(ids)} end)
  end

