    |> validate_rows(path <> ".rows", Map.get(report, "rows", []), &validate_constraint_row/3)
    |> validate_constraint_report_counts(path, report)
  end

  defp validate_constraint_report_model_limits(issues, path, report) do
    case Map.get(report, "model_limits") do
      nil ->
        issues

      :null ->
        issues

      limits when is_list(limits) ->
        expected_limits = Map.get(constraint_report_model_limits_by_model(), report["model"])

        if is_nil(expected_limits) or limits == expected_limits do
          issues
        else
          [error("#{path}.model_limits", "must match constraint report model limits") | issues]
        end

      _value ->
        issues
    end
  end

  defp validate_constraint_report_counts(issues, path, report) do
    rows =
      report
      |> Map.get("rows", [])
      |> Enum.filter(&is_map/1)

    issues
    |> expect_field_equals(path, report, "constraint_count", constraint_id_count(rows))
    |> expect_field_equals(path, report, "row_count", length(rows))
    |> expect_field_equals(path, report, "status", constraint_report_status(rows))
    |> expect_field_equals(
      path,
      report,
      "status_counts",
      constraint_status_counts(rows),
      "must equal row-derived status_counts"
    )
  end

  defp constraint_id_count(rows) do
    rows
    |> Enum.map(&Map.get(&1, "constraint_id"))
    |> Enum.reject(&is_nil/1)
    |> Enum.uniq()
    |> length()
  end

  defp constraint_report_status(rows) do
    statuses = Enum.map(rows, &Map.get(&1, "status"))

    cond do
      "fail" in statuses -> "fail"
      "warning" in statuses -> "warning"
      true -> "pass"
    end
  end

  defp constraint_status_counts(rows) do
    rows
    |> frequency_map("status")
    |> Map.put_new("pass", 0)
    |> Map.put_new("fail", 0)
    |> Map.put_new("warning", 0)
  end

