    |> expect_type(path, report, "invalidated_candidates", :list)
    |> expect_optional_type(path, report, "model_limits", :list)
    |> expect_optional_non_negative_integer(path, report, "valid_prior_candidate_count")
    |> expect_optional_non_negative_integer(path, report, "invalid_prior_candidate_input_count")
