      "source_window_id"
    ])
    |> expect_one_of(path, candidate, "diff_reason", [
      "present_in_prior_candidate_set",
      "present_in_prior_candidate_set_with_semantic_changes",
      "not_present_in_prior_candidate_set",
      "semantically_similar_prior_candidate_changed",
      "ambiguous_semantic_prior_candidate_match"
    ])
    |> expect_optional_number(path, candidate, "starts_at_s")
    |> expect_optional_number(path, candidate, "ends_at_s")
    |> expect_optional_type(path, candidate, "direction", :binary)
    |> expect_optional_type(path, candidate, "source_target", :map)
    |> expect_optional_number(path, candidate, "target_latitude_deg")
    |> expect_optional_number(path, candidate, "target_longitude_deg")
    |> expect_optional_number(path, candidate, "target_minimum_elevation_deg")
    |> expect_optional_number(path, candidate, "target_priority")
    |> expect_optional_type(path, candidate, "target_priority_source", :binary)
    |> expect_optional_type(path, candidate, "target_priority_objective_ids", :list)
    |> validate_optional_stable_id_list(path, candidate, "target_priority_objective_ids")
    |> expect_optional_type(path, candidate, "target_priority_objective_type", :binary)
    |> expect_optional_list(path, candidate, "semantic_change_reasons")
    |> validate_candidate_refresh_scoped_context_fields(path, candidate)
    |> validate_semantic_change_details(path, candidate)
    |> validate_candidate_diff_changed_fields(path, candidate)
  end

  defp validate_optional_freshness_report(issues, _path, nil), do: issues

  defp validate_optional_freshness_report(issues, path, %{} = report) do
    issues
    |> require_fields(path, report, [
      "schema_contract",
      "model",
      "generated_at",
      "accepted_at",
      "current_epoch_s",
      "horizon_starts_at_s",
      "accepted_snapshot_age_s",
      "horizon_start_offset_s",
      "max_snapshot_age_s",
      "max_horizon_start_offset_s",
      "status",
      "stale_reasons"
    ])
    |> expect_equal(path, report, "schema_contract", "freshness_report.v1")
    |> expect_equal(path, report, "model", "accepted_snapshot_horizon_and_quality_freshness")
    |> expect_type(path, report, "generated_at", :binary)
    |> expect_optional_number(path, report, "current_epoch_s")
    |> expect_optional_number(path, report, "horizon_starts_at_s")
    |> expect_optional_number(path, report, "accepted_snapshot_age_s")
    |> expect_optional_number(path, report, "horizon_start_offset_s")
    |> expect_number(path, report, "max_snapshot_age_s")
    |> expect_number(path, report, "max_horizon_start_offset_s")
    |> expect_optional_type(path, report, "accepted_state_quality_level", :binary)
    |> expect_optional_type(path, report, "state_quality_status", :binary)
    |> expect_optional_list(path, report, "allowed_state_quality_levels")
    |> expect_one_of(path, report, "status", freshness_statuses())
    |> expect_type(path, report, "stale_reasons", :list)
    |> expect_optional_type(path, report, "unknown_reasons", :list)
    |> expect_optional_type(path, report, "model_limits", :list)
    |> validate_string_list_items(path, report, "model_limits")
    |> validate_freshness_report_counts(path, report)
  end

  defp validate_optional_freshness_report(issues, path, _report),
    do: [error(path, "must be an object") | issues]

  defp validate_freshness_report_counts(issues, path, report) do
    stale_reasons = freshness_stale_reasons(report)
    unknown_reasons = freshness_unknown_reasons(report)

    issues
    |> expect_field_equals(
      path,
      report,
      "stale_reasons",
      stale_reasons,
      "must equal freshness-policy-derived stale_reasons"
    )
    |> expect_field_equals(
      path,
      report,
      "unknown_reasons",
      unknown_reasons,
      "must equal freshness-policy-derived unknown_reasons"
    )
    |> expect_field_equals(
      path,
      report,
      "status",
      freshness_status(stale_reasons, unknown_reasons)
    )
    |> expect_field_equals(
      path,
      report,
      "state_quality_status",
      freshness_state_quality_status(report)
    )
    |> expect_field_equals(
      path,
      report,
      "model_limits",
      OrbitalDynamics.CandidateRefresh.model_limits(),
      "must match candidate refresh model limits"
    )
  end

  defp freshness_stale_reasons(report) do
    []
    |> maybe_append(
      freshness_snapshot_stale?(report),
      "accepted_snapshot_older_than_policy"
    )
    |> maybe_append(
      freshness_horizon_stale?(report),
      "remaining_horizon_does_not_start_at_current_epoch"
    )
    |> maybe_append(
      freshness_state_quality_status(report) == "not_accepted",
      "accepted_state_quality_below_policy"
    )
  end

  defp freshness_unknown_reasons(report) do
    []
    |> maybe_append(
      not is_number(Map.get(report, "accepted_snapshot_age_s")),
      "accepted_snapshot_age_unknown"
    )
    |> maybe_append(
      not is_number(Map.get(report, "horizon_start_offset_s")),
      "horizon_alignment_unknown"
    )
    |> maybe_append(
      freshness_state_quality_status(report) == "unknown",
      "accepted_state_quality_unknown"
    )
  end

  defp freshness_snapshot_stale?(report) do
    age = Map.get(report, "accepted_snapshot_age_s")
    max_age = Map.get(report, "max_snapshot_age_s")

    is_number(age) and is_number(max_age) and age > max_age
  end

  defp freshness_horizon_stale?(report) do
    offset = Map.get(report, "horizon_start_offset_s")
    max_offset = Map.get(report, "max_horizon_start_offset_s")

    is_number(offset) and is_number(max_offset) and abs(offset) > max_offset
  end

  defp freshness_state_quality_status(report) do
    level = Map.get(report, "accepted_state_quality_level")
    allowed_levels = list_value(report, "allowed_state_quality_levels")

    cond do
      not is_binary(level) ->
        "unknown"

      level in allowed_levels ->
        "accepted"

      true ->
        "not_accepted"
    end
  end

  defp freshness_status(stale_reasons, unknown_reasons) do
    cond do
      stale_reasons != [] -> "stale"
      unknown_reasons != [] -> "unknown"
      true -> "current"
    end
  end

  defp maybe_append(values, true, value), do: values ++ [value]
  defp maybe_append(values, _condition, _value), do: values

  defp validate_optional_refresh_budget_report(issues, _path, nil), do: issues

  defp validate_optional_refresh_budget_report(issues, path, %{} = report) do
    validate_refresh_budget_report(issues, path, report)
  end

  defp validate_optional_refresh_budget_report(issues, path, _report),
