  defp validate_optional_source_window_lineage(issues, path, row, field) do
    case Map.get(row, field) do
      nil ->
        issues

      %{} = lineage ->
        validate_source_window_lineage(issues, "#{path}.#{field}", lineage)

      _value ->
        [error("#{path}.#{field}", "must be an object") | issues]
    end
