  defp validate_stable_id_list(issues, path, map, field) do
    case Map.get(map, field) do
      values when is_list(values) ->
        values
        |> Enum.with_index()
        |> Enum.reduce(issues, fn {value, index}, acc ->
          validate_stable_id(acc, "#{path}.#{field}[#{index}]", value)
        end)

      _value ->
        issues
    end
  end

  defp validate_refresh_budget_counts(issues, path, report) do
    issues
    |> expect_field_at_least(path, report, "input_candidate_count", 0)
    |> expect_field_at_least(path, report, "kept_candidate_count", 0)
    |> expect_field_at_least(path, report, "dropped_candidate_count", 0)
    |> expect_field_at_least(path, report, "max_candidate_activities", 0)
    |> expect_equal(
      path,
      report,
      "input_candidate_count",
      row_count_sum(report, ["kept_candidate_count", "dropped_candidate_count"])
    )
    |> expect_equal(
      path,
      report,
      "kept_candidate_count",
      length(Map.get(report, "kept_candidate_ids", []))
    )
    |> expect_equal(
      path,
      report,
      "dropped_candidate_count",
      length(Map.get(report, "dropped_candidate_ids", []))
    )
    |> expect_field_equals(
      path,
      report,
      "model_limits",
      OrbitalDynamics.CandidateRefresh.model_limits(),
      "must match candidate refresh model limits"
    )
    |> validate_refresh_budget_candidate_id_sets(path, report)
  end

  defp validate_refresh_budget_candidate_id_sets(issues, path, report) do
    kept_candidate_ids = list_value(report, "kept_candidate_ids")
    dropped_candidate_ids = list_value(report, "dropped_candidate_ids")

    issues
    |> reject_duplicate_ids(path <> ".kept_candidate_ids", kept_candidate_ids)
    |> reject_duplicate_ids(path <> ".dropped_candidate_ids", dropped_candidate_ids)
    |> reject_id_list_overlap(
      path <> ".dropped_candidate_ids",
      kept_candidate_ids,
      dropped_candidate_ids,
      "must not overlap kept_candidate_ids"
    )
  end

  defp reject_duplicate_ids(issues, path, ids) do
    duplicate_ids =
      ids
      |> Enum.frequencies()
      |> Enum.filter(fn {_id, count} -> count > 1 end)
      |> Enum.map(fn {id, _count} -> id end)
      |> Enum.sort()

    if duplicate_ids == [] do
      issues
    else
      [error(path, "must not contain duplicate IDs: #{inspect(duplicate_ids)}") | issues]
    end
  end

  defp reject_id_list_overlap(issues, path, left_ids, right_ids, message) do
    overlap =
      left_ids
      |> MapSet.new()
      |> MapSet.intersection(MapSet.new(right_ids))
      |> MapSet.to_list()
      |> Enum.sort()

    if overlap == [] do
      issues
    else
      [error(path, "#{message}: #{inspect(overlap)}") | issues]
    end
  end

  defp validate_candidate_diff_report_lineage(issues, path, report) do
    candidates =
      ["retained_candidates", "new_candidates", "invalidated_candidates"]
      |> Enum.flat_map(fn field -> Map.get(report, field, []) end)
      |> Enum.filter(&is_map/1)
      |> Map.new(fn candidate -> {Map.get(candidate, "id"), candidate} end)

    report
    |> Map.get("source_window_lineage", [])
    |> case do
      rows when is_list(rows) ->
        rows
        |> Enum.with_index()
        |> Enum.reduce(issues, fn {lineage, index}, acc ->
          candidate_activity_id =
            if is_map(lineage), do: Map.get(lineage, "candidate_activity_id")

          candidate = candidates[candidate_activity_id]

          cond do
            is_map(lineage) and is_nil(candidate) ->
              [
                error(
                  "#{path}.source_window_lineage[#{index}].candidate_activity_id",
                  "must match a candidate diff row"
                )
                | acc
              ]

            is_map(lineage) and is_map(candidate) and
                Map.get(lineage, "source_window_id") != Map.get(candidate, "source_window_id") ->
              [
                error(
                  "#{path}.source_window_lineage[#{index}].source_window_id",
                  "must match candidate activity source_window_id"
                )
                | acc
              ]

            true ->
              acc
          end
        end)

      _rows ->
        issues
    end
  end

  defp validate_filter_report_counts(issues, path, report, kind) do
    rows =
      report
      |> Map.get("suppressed_candidates", [])
      |> Enum.filter(&is_map/1)

    issues
    |> expect_field_equals(path, report, "suppressed_candidate_count", length(rows))
    |> expect_field_equals(
      path,
      report,
      "kept_candidate_count",
      row_count_difference(report, "input_candidate_count", length(rows))
    )
    |> validate_filter_report_invalid_inputs(path, report, rows, kind)
    |> validate_filter_report_duplicate_rows(path, report, rows)
    |> validate_filter_report_count_maps(path, report, rows, kind)
  end

  defp validate_filter_report_invalid_inputs(issues, path, report, rows, "contact") do
    invalid_ids =
      rows
      |> Enum.filter(
        &(Map.get(&1, "invalid_contact_shape") == true or
            Map.get(&1, "invalid_contact_input") == true)
      )
      |> Enum.map(&Map.get(&1, "id"))

    issues
    |> expect_field_equals(path, report, "invalid_contact_input_count", length(invalid_ids))
    |> validate_ids_match_row_multiset(
      path,
      report,
      "invalid_contact_input_ids",
      invalid_ids,
      "must equal row-derived invalid_contact_input_ids"
    )
  end

  defp validate_filter_report_invalid_inputs(issues, path, report, rows, "resource") do
    invalid_summary_rows =
      report
      |> Map.get("invalid_resource_summary_inputs", [])
      |> case do
        values when is_list(values) -> Enum.filter(values, &is_map/1)
        _values -> []
      end

    invalid_candidate_ids =
      rows
      |> Enum.filter(
        &(Map.get(&1, "invalid_candidate_input") == true or
            Map.get(&1, "invalid_candidate_shape") == true)
      )
      |> Enum.map(&Map.get(&1, "id"))
      |> Enum.sort()

    issues
    |> expect_field_equals(
      path,
      report,
      "invalid_candidate_input_count",
      length(invalid_candidate_ids)
    )
    |> expect_field_equals(
      path,
      report,
      "invalid_candidate_input_ids",
      invalid_candidate_ids,
      "must equal row-derived invalid_candidate_input_ids"
    )
    |> expect_field_equals(
      path,
      report,
      "invalid_resource_summary_input_count",
      length(invalid_summary_rows)
    )
    |> expect_field_equals(
      path,
      report,
      "invalid_resource_summary_input_ids",
      Enum.map(invalid_summary_rows, &Map.get(&1, "resource_summary_id")),
      "must equal row-derived invalid_resource_summary_input_ids"
    )
    |> expect_field_equals(
      path,
      report,
      "valid_resource_summary_count",
      row_count_difference(report, "input_resource_summary_count", length(invalid_summary_rows))
    )
    |> expect_field_equals(
      path,
      report,
      "input_resource_summary_count",
      resource_filter_input_summary_count(report, length(invalid_summary_rows))
    )
  end

  defp resource_filter_input_summary_count(report, invalid_summary_count) do
    case Map.get(report, "valid_resource_summary_count") do
      value when is_integer(value) -> value + invalid_summary_count
      _value -> nil
    end
  end

