  defp validate_resource_filter_summary(issues, path, summary) do
    issues
    |> expect_equal(path, summary, "schema_contract", "resource_filter_summary.v1")
    |> expect_equal(path, summary, "model", "artifact_only_resource_filter_summary")
    |> expect_equal(path, summary, "source_artifact_type", "resource_filter_report.v1")
    |> expect_optional_type(path, summary, "model_limits", :list)
    |> validate_string_list_items(path, summary, "model_limits")
    |> validate_optional_exact_model_limits(
      path,
      summary,
      resource_filter_report_model_limits(),
      "must match resource filter report model limits"
    )
    |> validate_resource_filter_summary_field_types(path, summary)
    |> expect_type(path, summary, "review_rows", :list)
    |> validate_rows(
      path <> ".review_rows",
      Map.get(summary, "review_rows", []),
      &validate_suppressed_candidate/3
    )
    |> expect_type(path, summary, "invalid_resource_summary_inputs", :list)
    |> validate_rows(
      path <> ".invalid_resource_summary_inputs",
      Map.get(summary, "invalid_resource_summary_inputs", []),
      &validate_invalid_resource_summary_input/3
    )
    |> expect_type(path, summary, "assumptions", :map)
    |> validate_resource_filter_summary_assumptions(path, summary)
    |> validate_resource_filter_summary_counts(path, summary)
  end

  defp validate_resource_filter_summary_field_types(issues, path, summary) do
    issues =
      Enum.reduce(resource_filter_summary_count_fields(), issues, fn field, acc ->
        expect_non_negative_integer(acc, path, summary, field)
      end)

    issues =
      Enum.reduce(resource_filter_summary_count_map_fields(), issues, fn field, acc ->
        acc
        |> expect_type(path, summary, field, :map)
        |> validate_non_negative_integer_count_map(path <> ".#{field}", Map.get(summary, field))
      end)

    issues =
      Enum.reduce(resource_filter_summary_stable_id_list_fields(), issues, fn field, acc ->
        acc
        |> expect_type(path, summary, field, :list)
        |> validate_stable_id_list(path <> ".#{field}", Map.get(summary, field))
      end)

    issues =
      Enum.reduce(resource_filter_summary_stable_id_array_map_fields(), issues, fn field, acc ->
        acc
        |> expect_type(path, summary, field, :map)
        |> validate_stable_id_array_map(path <> ".#{field}", Map.get(summary, field))
      end)

    issues
    |> expect_one_of(path, summary, "suppression_review_status", ["clear", "review_required"])
  end

