      resource_filter_summary_row_ids(invalid_summary_rows, "resource_summary_id"),
      "must equal invalid_resource_summary_inputs resource_summary_id values"
    )
    |> expect_field_equals(
      path,
      summary,
      "duplicate_suppressed_candidate_id_count",
      duplicate_suppressed_candidate_id_count_from_schema_rows(rows),
      "must equal review_rows duplicate suppressed candidate id count"
    )
    |> expect_field_equals(
      path,
      summary,
      "duplicate_suppressed_candidate_row_count",
      duplicate_suppressed_candidate_row_count_from_schema_rows(rows),
      "must equal review_rows duplicate suppressed candidate row count"
    )
  end

  defp resource_filter_summary_review_status([], []), do: "clear"
  defp resource_filter_summary_review_status(_rows, _invalid_summary_rows), do: "review_required"

  defp resource_filter_summary_row_ids(rows, field) do
    rows
    |> Enum.map(&Map.get(&1, field))
    |> sorted_unique_binary_values()
  end

  defp duplicate_suppressed_candidate_id_count_from_schema_rows(rows) do
    rows
    |> Enum.map(&Map.get(&1, "id"))
    |> Enum.reject(&is_nil/1)
    |> Enum.frequencies()
    |> Enum.count(fn {_id, count} -> count > 1 end)
  end

  defp duplicate_suppressed_candidate_row_count_from_schema_rows(rows) do
    rows
    |> Enum.filter(&(Map.get(&1, "duplicate_suppressed_candidate_id") == true))
    |> length()
  end

  defp validate_non_negative_integer_count_map(issues, path, counts) when is_map(counts) do
    Enum.reduce(counts, issues, fn {field, count}, acc ->
      if is_integer(count) and count >= 0 do
        acc
      else
        [error("#{path}.#{field}", "must be a non-negative integer") | acc]
      end
    end)
  end

  defp validate_non_negative_integer_count_map(issues, _path, _counts), do: issues

  defp validate_non_negative_number_map(issues, path, values) when is_map(values) do
    Enum.reduce(values, issues, fn {field, value}, acc ->
      cond do
        is_number(value) and value >= 0.0 ->
          acc

        is_number(value) ->
          [error("#{path}.#{field}", "must be non-negative") | acc]

        true ->
          [error("#{path}.#{field}", "must be a number") | acc]
      end
    end)
  end

  defp validate_non_negative_number_map(issues, _path, _values), do: issues

  defp validate_nested_non_negative_number_map(issues, _path, value)
       when value in [nil, :null],
       do: issues

  defp validate_nested_non_negative_number_map(issues, path, %{} = values) do
    Enum.reduce(values, issues, fn {key, nested_values}, acc ->
      validate_non_negative_number_map(acc, "#{path}.#{key}", nested_values)
    end)
  end

  defp validate_nested_non_negative_number_map(issues, _path, _value), do: issues

  defp validate_non_negative_number_list(issues, _path, value) when value in [nil, :null],
    do: issues

  defp validate_non_negative_number_list(issues, path, values) when is_list(values) do
    values
    |> Enum.with_index()
    |> Enum.reduce(issues, fn {value, index}, acc ->
      cond do
        is_number(value) and value >= 0.0 ->
          acc

        is_number(value) ->
          [error("#{path}[#{index}]", "must be non-negative") | acc]

        true ->
          [error("#{path}[#{index}]", "must be a number") | acc]
      end
    end)
  end

  defp validate_non_negative_number_list(issues, path, _value),
    do: [error(path, "must be an array") | issues]

  defp validate_number_array_map(issues, _path, value) when value in [nil, :null], do: issues

  defp validate_number_array_map(issues, path, %{} = values) do
    Enum.reduce(values, issues, fn {key, refs}, acc ->
      validate_non_negative_number_list(acc, "#{path}.#{key}", refs)
    end)
  end

  defp validate_number_array_map(issues, path, _value),
    do: [error(path, "must be an object") | issues]

  defp validate_string_list_map(issues, path, summary, field) do
    case Map.get(summary, field) do
      %{} = grouped_values ->
        Enum.reduce(grouped_values, issues, fn {key, values}, acc ->
          entry_path = "#{path}.#{field}.#{key}"

          cond do
            not is_list(values) ->
              [error(entry_path, "must be an array") | acc]

            Enum.all?(values, &is_binary/1) ->
              acc

            true ->
              [error(entry_path, "must contain only strings") | acc]
          end
        end)

      _grouped_values ->
        issues
    end
  end

  defp non_negative_integer_map_sum(counts) when is_map(counts) do
    values = Map.values(counts)

    if Enum.all?(values, &(is_integer(&1) and &1 >= 0)),
      do: Enum.sum(values),
      else: nil
  end

  defp non_negative_integer_map_sum(_counts), do: nil

  defp numeric_map_sum(values) when is_map(values) do
    values = Map.values(values)

    if Enum.all?(values, &is_number/1),
      do: Enum.sum(values),
      else: nil
  end

  defp numeric_map_sum(_values), do: nil

  defp nested_numeric_map_sum(values) when is_map(values) do
    values
    |> Map.values()
    |> Enum.reduce_while(0.0, fn
      nested_values, total when is_map(nested_values) ->
        case numeric_map_sum(nested_values) do
          sum when is_number(sum) -> {:cont, total + sum}
          _sum -> {:halt, nil}
        end

      _nested_values, _total ->
        {:halt, nil}
    end)
  end

  defp nested_numeric_map_sum(_values), do: nil

  defp stable_id_array_map_value_count(values) when is_map(values) do
    values
    |> Map.values()
    |> Enum.reduce_while(0, fn
      ids, total when is_list(ids) -> {:cont, total + length(ids)}
      _ids, _total -> {:halt, nil}
    end)
  end

  defp stable_id_array_map_value_count(_values), do: nil

  defp nested_stable_id_array_map_value_count(values) when is_map(values) do
    values
    |> Map.values()
    |> Enum.reduce_while(0, fn
      nested_values, total when is_map(nested_values) ->
        case stable_id_array_map_value_count(nested_values) do
          count when is_integer(count) -> {:cont, total + count}
          _count -> {:halt, nil}
        end

      _nested_values, _total ->
        {:halt, nil}
    end)
  end

  defp nested_stable_id_array_map_value_count(_values), do: nil

  defp stable_id_array_map_counts(values) when is_map(values) do
    values
    |> Map.new(fn
      {key, ids} when is_list(ids) -> {key, length(ids)}
      {key, _ids} -> {key, nil}
    end)
  end

  defp stable_id_array_map_counts(_values), do: nil

  defp sorted_map_keys(values) when is_map(values) do
    values
    |> Map.keys()
    |> sorted_unique_binary_values()
  end

  defp sorted_map_keys(_values), do: nil

  defp expect_non_negative_integer(issues, path, map, field) do
    case Map.get(map, field) do
      value when is_integer(value) and value >= 0 ->
        issues

      _value ->
        [error("#{path}.#{field}", "must be a non-negative integer") | issues]
    end
  end

  defp expect_optional_non_negative_integer(issues, path, map, field) do
    case Map.get(map, field) do
      nil ->
        issues

      :null ->
        issues

      value when is_integer(value) and value >= 0 ->
        issues

      _value ->
        [error("#{path}.#{field}", "must be a non-negative integer") | issues]
    end
  end

  defp validate_filter_report_duplicate_rows(issues, path, report, rows) do
    duplicate_rows =
      Enum.filter(rows, &(Map.get(&1, "duplicate_suppressed_candidate_id_collision") == true))

    issues =
      issues
      |> expect_field_equals(
        path,
        report,
        "duplicate_suppressed_candidate_row_count",
        length(duplicate_rows)
      )
      |> expect_field_equals(
        path,
        report,
        "duplicate_suppressed_candidate_id_count",
        duplicate_rows
        |> Enum.map(&Map.get(&1, "base_candidate_id"))
        |> Enum.reject(&is_nil/1)
        |> Enum.uniq()
        |> length()
      )

    duplicate_rows
    |> Enum.group_by(&Map.get(&1, "base_candidate_id"))
    |> Enum.reduce(issues, fn {_base_id, group}, acc ->
      count = length(group)

      indexes =
        group |> Enum.map(&Map.get(&1, "duplicate_suppressed_candidate_index")) |> Enum.sort()

      expected_indexes = Enum.to_list(1..count)

      acc =
        group
        |> Enum.reduce(acc, fn row, row_acc ->
          row_index = Enum.find_index(rows, &(&1 == row)) || 0

          row_acc
          |> expect_field_equals(
            "#{path}.suppressed_candidates[#{row_index}]",
            row,
            "duplicate_suppressed_candidate_count",
            count
          )
        end)

      if indexes == expected_indexes do
        acc
      else
        [
          error(
            "#{path}.suppressed_candidates",
            "duplicate_suppressed_candidate_index values must cover 1..#{count}"
          )
          | acc
        ]
      end
    end)
  end

