      Enum.reduce(link_capacity_summary_stable_id_array_map_fields(), issues, fn field, acc ->
        acc
        |> expect_type(path, summary, field, :map)
        |> validate_stable_id_array_map(path <> ".#{field}", Map.get(summary, field))
      end)

    issues =
      Enum.reduce(link_capacity_summary_optional_status_fields(), issues, fn field, acc ->
        expect_optional_type(acc, path, summary, field, :binary)
      end)

