    station_pressure_rows = contact_allocation_station_pressure_rows(rows)
    resource_blocked_rows = contact_allocation_resource_blocked_rows(rows)
    capacity_pack_rows = contact_allocation_capacity_pack_rows(rows)

    selected_capacity_pack_rows =
      contact_allocation_selected_capacity_pack_rows(capacity_pack_rows)

    deferred_capacity_pack_rows =
      contact_allocation_deferred_capacity_pack_rows(capacity_pack_rows)

    pack_groups = summary |> Map.get("reduced_capacity_pack_groups", []) |> Enum.filter(&is_map/1)

    reservation_expiration_rows =
      contact_allocation_reservation_expiration_rows(
        rows,
        Map.get(summary, "station_reservation_expiration_now_s")
