    |> validate_contact_allocation_reservation_conflict_summary_assumptions(path, summary)
    |> validate_contact_allocation_reservation_conflict_summary_counts(path, summary)
  end

  defp validate_contact_allocation_reservation_conflict_summary_assumptions(
         issues,
         path,
         summary
       ) do
    case Map.get(summary, "assumptions") do
      %{} = assumptions ->
        issues
        |> expect_equal(
          path <> ".assumptions",
          assumptions,
          "execution_boundary",
          "artifact_only_no_provider_reservation_or_schedule_mutation"
        )
        |> expect_equal(
          path <> ".assumptions",
          assumptions,
          "source",
          "contact_allocation_report.v1"
        )
        |> expect_equal(
          path <> ".assumptions",
          assumptions,
          "operator_authority",
          "not_granted_by_reservation_conflict_summary"
        )

      _assumptions ->
        issues
    end
  end

  defp validate_contact_allocation_reservation_conflict_summary_counts(
         issues,
         path,
         summary
       ) do
    rows =
      summary
      |> Map.get("rows", [])
      |> Enum.filter(&is_map/1)

    now_s = Map.get(summary, "station_reservation_expiration_now_s")
    reservation_rows = Enum.filter(rows, &contact_allocation_reservation_expiration_row?/1)
    conflict_rows = Enum.filter(reservation_rows, &contact_allocation_reservation_conflict_row?/1)
    review_rows = Enum.filter(reservation_rows, &contact_allocation_review_row?/1)

    expiration_rows =
      contact_allocation_reservation_expiration_rows(reservation_rows, now_s)

    issues
    |> expect_field_equals(path, summary, "input_contact_count", length(rows))
    |> expect_field_equals(
      path,
      summary,
      "station_reservation_contact_count",
      length(reservation_rows),
      "must equal row-derived station_reservation_contact_count"
    )
    |> expect_field_equals(
      path,
      summary,
      "reservation_conflict_contact_count",
      length(conflict_rows),
      "must equal row-derived reservation_conflict_contact_count"
    )
    |> expect_field_equals(
      path,
      summary,
      "reservation_review_contact_count",
      length(review_rows),
      "must equal row-derived reservation_review_contact_count"
    )
    |> expect_field_equals(
      path,
      summary,
      "station_reservation_match_status_counts",
      frequency_map(reservation_rows, "station_reservation_match_status"),
      "must equal row-derived station_reservation_match_status_counts"
