  defp validate_contact_allocation_provider_reservation_request_summary_assumptions(
         issues,
         path,
         summary
       ) do
    case Map.get(summary, "assumptions") do
      %{} = assumptions ->
        issues
        |> expect_equal(
          path <> ".assumptions",
          assumptions,
          "execution_boundary",
          "artifact_only_no_provider_reservation_or_schedule_mutation"
        )
        |> expect_equal(
          path <> ".assumptions",
          assumptions,
          "source",
          "contact_allocation_report.v1"
        )
        |> expect_equal(
          path <> ".assumptions",
          assumptions,
          "provider_reservation_execution",
          "not_performed_by_summary"
        )
        |> expect_equal(
          path <> ".assumptions",
          assumptions,
          "operator_authority",
          "not_granted_by_provider_reservation_request_summary"
        )

      _assumptions ->
        issues
    end
  end

  defp validate_contact_allocation_provider_reservation_request_summary_counts(
         issues,
         path,
         summary
       ) do
    rows =
      summary
      |> Map.get("rows", [])
      |> Enum.filter(&is_map/1)

    candidate_rows =
      Enum.filter(rows, &contact_allocation_provider_reservation_candidate_row?/1)

    request_rows =
      Enum.filter(candidate_rows, &contact_allocation_provider_reservation_request_ready_row?/1)

    review_rows =
      Enum.reject(candidate_rows, &contact_allocation_provider_reservation_request_ready_row?/1)

    no_request_rows =
      Enum.reject(rows, &contact_allocation_provider_reservation_candidate_row?/1)

    issues
    |> expect_field_equals(path, summary, "input_contact_count", length(rows))
    |> expect_field_equals(
      path,
      summary,
      "provider_reservation_candidate_contact_count",
      length(candidate_rows),
      "must equal row-derived provider_reservation_candidate_contact_count"
    )
    |> expect_field_equals(
      path,
      summary,
      "provider_reservation_request_contact_count",
      length(request_rows),
      "must equal row-derived provider_reservation_request_contact_count"
    )
    |> expect_field_equals(
      path,
      summary,
      "provider_reservation_review_contact_count",
      length(review_rows),
      "must equal row-derived provider_reservation_review_contact_count"
    )
    |> expect_field_equals(
      path,
      summary,
      "provider_reservation_no_request_contact_count",
      length(no_request_rows),
      "must equal row-derived provider_reservation_no_request_contact_count"
    )
    |> expect_field_equals(
      path,
      summary,
      "provider_reservation_request_status",
      contact_allocation_provider_reservation_request_status(request_rows, review_rows)
    )
    |> expect_field_equals(
      path,
      summary,
      "provider_reservation_request_contact_ids",
      contact_allocation_row_contact_ids(request_rows),
      "must equal row-derived provider_reservation_request_contact_ids"
    )
    |> expect_field_equals(
      path,
      summary,
      "provider_reservation_review_contact_ids",
      contact_allocation_row_contact_ids(review_rows),
      "must equal row-derived provider_reservation_review_contact_ids"
    )
    |> expect_field_equals(
      path,
      summary,
      "provider_reservation_no_request_contact_ids",
      contact_allocation_row_contact_ids(no_request_rows),
      "must equal row-derived provider_reservation_no_request_contact_ids"
    )
    |> expect_field_equals(
      path,
      summary,
      "provider_reservation_request_contact_ids_by_ground_station_id",
      row_ids_by_field(request_rows, "ground_station_id", "contact_id"),
      "must equal row-derived provider_reservation_request_contact_ids_by_ground_station_id"
    )
    |> expect_field_equals(
      path,
      summary,
      "provider_reservation_review_contact_ids_by_ground_station_id",
      row_ids_by_field(review_rows, "ground_station_id", "contact_id"),
      "must equal row-derived provider_reservation_review_contact_ids_by_ground_station_id"
    )
    |> expect_field_equals(
      path,
      summary,
      "provider_reservation_no_request_contact_ids_by_direction",
      row_ids_by_field(no_request_rows, "direction", "contact_id"),
      "must equal row-derived provider_reservation_no_request_contact_ids_by_direction"
    )
    |> expect_field_equals(
      path,
      summary,
      "provider_reservation_request_contact_ids_by_direction",
      row_ids_by_field(request_rows, "direction", "contact_id"),
      "must equal row-derived provider_reservation_request_contact_ids_by_direction"
    )
    |> expect_field_equals(
      path,
      summary,
      "provider_reservation_review_contact_ids_by_direction",
      row_ids_by_field(review_rows, "direction", "contact_id"),
      "must equal row-derived provider_reservation_review_contact_ids_by_direction"
    )
    |> expect_field_equals(
      path,
      summary,
      "provider_reservation_request_contact_ids_by_match_status",
      row_ids_by_field(request_rows, "station_reservation_match_status", "contact_id"),
      "must equal row-derived provider_reservation_request_contact_ids_by_match_status"
    )
    |> expect_field_equals(
      path,
      summary,
      "provider_reservation_review_contact_ids_by_match_status",
      row_ids_by_field(review_rows, "station_reservation_match_status", "contact_id"),
      "must equal row-derived provider_reservation_review_contact_ids_by_match_status"
    )
    |> expect_field_equals(
      path,
      summary,
      "provider_reservation_request_ids_by_match_status",
      row_ids_by_field(
        request_rows,
        "station_reservation_match_status",
        "station_reservation_id"
      ),
      "must equal row-derived provider_reservation_request_ids_by_match_status"
    )
    |> expect_field_equals(
      path,
      summary,
      "provider_reservation_review_ids_by_match_status",
      row_ids_by_field(review_rows, "station_reservation_match_status", "station_reservation_id"),
      "must equal row-derived provider_reservation_review_ids_by_match_status"
    )
    |> expect_field_equals(
      path,
      summary,
      "provider_reservation_request_rows",
      request_rows,
      "must equal row-derived provider_reservation_request_rows"
    )
    |> expect_field_equals(
      path,
      summary,
      "provider_reservation_review_rows",
      review_rows,
      "must equal row-derived provider_reservation_review_rows"
    )
  end

  defp contact_allocation_provider_reservation_candidate_row?(row) do
    Map.get(row, "allocation_status") == "allocated" and
      contact_allocation_reservation_expiration_row?(row)
  end

  defp contact_allocation_provider_reservation_request_ready_row?(row) do
    Map.get(row, "station_reservation_match_status") in ["matched", "owner_matched"] and
      contact_allocation_reservation_ids(row) != []
  end

  defp contact_allocation_provider_reservation_request_status(_request_rows, review_rows)
       when review_rows != [],
       do: "review_required"

  defp contact_allocation_provider_reservation_request_status(request_rows, _review_rows)
       when request_rows != [],
       do: "request_ready"

  defp contact_allocation_provider_reservation_request_status(_request_rows, _review_rows),
    do: "clear"

  defp contact_allocation_row_contact_ids(rows) do
    rows
    |> Enum.map(&Map.get(&1, "contact_id"))
    |> Enum.reject(&is_nil/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp validate_contact_allocation_duplicate_evidence(issues, path, row) do
    if Map.get(row, "allocation_reason") == "duplicate_contact_id" do
      ids = Map.get(row, "duplicate_contact_candidate_ids")

      issues
      |> require_fields(path, row, ["duplicate_contact_candidate_ids"])
      |> expect_field_equals(
        path,
        row,
        "duplicate_contact_candidate_count",
        if(is_list(ids), do: length(ids), else: nil)
      )
    else
      issues
    end
  end

  defp validate_contact_contention_recommendation_duplicate_evidence(issues, path, recommendation) do
    if Map.get(recommendation, "resolution_issue") == "duplicate_contact_id" or
         Map.has_key?(recommendation, "duplicate_contact_ids") do
      issues
      |> require_fields(path, recommendation, ["duplicate_contact_candidates"])
      |> expect_field_equals(
        path,
        recommendation,
        "duplicate_contact_id_count",
        list_count(recommendation, "duplicate_contact_ids")
      )
      |> expect_field_equals(
        path,
        recommendation,
        "duplicate_contact_candidate_count",
        list_count(recommendation, "duplicate_contact_candidates")
      )
      |> validate_stable_id_list(
        path <> ".duplicate_contact_ids",
        Map.get(recommendation, "duplicate_contact_ids")
      )
    else
      issues
    end
  end

  defp contact_allocation_invalid_contact_input_ids(rows) do
    rows
    |> Enum.filter(&(&1["invalid_contact_input"] == true))
    |> Enum.map(&Map.get(&1, "contact_id"))
    |> Enum.reject(&is_nil/1)
  end

  defp contact_allocation_status_blocked_contact_ids(rows) do
    rows
    |> Enum.filter(&contact_allocation_status_blocked_row?/1)
    |> Enum.map(&Map.get(&1, "contact_id"))
    |> Enum.reject(&is_nil/1)
  end

  defp contact_allocation_status_blocked_row?(row) do
    reason = row["allocation_reason"]

    is_binary(reason) and
      (String.starts_with?(reason, "activity_status_") or
         String.starts_with?(reason, "approval_status_"))
  end

  defp contact_allocation_resource_blocked_rows(rows) do
    Enum.filter(rows, &Map.has_key?(&1, "source_resource_suppression"))
  end

  defp contact_allocation_capacity_pack_rows(rows) do
    Enum.filter(rows, fn row ->
      is_map(row) and is_binary(row["capacity_pack_status"]) and
        is_number(row["required_capacity_fraction"])
    end)
  end

  defp contact_allocation_selected_capacity_pack_rows(rows) do
    Enum.filter(rows, fn row ->
      row["capacity_pack_status"] in [
        "selected_by_contention_resolution",
        "selected_by_reduced_station_capacity_pack"
      ]
    end)
  end

  defp contact_allocation_deferred_capacity_pack_rows(rows) do
    Enum.filter(
      rows,
      &(&1["capacity_pack_status"] == "deferred_by_reduced_station_capacity_pack")
    )
  end

  defp contact_allocation_capacity_pack_required_fraction(rows) do
    rows
    |> Enum.map(&Map.get(&1, "required_capacity_fraction"))
    |> Enum.filter(&is_number/1)
    |> Enum.sum()
  end

  defp contact_allocation_capacity_pack_required_fraction_by_field(rows, field) do
    rows
    |> Enum.reduce(%{}, fn row, totals ->
      field_value = Map.get(row, field)
      required_fraction = Map.get(row, "required_capacity_fraction")

      if is_nil(field_value) or not is_number(required_fraction) do
        totals
      else
        Map.update(totals, field_value, required_fraction, &(&1 + required_fraction))
      end
    end)
  end

  defp validate_ids_match_row_multiset(issues, path, report, field, expected_ids, message) do
    ids = Map.get(report, field)

    if is_list(ids) and Enum.sort(ids) != Enum.sort(expected_ids) do
      [error("#{path}.#{field}", message) | issues]
    else
      issues
    end
  end

  defp validate_optional_stable_id_array_map(issues, path, report, field) do
    issues
    |> expect_optional_type(path, report, field, :map)
    |> validate_stable_id_array_map(path <> ".#{field}", Map.get(report, field))
  end

