  defp contact_allocation_reservation_expiration_rows(rows) do
    rows
    |> Enum.filter(&contact_allocation_reservation_expiration_row?/1)
    |> Enum.map(fn row ->
      expires_at_s = contact_allocation_reservation_expires_at_s(row)

      row
      |> Map.put("station_reservation_summary_expires_at_s", expires_at_s)
      |> Map.put(
        "station_reservation_expiration_status",
        if(is_number(expires_at_s), do: "declared", else: "missing")
      )
    end)
  end

  defp contact_allocation_reservation_expiration_rows(rows, now_s) do
    rows
    |> Enum.filter(&contact_allocation_reservation_expiration_row?/1)
    |> Enum.map(fn row ->
      expires_at_s = contact_allocation_reservation_expires_at_s(row)

      row
      |> Map.put("station_reservation_summary_expires_at_s", expires_at_s)
      |> Map.put(
        "station_reservation_expiration_status",
        contact_allocation_reservation_expiration_status(expires_at_s, now_s)
      )
    end)
  end

  defp contact_allocation_reservation_expiration_status(nil, _now_s), do: "missing"
  defp contact_allocation_reservation_expiration_status(_expires_at_s, nil), do: "declared"

  defp contact_allocation_reservation_expiration_status(expires_at_s, now_s)
       when is_number(expires_at_s) and is_number(now_s) and expires_at_s <= now_s,
       do: "expired"

  defp contact_allocation_reservation_expiration_status(_expires_at_s, _now_s), do: "active"

  defp contact_allocation_reservation_expiration_row?(row) do
    Enum.any?(
      [
        row["station_reservation_id"],
        row["station_reservation_status"],
        row["station_reserved_by"],
        row["station_reservation_match_status"],
        row["station_reservation_expires_at_s"],
        row["station_calendar_reservation_ids"],
        row["station_calendar_reservation_statuses"],
        row["station_calendar_reserved_by"],
        row["station_calendar_reservation_expires_at_s"]
      ],
      &contact_allocation_pressure_value?/1
    )
  end

  defp contact_allocation_reservation_expires_at_s(row) do
    [
      row["station_reservation_expires_at_s"],
      row["station_calendar_reservation_expires_at_s"]
    ]
    |> List.flatten()
    |> Enum.find(&is_number/1)
  end

  defp contact_allocation_reservation_expiration_count(rows, status) do
    Enum.count(rows, &(&1["station_reservation_expiration_status"] == status))
  end

  defp contact_allocation_earliest_reservation_expires_at_s(rows) do
    rows
    |> Enum.map(& &1["station_reservation_summary_expires_at_s"])
    |> Enum.reject(&is_nil/1)
    |> Enum.min(fn -> nil end)
  end

  defp contact_allocation_reservation_ids_by_expiration_status(rows) do
    rows
    |> Enum.flat_map(fn row ->
      row
      |> contact_allocation_reservation_ids()
      |> Enum.map(&{row["station_reservation_expiration_status"], &1})
    end)
    |> Enum.group_by(fn {status, _id} -> status end, fn {_status, id} -> id end)
    |> Enum.reject(fn {status, ids} -> is_nil(status) or Enum.all?(ids, &is_nil/1) end)
    |> Map.new(fn {status, ids} -> {status, ids |> Enum.uniq() |> Enum.sort()} end)
  end

  defp contact_allocation_reservation_row_ids(rows) do
    rows
    |> Enum.map(&Map.get(&1, "station_reservation_id"))
    |> Enum.reject(&is_nil/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp contact_allocation_reservation_expires_at_values(rows) do
    rows
    |> Enum.map(&Map.get(&1, "station_reservation_expires_at_s"))
    |> Enum.filter(&is_number/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp contact_allocation_reservation_ids(row) do
    [
      row["station_reservation_id"],
      row["station_calendar_reservation_ids"]
    ]
    |> List.flatten()
    |> Enum.filter(&(is_binary(&1) and Regex.match?(@stable_id_regex, &1)))
  end

  defp contact_allocation_station_pressure_rows(rows) do
    Enum.filter(rows, fn row ->
      contact_allocation_pressure_value?(row["station_calendar_overlap_count"]) or
        contact_allocation_pressure_value?(row["station_calendar_overlap_availabilities"]) or
        contact_allocation_pressure_value?(row["station_calendar_entry_id"]) or
        contact_allocation_pressure_value?(row["station_reservation_match_status"]) or
        contact_allocation_pressure_value?(row["station_calendar_precedence_rank"]) or
        contact_allocation_pressure_value?(row["station_calendar_precedence_availability"]) or
        contact_allocation_source_pressure_values(row) != []
    end)
  end

  defp contact_allocation_pressure_value?(nil), do: false
  defp contact_allocation_pressure_value?([]), do: false
  defp contact_allocation_pressure_value?(value) when is_number(value), do: value > 0
  defp contact_allocation_pressure_value?(value) when is_binary(value), do: value != ""
  defp contact_allocation_pressure_value?(_value), do: true

  defp contact_allocation_station_pressure_ids_by_availability(rows) do
    rows
    |> Enum.flat_map(fn row ->
      row
      |> contact_allocation_station_pressure_availability_values()
      |> Enum.map(&{&1, row["contact_id"]})
    end)
    |> Enum.group_by(fn {availability, _contact_id} -> availability end, fn {_availability,
                                                                             contact_id} ->
      contact_id
    end)
    |> Enum.reject(fn {availability, contact_ids} ->
      is_nil(availability) or Enum.all?(contact_ids, &is_nil/1)
    end)
    |> Map.new(fn {availability, contact_ids} ->
      {availability, contact_ids |> Enum.reject(&is_nil/1) |> Enum.uniq() |> Enum.sort()}
    end)
  end

  defp contact_allocation_station_pressure_availability_values(row) do
    direct_values =
      row
      |> Map.take(["station_availability", "availability", "station_calendar_status"])
      |> Map.values()

    source_values =
      contact_allocation_source_availability_candidates(row["source_station_calendar_entry"]) ++
        contact_allocation_source_availability_candidates(row["source_station_calendar_overlaps"])

    (direct_values ++ List.wrap(row["station_calendar_overlap_availabilities"]) ++ source_values)
    |> Enum.map(&contact_allocation_status_token/1)
    |> Enum.filter(&contact_allocation_station_availability?/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp contact_allocation_source_pressure_values(row) do
    (contact_allocation_source_availability_candidates(row["source_station_calendar_entry"]) ++
       contact_allocation_source_availability_candidates(row["source_station_calendar_overlaps"]))
    |> Enum.map(&contact_allocation_status_token/1)
    |> Enum.filter(&contact_allocation_pressure_availability?/1)
    |> Enum.uniq()
  end

  defp contact_allocation_source_availability_candidates(nil), do: []

  defp contact_allocation_source_availability_candidates(entries) when is_list(entries) do
    Enum.flat_map(entries, &contact_allocation_source_availability_candidates/1)
  end

  defp contact_allocation_source_availability_candidates(%{} = entry) do
    [entry["availability"], entry["status"], entry["station_availability"]]
  end

  defp contact_allocation_source_availability_candidates(_entry), do: []

  defp contact_allocation_status_token(value) when is_binary(value) do
    value
    |> String.trim()
    |> String.downcase()
    |> String.replace(~r/[\s-]+/, "_")
    |> contact_allocation_canonical_status_token()
  end

  defp contact_allocation_status_token(value) when is_atom(value) do
    value
    |> Atom.to_string()
    |> contact_allocation_status_token()
  end

  defp contact_allocation_status_token(value), do: value

  defp contact_allocation_canonical_status_token(value)
       when value in ["outage", "down", "offline"],
       do: "unavailable"

  defp contact_allocation_canonical_status_token(value), do: value

  defp contact_allocation_station_availability?(value)
       when value in ["available", "unavailable", "maintenance", "reserved", "reduced_capacity"],
       do: true

  defp contact_allocation_station_availability?(_value), do: false

  defp contact_allocation_pressure_availability?(value)
       when value in ["unavailable", "maintenance", "reserved", "reduced_capacity"],
       do: true

  defp contact_allocation_pressure_availability?(_value), do: false

  defp validate_resource_projection_report_counts(issues, path, report) do
    projected_rows =
      report
      |> Map.get("projected_resources", [])
      |> Enum.filter(&is_map/1)

    invalid_summary_rows =
      report
      |> Map.get("invalid_resource_summary_inputs", [])
      |> case do
        rows when is_list(rows) -> Enum.filter(rows, &is_map/1)
        _rows -> []
      end

    invalid_activity_rows =
      report
      |> Map.get("invalid_activity_inputs", [])
      |> case do
        rows when is_list(rows) -> Enum.filter(rows, &is_map/1)
        _rows -> []
      end

    resource_pressure_rows =
      Enum.filter(projected_rows, &(resource_projection_pressure_types([&1]) != []))

    flow_rows = Enum.flat_map(projected_rows, &resource_projection_flow_rows/1)

    activity_count =
      if Map.has_key?(report, "valid_activity_count") do
        integer_or_zero(Map.get(report, "valid_activity_count")) + length(invalid_activity_rows)
      end

    issues
    |> expect_field_equals(
      path,
      report,
      "input_resource_summary_count",
      length(projected_rows) + length(invalid_summary_rows)
    )
    |> expect_field_equals(path, report, "valid_resource_summary_count", length(projected_rows))
    |> expect_field_equals(
      path,
      report,
      "invalid_resource_summary_input_count",
      length(invalid_summary_rows)
    )
    |> expect_field_equals(
      path,
      report,
      "invalid_resource_summary_input_ids",
      Enum.map(invalid_summary_rows, &Map.get(&1, "resource_summary_id")),
      "must equal row-derived invalid_resource_summary_input_ids"
    )
    |> expect_field_equals(
      path,
      report,
      "invalid_activity_input_count",
      length(invalid_activity_rows)
    )
    |> expect_field_equals(
      path,
      report,
      "invalid_activity_input_ids",
      Enum.map(invalid_activity_rows, &Map.get(&1, "activity_id")),
      "must equal row-derived invalid_activity_input_ids"
    )
    |> expect_field_equals(
      path,
      report,
      "activity_count",
      activity_count,
      "must equal valid_activity_count plus invalid activity inputs"
    )
    |> expect_field_equals(
      path,
      report,
      "valid_activity_count",
      row_count_difference(report, "activity_count", length(invalid_activity_rows))
    )
    |> expect_field_equals(
      path,
      report,
      "warnings",
      projected_rows |> Enum.flat_map(&Map.get(&1, "warnings", [])) |> Enum.uniq() |> Enum.sort(),
      "must equal row-derived warnings"
    )
    |> expect_field_equals(
      path,
      report,
      "resource_pressure_count",
      length(resource_pressure_rows),
      "must equal row-derived resource_pressure_count"
    )
    |> expect_field_equals(
      path,
      report,
      "resource_pressure_types",
      resource_projection_pressure_types(projected_rows),
      "must equal row-derived resource_pressure_types"
    )
    |> expect_field_equals(
      path,
      report,
      "resource_pressure_spacecraft_ids",
      resource_pressure_rows
      |> Enum.map(&Map.get(&1, "spacecraft_id"))
      |> sorted_stable_values(),
      "must equal row-derived resource_pressure_spacecraft_ids"
    )
    |> expect_field_equals(
      path,
      report,
      "resource_pressure_spacecraft_ids_by_type",
      resource_projection_pressure_spacecraft_ids_by_type(projected_rows, flow_rows),
      "must equal row-derived resource_pressure_spacecraft_ids_by_type"
    )
    |> expect_field_equals(
      path,
      report,
      "resource_pressure_activity_ids_by_type",
      resource_projection_pressure_activity_ids_by_type(flow_rows),
      "must equal row-derived resource_pressure_activity_ids_by_type"
    )
    |> validate_non_negative_integer_count_map(
      "#{path}.resource_source_quality_counts",
      Map.get(report, "resource_source_quality_counts")
    )
    |> validate_non_negative_integer_count_map(
      "#{path}.resource_trust_boundary_status_counts",
      Map.get(report, "resource_trust_boundary_status_counts")
    )
    |> expect_field_equals(
      path,
      report,
      "resource_source_quality_counts",
      frequency_map(projected_rows, "resource_source_quality"),
      "must equal row-derived resource_source_quality_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "resource_spacecraft_ids_by_source_quality",
      stable_values_by_key(
        Enum.map(
          projected_rows,
          &{Map.get(&1, "resource_source_quality"), Map.get(&1, "spacecraft_id")}
        )
      ),
      "must equal row-derived resource_spacecraft_ids_by_source_quality"
    )
    |> expect_field_equals(
      path,
      report,
      "resource_trust_boundary_status_counts",
      frequency_map(projected_rows, "resource_trust_boundary_status"),
      "must equal row-derived resource_trust_boundary_status_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "resource_spacecraft_ids_by_trust_boundary_status",
      stable_values_by_key(
        Enum.map(
          projected_rows,
          &{Map.get(&1, "resource_trust_boundary_status"), Map.get(&1, "spacecraft_id")}
        )
      ),
      "must equal row-derived resource_spacecraft_ids_by_trust_boundary_status"
    )
  end

  defp validate_resource_projection_flow_summary_counts(issues, path, summary) do
    projected_rows =
      summary
      |> Map.get("projected_resources", [])
      |> case do
        rows when is_list(rows) -> Enum.filter(rows, &is_map/1)
        _rows -> []
      end

    flow_rows =
      summary
      |> Map.get("activity_resource_flow", [])
      |> case do
        rows when is_list(rows) -> Enum.filter(rows, &is_map/1)
        _rows -> []
      end

    invalid_activity_ids = list_or_empty(Map.get(summary, "invalid_activity_input_ids"))
    invalid_summary_ids = list_or_empty(Map.get(summary, "invalid_resource_summary_input_ids"))
    pressure_rows = Enum.filter(projected_rows, &resource_projection_flow_summary_pressure_row?/1)
    pressure_types = resource_projection_flow_summary_pressure_types(projected_rows, flow_rows)
    ignored_rows = resource_projection_flow_summary_ignored_rows(flow_rows)
    latency_review_ids = resource_projection_flow_summary_latency_review_activity_ids(flow_rows)
    latency_review_count = length(latency_review_ids)
    latency_evidence_count = resource_projection_flow_summary_latency_evidence_count(flow_rows)

    invalid_input_count = length(invalid_activity_ids) + length(invalid_summary_ids)

    expected_flow_status =
      if pressure_rows == [] and invalid_input_count == 0 and latency_review_count == 0 do
        "clear"
      else
        "review_required"
      end

    issues
    |> expect_field_equals(
      path,
      summary,
      "invalid_activity_input_count",
      length(invalid_activity_ids),
      "must equal invalid_activity_input_ids count"
    )
    |> expect_field_equals(
      path,
      summary,
      "invalid_resource_summary_input_count",
      length(invalid_summary_ids),
      "must equal invalid_resource_summary_input_ids count"
    )
    |> expect_field_equals(
      path,
      summary,
      "activity_count",
      integer_or_zero(Map.get(summary, "valid_activity_count")) + length(invalid_activity_ids),
      "must equal valid_activity_count plus invalid_activity_input_ids count"
    )
    |> expect_field_equals(
      path,
      summary,
      "input_resource_summary_count",
      integer_or_zero(Map.get(summary, "valid_resource_summary_count")) +
        length(invalid_summary_ids),
      "must equal valid_resource_summary_count plus invalid_resource_summary_input_ids count"
    )
    |> expect_field_equals(
      path,
      summary,
      "projected_resource_count",
      length(projected_rows),
      "must equal projected_resources count"
    )
    |> expect_field_equals(
      path,
      summary,
      "valid_resource_summary_count",
      length(projected_rows),
      "must equal projected_resources count"
    )
    |> expect_field_equals(
      path,
      summary,
      "flow_row_count",
      length(flow_rows),
      "must equal activity_resource_flow row count"
    )
    |> expect_field_equals(
      path,
      summary,
      "ignored_activity_count",
      length(ignored_rows),
      "must equal ignored activity_resource_flow row count"
    )
    |> expect_field_equals(
      path,
      summary,
      "ignored_activity_reason_counts",
      resource_projection_flow_summary_ignored_activity_reason_counts(ignored_rows),
      "must equal ignored activity_resource_flow reason counts"
    )
    |> expect_field_equals(
      path,
      summary,
      "ignored_activity_ids",
      resource_projection_flow_summary_ignored_activity_ids(ignored_rows),
      "must equal ignored activity_resource_flow activity IDs"
    )
    |> expect_field_equals(
      path,
