  defp resource_projection_flow_summary_pressure_row?(row) do
    Map.get(row, "resource_pressure_types", []) != [] or
      Map.get(row, "resource_pressure_status") in [
        "review_required",
        "storage_overflow",
        "downlink_shortfall",
        "battery_depletion"
      ]
  end

  defp resource_projection_flow_summary_pressure_types(projected_rows, flow_rows) do
    projected_types =
      projected_rows
      |> Enum.flat_map(fn
        %{} = row -> Map.get(row, "resource_pressure_types", [])
        _row -> []
      end)

    flow_types =
      flow_rows
      |> Enum.flat_map(&resource_projection_pressure_kinds/1)

    (projected_types ++ flow_types)
    |> Enum.reject(&is_nil/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp resource_projection_flow_summary_ignored_rows(flow_rows) do
    Enum.filter(flow_rows, &(Map.get(&1, "resource_effect_status") == "ignored"))
  end

  defp resource_projection_flow_summary_ignored_activity_ids(rows) do
    rows
    |> Enum.map(&Map.get(&1, "activity_id"))
    |> sorted_stable_values()
  end

  defp resource_projection_flow_summary_ignored_activity_reason_counts(rows) do
    rows
    |> Enum.map(&Map.get(&1, "resource_effect_reason"))
    |> Enum.reject(&is_nil/1)
    |> Enum.frequencies()
  end

  defp resource_projection_flow_summary_ignored_activity_ids_by_reason(rows) do
    rows
    |> Enum.map(&{Map.get(&1, "resource_effect_reason"), Map.get(&1, "activity_id")})
    |> stable_values_by_key()
  end

  defp resource_projection_flow_summary_spacecraft_ids_by_type(projected_rows, flow_rows) do
    projected_pairs =
      Enum.flat_map(projected_rows, fn
        %{} = row ->
          row
          |> Map.get("resource_pressure_types", [])
          |> Enum.map(&{&1, Map.get(row, "spacecraft_id")})

        _row ->
          []
      end)

    flow_pairs =
      Enum.flat_map(flow_rows, fn row ->
        Enum.map(resource_projection_pressure_kinds(row), &{&1, Map.get(row, "spacecraft_id")})
      end)

    stable_values_by_key(projected_pairs ++ flow_pairs)
  end

