  defp resource_projection_pressure_capacity_fractions_by_type(flow_rows) do
    flow_rows
    |> Enum.flat_map(fn
      %{} = row ->
        case Map.get(row, "capacity_fraction") do
          value when is_number(value) ->
            Enum.map(resource_projection_pressure_kinds(row), &{&1, value})

          _value ->
            []
        end

      _row ->
        []
    end)
    |> number_values_by_key()
  end

  defp resource_projection_flow_summary_latency_status(_evidence_count, review_count)
       when review_count > 0,
       do: "review_required"

  defp resource_projection_flow_summary_latency_status(evidence_count, _review_count)
       when evidence_count > 0,
       do: "clear"

  defp resource_projection_flow_summary_latency_status(_evidence_count, _review_count), do: nil

  defp resource_projection_flow_summary_latency_evidence_count(flow_rows) do
    Enum.count(flow_rows, fn row ->
      Enum.any?(
        ~w(collection_ends_at_s planned_delivery_at_s actual_delivery_at_s max_latency_s planned_latency_s actual_latency_s),
        &Map.has_key?(row, &1)
      )
    end)
  end

  defp resource_projection_flow_summary_latency_review_activity_ids(flow_rows) do
    flow_rows
    |> Enum.filter(&(Map.get(&1, "latency_status") == "late"))
    |> Enum.map(&Map.get(&1, "activity_id"))
    |> sorted_stable_values()
  end

  defp resource_projection_pressure_types(projected_rows) do
    projection_pressure_types =
      projected_rows
      |> Enum.flat_map(fn
        %{} = row -> Map.get(row, "resource_pressure_types", [])
        _row -> []
      end)

    flow_pressure_types =
      projected_rows
      |> Enum.flat_map(&resource_projection_flow_rows/1)
      |> Enum.map(&resource_projection_pressure_kind/1)
      |> Enum.reject(&is_nil/1)

    (projection_pressure_types ++ flow_pressure_types)
    |> Enum.reject(&is_nil/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp resource_projection_pressure_spacecraft_ids_by_type(projected_rows, flow_rows) do
    projected_pairs =
      Enum.flat_map(projected_rows, fn
        %{} = row ->
          row
          |> Map.get("resource_pressure_types", [])
          |> Enum.map(&{&1, Map.get(row, "spacecraft_id")})

        _row ->
          []
      end)

    flow_pairs =
      Enum.flat_map(flow_rows, fn row ->
        Enum.map(resource_projection_pressure_kinds(row), &{&1, Map.get(row, "spacecraft_id")})
      end)

    stable_values_by_key(projected_pairs ++ flow_pairs)
