  defp resource_projection_pressure_activity_ids_by_type(flow_rows) do
    flow_rows
    |> Enum.flat_map(fn row ->
      Enum.map(resource_projection_pressure_kinds(row), &{&1, Map.get(row, "activity_id")})
    end)
    |> stable_values_by_key()
  end

  defp resource_projection_flow_rows(%{
         "activity_resource_flow" => flow_rows,
         "spacecraft_id" => id
       })
       when is_list(flow_rows) do
    Enum.map(flow_rows, fn
      %{} = row -> Map.put_new(row, "spacecraft_id", id)
      row -> row
    end)
  end

  defp resource_projection_flow_rows(_row), do: []

  defp resource_projection_pressure_kind(%{"storage_overflow_mb" => value})
       when is_number(value) and value > 0.0,
       do: "storage_overflow"

  defp resource_projection_pressure_kind(%{"downlink_shortfall_mb" => value})
       when is_number(value) and value > 0.0,
       do: "downlink_shortfall"

  defp resource_projection_pressure_kind(%{"battery_overuse_wh" => value})
       when is_number(value) and value > 0.0,
       do: "battery_depletion"

  defp resource_projection_pressure_kind(%{"resource_effect_reason" => reason})
       when reason in [
              "spacecraft_unavailable",
              "payload_unavailable",
              "spacecraft_degraded_payload_unavailable",
              "activity_type_suppressed_by_resource_summary",
              "activity_type_incompatible_with_resource_summary",
              "antenna_unavailable"
            ],
       do: reason

  defp resource_projection_pressure_kind(_row), do: nil

  defp resource_projection_pressure_kinds(row) do
    []
    |> maybe_add_resource_projection_pressure_kind(row, "storage_overflow", "storage_overflow_mb")
    |> maybe_add_resource_projection_pressure_kind(
      row,
      "downlink_shortfall",
      "downlink_shortfall_mb"
    )
    |> maybe_add_resource_projection_pressure_kind(row, "battery_depletion", "battery_overuse_wh")
    |> maybe_add_resource_projection_availability_pressure_kind(row)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp maybe_add_resource_projection_pressure_kind(types, row, type, field) do
    case Map.get(row, field) do
      value when is_number(value) and value > 0.0 -> [type | types]
      _value -> types
    end
  end

  defp maybe_add_resource_projection_availability_pressure_kind(
         types,
         %{"resource_effect_reason" => reason}
       )
       when reason in [
              "spacecraft_unavailable",
              "payload_unavailable",
              "spacecraft_degraded_payload_unavailable",
              "activity_type_suppressed_by_resource_summary",
              "activity_type_incompatible_with_resource_summary",
              "antenna_unavailable"
            ],
       do: [reason | types]

  defp maybe_add_resource_projection_availability_pressure_kind(types, _row), do: types

  defp stable_values_by_key(pairs) do
    pairs
    |> Enum.reject(fn {key, value} -> key in [nil, ""] or value in [nil, ""] end)
    |> Enum.group_by(fn {key, _value} -> key end, fn {_key, value} -> value end)
    |> Map.new(fn {key, values} -> {key, sorted_stable_values(values)} end)
  end

  defp number_values_by_key(pairs) do
    pairs
    |> Enum.reject(fn {key, value} -> key in [nil, ""] or not is_number(value) end)
    |> Enum.group_by(fn {key, _value} -> key end, fn {_key, value} -> value end)
    |> Map.new(fn {key, values} -> {key, values |> Enum.uniq() |> Enum.sort()} end)
  end

  defp sorted_stable_values(values) do
    values
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.map(&to_string/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp resource_projection_report_model_limits do
    OrbitalDynamics.ResourceProjection.capabilities()
    |> Map.fetch!(:known_limits)
    |> Enum.map(&Atom.to_string/1)
  end

  defp resource_projection_report_models do
    [
      "thin_battery_handoff_resource_projection_fixture",
      "thin_campaign_selected_activity_resource_projection",
      "thin_repaired_activity_resource_projection",
      "thin_selected_activity_resource_projection",
      "thin_stale_derived_margin_resource_projection_fixture",
      "thin_strategy_branch_activity_resource_projection"
    ]
  end

  defp validate_resource_projection_row_counts(issues, path, row) do
    flow_rows =
      case Map.fetch(row, "activity_resource_flow") do
        {:ok, flow} when is_list(flow) -> Enum.filter(flow, &is_map/1)
        _flow -> nil
      end

    flow_ignored_ids =
      if is_list(flow_rows) do
        flow_rows
        |> Enum.filter(&(Map.get(&1, "resource_effect_status") == "ignored"))
        |> Enum.map(&Map.get(&1, "activity_id"))
      end

    projected_flow_rows =
      if is_list(flow_rows) do
        Enum.reject(flow_rows, &(Map.get(&1, "resource_effect_status") == "ignored"))
      end

    issues
    |> expect_field_equals(
      path,
      row,
      "activity_count",
      if(is_list(flow_rows), do: length(flow_rows), else: nil),
      "must equal activity_resource_flow row count"
    )
    |> expect_field_equals(
      path,
      row,
      "effective_activity_count",
      if(is_list(projected_flow_rows), do: length(projected_flow_rows), else: nil),
      "must equal projected activity_resource_flow row count"
    )
    |> expect_field_equals(
      path,
      row,
      "observation_count",
      if(is_list(projected_flow_rows),
        do: Enum.count(projected_flow_rows, &(Map.get(&1, "activity_type") == "observe")),
        else: nil
      ),
      "must equal projected observe flow row count"
    )
    |> expect_field_equals(
      path,
      row,
      "downlink_count",
      if(is_list(projected_flow_rows),
        do: Enum.count(projected_flow_rows, &resource_projection_downlink_flow_row?/1),
        else: nil
      ),
      "must equal projected downlink flow row count"
    )
    |> expect_field_equals(
      path,
      row,
      "ignored_activity_count",
      if(is_list(flow_ignored_ids), do: length(flow_ignored_ids), else: nil)
    )
    |> expect_field_equals(
      path,
      row,
      "ignored_activity_ids",
      flow_ignored_ids,
      "must match ignored activity flow row IDs"
    )
  end

