  defp provider_counteroffer_numeric_rows(rows, field) do
    Enum.filter(rows, fn row -> is_number(Map.get(row, field)) end)
  end

  defp provider_counteroffer_timing_shift_rows(rows) do
    Enum.filter(rows, fn row ->
      Enum.any?(
        [
          row["provider_counteroffer_start_delta_s"],
          row["provider_counteroffer_end_delta_s"],
          row["provider_counteroffer_duration_delta_s"]
        ],
        fn value -> is_number(value) and value != 0.0 end
      )
    end)
  end

  defp provider_counteroffer_ids(rows),
    do: provider_counteroffer_stable_ids(rows, "provider_counteroffer_id")

  defp provider_counteroffer_stable_ids(rows, field) do
    rows
    |> Enum.map(&Map.get(&1, field))
    |> Enum.filter(&is_binary/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp provider_counteroffer_ids_by(rows, field) do
    rows
    |> Enum.group_by(&Map.get(&1, field), &Map.get(&1, "provider_counteroffer_id"))
    |> Enum.reject(fn {key, _ids} -> is_nil(key) end)
    |> Map.new(fn {key, ids} ->
      {key, ids |> Enum.filter(&is_binary/1) |> Enum.uniq() |> Enum.sort()}
    end)
  end

  defp provider_counteroffer_status_count(rows, field, status) do
    Enum.count(rows, &(Map.get(&1, field) == status))
  end

  defp provider_counteroffer_numeric_value_count(rows, field) do
    rows
    |> provider_counteroffer_numeric_values(field)
    |> length()
  end

  defp provider_counteroffer_numeric_value_sum(rows, field) do
    rows
    |> provider_counteroffer_numeric_values(field)
    |> Enum.sum()
  end

  defp provider_counteroffer_numeric_value_min(rows, field) do
    rows
    |> provider_counteroffer_numeric_values(field)
    |> Enum.min(fn -> nil end)
  end

  defp provider_counteroffer_numeric_values(rows, field) do
    rows
    |> Enum.map(&Map.get(&1, field))
    |> Enum.filter(&is_number/1)
  end

  defp validate_optional_candidate_rejection_report(issues, _path, nil), do: issues

  defp validate_optional_candidate_rejection_report(issues, path, %{} = report) do
    issues
    |> require_fields(path, report, @contracts[@candidate_rejection_report]["required_fields"])
    |> validate_candidate_rejection_report(path, report)
  end

  defp validate_optional_candidate_rejection_report(issues, path, _report),
    do: [error(path, "must be an object") | issues]

  defp candidate_rejection_reason_frequency_map(rows) do
    rows
    |> Enum.flat_map(&Map.get(&1, "rejection_reasons", []))
    |> Enum.frequencies()
  end

  defp candidate_rejection_row_ids(rows, predicate) do
    rows
    |> Enum.filter(predicate)
    |> Enum.map(&Map.get(&1, "candidate_id"))
    |> Enum.reject(&is_nil/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp candidate_id_sets_by_rejection_reason(rows) do
    rows
    |> Enum.flat_map(fn row ->
      row
      |> Map.get("rejection_reasons", [])
      |> Enum.map(&{&1, Map.get(row, "candidate_id")})
    end)
    |> Enum.group_by(fn {reason, _candidate_id} -> reason end, fn {_reason, candidate_id} ->
      candidate_id
    end)
    |> Map.new(fn {reason, candidate_ids} ->
      candidate_ids =
        candidate_ids
        |> Enum.reject(&is_nil/1)
        |> Enum.uniq()
        |> Enum.sort()

      {reason, candidate_ids}
    end)
  end

  defp validate_candidate_id_sets_by_rejection_reason(issues, _path, nil), do: issues

  defp validate_candidate_id_sets_by_rejection_reason(issues, path, %{} = reason_ids) do
    allowed_reasons = OrbitalDynamics.Timeline.capabilities().candidate_rejection_reasons

    Enum.reduce(reason_ids, issues, fn {reason, candidate_ids}, acc ->
      acc =
        if reason in allowed_reasons,
          do: acc,
          else: [error("#{path}.#{reason}", "must use a supported rejection reason") | acc]

      case candidate_ids do
        ids when is_list(ids) ->
          validate_stable_id_list(acc, "#{path}.#{reason}", ids)

        _value ->
          [error("#{path}.#{reason}", "must be a list") | acc]
      end
    end)
  end

  defp validate_candidate_id_sets_by_rejection_reason(issues, path, _reason_ids),
    do: [error(path, "must be an object") | issues]

  defp validate_candidate_ids_by_required_operator_action(issues, _path, nil), do: issues

  defp validate_candidate_ids_by_required_operator_action(issues, path, %{} = action_ids) do
    allowed_actions = OrbitalDynamics.Timeline.capabilities().candidate_rejection_actions

    Enum.reduce(action_ids, issues, fn {action, candidate_ids}, acc ->
      acc =
        if action in allowed_actions,
          do: acc,
          else: [
            error("#{path}.#{action}", "must use a supported candidate rejection action") | acc
          ]

      case candidate_ids do
        ids when is_list(ids) ->
          validate_stable_id_list(acc, "#{path}.#{action}", ids)

        _value ->
          [error("#{path}.#{action}", "must be a list") | acc]
      end
    end)
  end

  defp validate_candidate_ids_by_required_operator_action(issues, path, _action_ids),
    do: [error(path, "must be an object") | issues]

  defp candidate_ids_by_required_operator_action(rows) do
    rows
    |> Enum.group_by(&Map.get(&1, "required_operator_action"), &Map.get(&1, "candidate_id"))
    |> Map.new(fn {action, candidate_ids} ->
      candidate_ids =
        candidate_ids
        |> Enum.reject(&is_nil/1)
        |> Enum.uniq()
        |> Enum.sort()

      {action, candidate_ids}
    end)
  end

  defp operational_approved_row?(row),
    do: row["approval_status"] in ["approved", "auto_approvable"]

  defp operational_executed_row?(row), do: row["status"] in ["completed", "partial", "executed"]

  defp operational_terminal_exception_row?(row) do
    row["status"] in ["missed", "failed", "canceled", "cancelled", "rejected"] or
      row["operator_action_reason"] in [
        "contact_success_false_requires_review",
        "command_success_false_requires_review"
      ] or operational_provider_result_failure?(row["contact_result"]) or
      operational_provider_result_failure?(row["command_result"])
  end

  defp operational_provider_result_failure?(result) when is_binary(result) do
    result
    |> String.split(",", trim: true)
    |> Enum.map(&String.trim/1)
    |> Enum.map(&String.downcase/1)
    |> Enum.map(&String.replace(&1, ~r/[\s-]+/, "_"))
    |> Enum.any?(
      &(&1 in [
          "rejected",
          "failed",
          "failure",
          "timeout",
          "timed_out",
          "aborted",
          "error",
          "dropped",
          "lost",
          "missed",
          "canceled",
          "cancelled",
          "no_contact"
        ])
    )
  end

  defp operational_provider_result_failure?(_result), do: false

  defp operational_dependency_row?(row) do
    non_empty_list?(row["dependency_activity_ids"]) or
      non_empty_list?(row["dependency_timeline_ids"])
  end

  defp operational_exclusivity_row?(row) do
    non_empty_list?(row["exclusive_with_activity_ids"]) or
      non_empty_list?(row["exclusive_with_timeline_ids"])
  end

  defp operational_dependency_issue_count(rows) do
    rows
    |> Enum.flat_map(&list_value(&1, "timeline_integrity_issues"))
    |> Enum.count(fn issue ->
      is_map(issue) and dependency_issue_type?(Map.get(issue, "type"))
    end)
  end

  defp operational_exclusivity_issue_count(rows) do
    rows
    |> Enum.flat_map(&list_value(&1, "timeline_integrity_issues"))
    |> Enum.count(fn issue ->
      is_map(issue) and exclusivity_issue_type?(Map.get(issue, "type"))
    end)
  end

  defp dependency_issue_type?(type) when is_binary(type), do: String.contains?(type, "dependency")
  defp dependency_issue_type?(_type), do: false

  defp exclusivity_issue_type?(type) when is_binary(type),
    do: String.contains?(type, "exclusivity")

  defp exclusivity_issue_type?(_type), do: false

  defp operational_duplicate_timeline_group_count(rows) do
    rows
    |> operational_rows_by_timeline_id()
    |> Enum.count(fn {_timeline_id, grouped_rows} -> length(grouped_rows) > 1 end)
  end

  defp operational_duplicate_timeline_activity_count(rows) do
    rows
    |> operational_rows_by_timeline_id()
    |> Enum.filter(fn {_timeline_id, grouped_rows} -> length(grouped_rows) > 1 end)
    |> Enum.reduce(0, fn {_timeline_id, grouped_rows}, total -> total + length(grouped_rows) end)
  end

  defp operational_rows_by_timeline_id(rows) do
    rows
    |> Enum.group_by(&Map.get(&1, "timeline_id"))
    |> Enum.reject(fn {timeline_id, _rows} -> is_nil(timeline_id) end)
  end

  defp operational_invalid_activity_ids(rows) do
    rows
    |> Enum.filter(&(&1["invalid_activity_input"] == true))
    |> Enum.map(&Map.get(&1, "activity_id"))
    |> Enum.reject(&is_nil/1)
  end

  defp non_empty_list?(value), do: is_list(value) and value != []
  defp list_value(map, key) when is_map(map), do: Map.get(map, key) || []
  defp list_value(_map, _key), do: []

  defp validate_timeline_integrity_evidence(issues, path, row) do
    issues =
      case Map.get(row, "timeline_integrity_issues") do
        issues_list when is_list(issues_list) ->
          issues_list
          |> Enum.with_index()
          |> Enum.reduce(issues, fn {issue, index}, acc ->
            acc =
              if is_map(issue) do
                require_fields(acc, "#{path}.timeline_integrity_issues[#{index}]", issue, [
                  "type"
                ])
              else
                [error("#{path}.timeline_integrity_issues[#{index}]", "must be an object") | acc]
              end

            issue_type = if is_map(issue), do: Map.get(issue, "type")

            if is_binary(issue_type) and
                 issue_type not in OrbitalDynamics.Timeline.capabilities().timeline_integrity_issue_types do
              [
                error(
                  "#{path}.timeline_integrity_issues[#{index}].type",
                  "must be one of #{inspect(OrbitalDynamics.Timeline.capabilities().timeline_integrity_issue_types)}"
                )
                | acc
              ]
            else
              validate_timeline_integrity_issue_evidence(
                acc,
                "#{path}.timeline_integrity_issues[#{index}]",
                issue
              )
            end
          end)

        _issues ->
          issues
      end

    issue_types = Map.get(row, "timeline_integrity_issue_types")
    issues_list = Map.get(row, "timeline_integrity_issues")

    issues
    |> expect_field_equals(
      path,
      row,
      "timeline_integrity_issue_count",
      if(is_list(issues_list), do: length(issues_list), else: nil),
      "must match timeline_integrity_issues length"
    )
    |> expect_field_equals(
      path,
      row,
      "timeline_integrity_issue_types",
      if is_list(issues_list) do
        issues_list
        |> Enum.filter(&is_map/1)
        |> Enum.map(&Map.get(&1, "type"))
        |> Enum.reject(&is_nil/1)
        |> Enum.uniq()
        |> Enum.sort()
      else
        nil
      end,
      "must match timeline_integrity_issues types"
    )
    |> expect_field_equals(
      path,
      row,
      "missing_dependency_activity_ids",
      timeline_integrity_issue_ids(issues_list, "missing_dependency_activity_id"),
      "must match timeline_integrity_issues missing_dependency_activity_id values"
    )
    |> expect_field_equals(
      path,
      row,
      "self_dependency_activity_ids",
      timeline_integrity_issue_ids(issues_list, "self_dependency_activity_id"),
      "must match timeline_integrity_issues self_dependency_activity_id values"
    )
    |> expect_field_equals(
      path,
      row,
      "self_dependency_timeline_ids",
      timeline_integrity_issue_ids(issues_list, "self_dependency_timeline_id"),
      "must match timeline_integrity_issues self_dependency_timeline_id values"
    )
    |> expect_field_equals(
      path,
      row,
      "duplicate_dependency_activity_ids",
      timeline_integrity_issue_ids(issues_list, "duplicate_dependency_activity_id"),
      "must match timeline_integrity_issues duplicate_dependency_activity_id values"
    )
    |> expect_field_equals(
      path,
      row,
      "duplicate_dependency_timeline_ids",
      timeline_integrity_issue_ids(issues_list, "duplicate_dependency_timeline_id"),
      "must match timeline_integrity_issues duplicate_dependency_timeline_id values"
    )
    |> expect_field_equals(
      path,
      row,
      "duplicate_exclusivity_activity_ids",
      timeline_integrity_issue_ids(issues_list, "duplicate_exclusivity_activity_id"),
      "must match timeline_integrity_issues duplicate_exclusivity_activity_id values"
    )
    |> expect_field_equals(
      path,
      row,
      "duplicate_exclusivity_timeline_ids",
      timeline_integrity_issue_ids(issues_list, "duplicate_exclusivity_timeline_id"),
      "must match timeline_integrity_issues duplicate_exclusivity_timeline_id values"
    )
    |> then(fn acc ->
      if is_list(issue_types) do
        validate_string_list_allowed(
          acc,
          path,
          row,
          "timeline_integrity_issue_types",
          OrbitalDynamics.Timeline.capabilities().timeline_integrity_issue_types
        )
      else
        acc
      end
    end)
  end

  defp validate_timeline_integrity_issue_evidence(issues, path, issue) when is_map(issue) do
    issues =
      issue
      |> Map.take([
        "missing_dependency_activity_id",
        "missing_dependency_timeline_id",
        "self_dependency_activity_id",
        "self_dependency_timeline_id",
        "duplicate_dependency_activity_id",
        "duplicate_dependency_timeline_id",
        "duplicate_exclusivity_activity_id",
        "duplicate_exclusivity_timeline_id",
        "dependency_activity_id",
        "dependency_timeline_id",
        "exclusivity_violation_activity_id",
        "exclusivity_violation_timeline_id"
      ])
      |> Enum.reduce(issues, fn {field, value}, acc ->
        validate_stable_id(acc, "#{path}.#{field}", value)
      end)

    cond do
      Map.get(issue, "type") == "exclusivity_group_overlap" and
          not Map.has_key?(issue, "exclusivity_violation_group") ->
        [error(path <> ".exclusivity_violation_group", "is required") | issues]

      issue
      |> Map.keys()
      |> Enum.any?(&String.ends_with?(&1, "_id")) ->
        issues

      Map.has_key?(issue, "exclusivity_violation_group") ->
        issues

      Map.get(issue, "type") == "dependency_cycle" ->
        [error(path, "must include one of the timeline integrity evidence identifiers") | issues]

      true ->
        issues
    end
  end

  defp validate_timeline_integrity_issue_evidence(issues, _path, _issue), do: issues

  defp timeline_integrity_issue_ids(issues_list, field) when is_list(issues_list) do
    issues_list
    |> Enum.filter(&is_map/1)
    |> Enum.map(&Map.get(&1, field))
    |> Enum.reject(&is_nil/1)
    |> Enum.sort()
  end

  defp timeline_integrity_issue_ids(_issues_list, _field), do: nil

  defp validate_cadence_import_manifest(issues, path, manifest) do
    rows = Map.get(manifest, "rows", [])
    capability = OrbitalDynamics.CadenceImport.capability()

    issues
    |> expect_equal(path, manifest, "schema_contract", "cadence_import_manifest.v1")
    |> expect_equal(path, manifest, "model", "artifact_only_cadence_import_manifest")
    |> validate_stable_ids(path, manifest, ["manifest_id", "source_artifact_id"])
    |> validate_cadence_import_manifest_scalar_counts(path, manifest)
    |> expect_optional_type(path, manifest, "import_action_counts", :map)
    |> expect_optional_type(path, manifest, "import_status_counts", :map)
    |> expect_optional_type(path, manifest, "cadence_import_status_counts", :map)
    |> expect_optional_type(path, manifest, "source_review_type_counts", :map)
    |> expect_optional_type(path, manifest, "source_review_action_counts", :map)
    |> expect_optional_type(path, manifest, "source_review_queue_counts", :map)
    |> expect_optional_type(path, manifest, "calendar_entry_trust_boundary_status_counts", :map)
    |> expect_optional_type(path, manifest, "station_reservation_ids", :list)
    |> validate_optional_stable_id_list(path, manifest, "station_reservation_ids")
    |> expect_optional_type(path, manifest, "station_reserved_bys", :list)
    |> validate_string_list_items(path, manifest, "station_reserved_bys")
    |> expect_optional_type(path, manifest, "station_reservation_statuses", :list)
    |> validate_string_list_items(path, manifest, "station_reservation_statuses")
    |> expect_optional_type(path, manifest, "station_reservation_match_status_counts", :map)
    |> validate_contact_allocation_expiration_handoff_summary(path, manifest)
    |> validate_quality_gate_handoff_summary(path, manifest)
    |> expect_optional_type(path, manifest, "model_limits", :list)
    |> validate_string_list_items(path, manifest, "model_limits")
    |> validate_optional_exact_model_limits(
      path,
      manifest,
      cadence_import_manifest_model_limits(),
      "must match Cadence import manifest model limits"
    )
    |> validate_cadence_import_manifest_assumptions(path, manifest)
    |> expect_type(path, manifest, "rows", :list)
    |> validate_rows(path <> ".rows", rows, &validate_cadence_import_row/3)
    |> validate_suppression_duplicate_handoff_groups(path, rows)
    |> validate_non_negative_integer_count_map(
      path <> ".import_action_counts",
      Map.get(manifest, "import_action_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".import_status_counts",
      Map.get(manifest, "import_status_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".cadence_import_status_counts",
      Map.get(manifest, "cadence_import_status_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".source_review_type_counts",
      Map.get(manifest, "source_review_type_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".source_review_action_counts",
      Map.get(manifest, "source_review_action_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".source_review_queue_counts",
      Map.get(manifest, "source_review_queue_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".calendar_entry_trust_boundary_status_counts",
      Map.get(manifest, "calendar_entry_trust_boundary_status_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".station_reservation_match_status_counts",
      Map.get(manifest, "station_reservation_match_status_counts")
    )
    |> validate_contact_allocation_expiration_handoff_summary(path, manifest)
    |> expect_field_equals(
      path,
      manifest,
      "row_count",
      if(is_list(rows), do: length(rows), else: nil)
    )
    |> expect_field_equals(
      path,
      manifest,
      "ready_count",
      rows
      |> Enum.filter(&is_map/1)
      |> Enum.count(&(Map.get(&1, "import_status") == "ready_for_import"))
    )
    |> expect_field_equals(
      path,
      manifest,
      "review_required_count",
      rows
      |> Enum.filter(&is_map/1)
      |> Enum.count(&(Map.get(&1, "import_status") == "review_required_before_import"))
    )
    |> expect_field_equals(
      path,
      manifest,
      "blocked_count",
      rows
      |> Enum.filter(&is_map/1)
      |> Enum.count(&(Map.get(&1, "import_status") == "blocked_missing_cadence_import"))
    )
    |> expect_field_equals(
      path,
      manifest,
      "missing_import_count",
      rows
      |> Enum.filter(&is_map/1)
      |> Enum.count(&(Map.get(&1, "cadence_import_status") == "missing"))
    )
    |> expect_field_equals(
      path,
      manifest,
      "import_action_counts",
      rows |> Enum.filter(&is_map/1) |> frequency_map("import_action"),
      "must equal row-derived import_action_counts"
    )
    |> expect_field_equals(
      path,
      manifest,
      "import_status_counts",
      rows |> Enum.filter(&is_map/1) |> frequency_map("import_status"),
      "must equal row-derived import_status_counts"
    )
    |> expect_field_equals(
      path,
      manifest,
      "cadence_import_status_counts",
      rows |> Enum.filter(&is_map/1) |> frequency_map("cadence_import_status"),
      "must equal row-derived cadence_import_status_counts"
    )
    |> expect_field_equals(
      path,
      manifest,
      "source_review_type_counts",
      rows |> Enum.filter(&is_map/1) |> frequency_map("source_review_type"),
      "must equal row-derived source_review_type_counts"
    )
    |> expect_field_equals(
      path,
      manifest,
      "source_review_action_counts",
      rows |> Enum.filter(&is_map/1) |> frequency_map("source_review_action"),
      "must equal row-derived source_review_action_counts"
    )
    |> expect_field_equals(
      path,
      manifest,
      "source_review_queue_counts",
      rows |> Enum.filter(&is_map/1) |> frequency_map("source_review_queue_key"),
      "must equal row-derived source_review_queue_counts"
    )
    |> expect_optional_one_of(
      path,
      manifest,
      "source_artifact_type",
      capability.supported_sources
    )
  end

  defp validate_cadence_import_manifest_assumptions(issues, path, manifest) do
    case Map.get(manifest, "assumptions") do
      %{} = assumptions ->
        [
          {"execution_boundary", "artifact_only_no_cadence_api_writes"},
          {"authorization_boundary", "operator_review_or_cadence_adapter_must_authorize_import"}
        ]
        |> Enum.reduce(issues, fn {field, expected}, acc ->
          if Map.has_key?(assumptions, field) and Map.get(assumptions, field) != expected do
            [error("#{path}.assumptions.#{field}", "must equal #{inspect(expected)}") | acc]
          else
            acc
          end
        end)

      _assumptions ->
        issues
    end
  end

  defp validate_cadence_import_manifest_scalar_counts(issues, path, manifest) do
    Enum.reduce(@cadence_import_manifest_scalar_count_fields, issues, fn field, acc ->
      expect_non_negative_integer(acc, path, manifest, field)
    end)
  end

  defp validate_operational_readiness_report(issues, path, report) do
    gates = Map.get(report, "gates", [])
    evidence = Map.get(report, "evidence", %{})
    capability = OrbitalDynamics.OperationalReadiness.capabilities()

    issues
    |> expect_equal(path, report, "schema_contract", "operational_readiness_report.v1")
    |> expect_equal(path, report, "model", "artifact_only_operational_readiness_classifier")
    |> validate_stable_ids(path, report, ["report_id", "source_artifact_id"])
    |> expect_one_of(path, report, "readiness_level", capability.readiness_levels)
    |> expect_one_of(path, report, "import_classification", capability.import_classifications)
    |> expect_one_of(path, report, "status", capability.gate_statuses)
    |> expect_non_negative_integer(path, report, "gate_count")
    |> expect_non_negative_integer(path, report, "passed_gate_count")
    |> expect_non_negative_integer(path, report, "review_gate_count")
    |> expect_non_negative_integer(path, report, "analysis_gate_count")
    |> expect_non_negative_integer(path, report, "blocked_gate_count")
    |> expect_type(path, report, "gates", :list)
    |> validate_rows(path <> ".gates", gates, &validate_operational_readiness_gate/3)
    |> expect_type(path, report, "evidence", :map)
    |> validate_operational_readiness_evidence(path <> ".evidence", evidence)
    |> expect_type(path, report, "assumptions", :list)
    |> validate_string_list_items(path, report, "assumptions")
    |> expect_type(path, report, "model_limits", :list)
    |> validate_string_list_items(path, report, "model_limits")
    |> validate_optional_exact_model_limits(
      path,
      report,
      operational_readiness_model_limits(),
      "must match operational readiness model limits"
    )
    |> validate_operational_readiness_assumptions(path, report)
    |> validate_operational_readiness_classification(path, report, gates)
    |> validate_operational_readiness_evidence_gate_counts(path <> ".evidence", evidence, gates)
    |> expect_field_equals(path, report, "gate_count", if(is_list(gates), do: length(gates)))
    |> expect_field_equals(
      path,
      report,
      "passed_gate_count",
      gate_status_count(gates, "passed")
    )
    |> expect_field_equals(
      path,
      report,
      "review_gate_count",
      gate_status_count(gates, "review_required")
    )
    |> expect_field_equals(
      path,
      report,
      "analysis_gate_count",
      gate_status_count(gates, "analysis_only")
    )
    |> expect_field_equals(
      path,
      report,
      "blocked_gate_count",
      gate_status_count(gates, "blocked")
    )
  end

  defp validate_operational_readiness_assumptions(issues, path, report) do
    assumptions = Map.get(report, "assumptions")

    required_assumptions = [
      "classification_uses_declared_operator_review_and_cadence_import_manifest_evidence",
      "cadence_import_manifest_rows_are_adapter_handoff_not_external_import_writes"
    ]

    if is_list(assumptions) and Enum.all?(required_assumptions, &(&1 in assumptions)) do
      issues
    else
      [
        error(
          path <> ".assumptions",
          "must include operational readiness artifact-only assumptions"
        )
        | issues
      ]
    end
  end

  defp validate_operational_readiness_classification(issues, path, report, gates)
       when is_list(gates) do
    import_classification = operational_readiness_import_classification(gates)
    readiness_level = operational_readiness_level(import_classification)
    status = operational_readiness_report_status(import_classification)

    issues
    |> expect_field_equals(
      path,
      report,
      "import_classification",
      import_classification,
      "must match gate-derived import classification"
    )
    |> expect_field_equals(
      path,
      report,
      "readiness_level",
      readiness_level,
      "must match gate-derived readiness level"
    )
    |> expect_field_equals(
      path,
      report,
      "status",
      status,
      "must match gate-derived report status"
    )
  end

  defp validate_operational_readiness_classification(issues, _path, _report, _gates),
    do: issues

  defp operational_readiness_import_classification(gates) do
    statuses =
      gates
      |> Enum.filter(&is_map/1)
      |> Enum.map(&Map.get(&1, "status"))

    cond do
      "blocked" in statuses -> "blocked"
      "analysis_only" in statuses -> "analysis_only"
      "review_required" in statuses -> "review_only"
      true -> "importable"
    end
  end

  defp operational_readiness_level("importable"), do: "import_eligible"
  defp operational_readiness_level("review_only"), do: "operator_review"
  defp operational_readiness_level("analysis_only"), do: "analysis_only"
  defp operational_readiness_level("blocked"), do: "blocked"

  defp operational_readiness_report_status("importable"), do: "passed"
  defp operational_readiness_report_status("review_only"), do: "review_required"
  defp operational_readiness_report_status("analysis_only"), do: "analysis_only"
  defp operational_readiness_report_status("blocked"), do: "blocked"

  defp validate_operational_import_eligibility_summary(issues, path, summary) do
    non_passed_gates = Map.get(summary, "non_passed_gates", [])
    capability = OrbitalDynamics.OperationalReadiness.capabilities()

    issues
    |> expect_equal(path, summary, "schema_contract", "operational_import_eligibility_summary.v1")
    |> expect_equal(path, summary, "model", "artifact_only_import_eligibility_summary")
    |> expect_equal(path, summary, "source", "operational_readiness_report.v1")
    |> expect_type(path, summary, "source_artifact_type", :binary)
    |> validate_stable_ids(path, summary, ["source_artifact_id"])
    |> expect_one_of(path, summary, "readiness_level", capability.readiness_levels)
    |> expect_one_of(path, summary, "import_classification", capability.import_classifications)
    |> expect_one_of(path, summary, "status", capability.gate_statuses)
    |> expect_type(path, summary, "import_eligible", :boolean)
    |> expect_non_negative_integer(path, summary, "gate_count")
