  defp validate_operational_import_eligibility_summary_counts(issues, path, summary) do
    passed_count = Map.get(summary, "passed_gate_count")
    review_count = Map.get(summary, "review_gate_count")
    analysis_count = Map.get(summary, "analysis_gate_count")
    blocked_count = Map.get(summary, "blocked_gate_count")

    total_count =
      non_negative_integer_sum([passed_count, review_count, analysis_count, blocked_count])

    non_passed_count =
      non_negative_integer_sum([review_count, analysis_count, blocked_count])

    non_passed_gates =
      case Map.get(summary, "non_passed_gates", []) do
        gates when is_list(gates) -> Enum.filter(gates, &is_map/1)
        _gates -> []
      end

    issues
    |> expect_field_equals(
      path,
      summary,
      "gate_count",
      total_count,
      "must equal gate status counts"
    )
    |> expect_field_equals(
      path,
      summary,
      "non_passed_gate_count",
      non_passed_count,
      "must equal review, analysis, and blocked gate counts"
    )
    |> expect_field_equals(
      path,
      summary,
      "non_passed_gate_count",
      length(non_passed_gates),
      "must equal non-passed gate row count"
    )
    |> expect_field_equals(
      path,
      summary,
      "review_gate_count",
      gate_status_count(non_passed_gates, "review_required"),
      "must equal non-passed review gate count"
    )
    |> expect_field_equals(
      path,
      summary,
      "analysis_gate_count",
      gate_status_count(non_passed_gates, "analysis_only"),
      "must equal non-passed analysis gate count"
    )
    |> expect_field_equals(
      path,
      summary,
      "blocked_gate_count",
      gate_status_count(non_passed_gates, "blocked"),
      "must equal non-passed blocked gate count"
    )
  end

