  defp validate_operational_execution_boundary_summary_mode(issues, path, summary) do
    operational_mode_gate = Map.get(summary, "operational_mode_gate")

    issues =
      case operational_mode_gate do
        %{} = gate ->
          issues
          |> expect_equal(path <> ".operational_mode_gate", gate, "id", "operational_mode")
          |> expect_field_equals(
            path,
            summary,
            "analysis_mode",
            Map.get(gate, "analysis_mode"),
            "must match operational_mode_gate.analysis_mode"
          )
          |> expect_field_equals(
            path,
            summary,
            "analysis_mode_source",
            Map.get(gate, "analysis_mode_source"),
            "must match operational_mode_gate.analysis_mode_source"
          )

        _gate ->
          issues
      end

    if is_map(operational_mode_gate) and
         is_binary(Map.get(operational_mode_gate, "analysis_mode")) and
         not Map.has_key?(summary, "analysis_mode") do
      [error(path <> ".analysis_mode", "must match operational_mode_gate.analysis_mode") | issues]
    else
      issues
    end
  end

  defp non_negative_integer_sum(values) do
    if Enum.all?(values, &(is_integer(&1) and &1 >= 0)), do: Enum.sum(values)
  end

  defp validate_operational_readiness_evidence_gate_counts(issues, path, evidence, gates)
       when is_map(evidence) and is_list(gates) do
    scalar_fields = [
      "ready_for_import_count",
      "manifest_review_required_count",
      "blocked_import_count",
      "missing_import_count",
      "invalid_cadence_import_count",
