    |> validate_optional_stable_id_list(path, summary, "analysis_only_quality_gate_row_ids")
    |> expect_type(path, summary, "assumptions", :map)
    |> expect_type(path, summary, "model_limits", :list)
    |> validate_string_list_items(path, summary, "model_limits")
    |> validate_optional_exact_model_limits(
      path,
      summary,
      quality_gate_import_readiness_summary_model_limits(),
      "must match quality gate import-readiness summary model limits"
    )
    |> validate_operational_quality_gate_import_readiness_summary_assumptions(path, summary)
    |> validate_operational_quality_gate_import_readiness_summary_counts(path, summary)
    |> validate_operational_quality_gate_import_readiness_summary_id_sets(path, summary)
    |> validate_timeline_publication_context(path, summary)
  end

  defp validate_operational_quality_gate_import_readiness_summary_id_list_types(
         issues,
         path,
         summary
       ) do
    [
      "review_required_quality_gate_row_ids",
      "blocked_quality_gate_row_ids",
      "ready_quality_gate_row_ids",
      "stale_or_unknown_freshness_quality_gate_row_ids",
      "import_preparation_quality_gate_row_ids",
      "blocked_import_quality_gate_row_ids",
      "import_readiness_gate_ids"
    ]
    |> Enum.reduce(issues, fn field, acc ->
      acc
      |> expect_type(path, summary, field, :list)
      |> validate_stable_id_list(path <> ".#{field}", Map.get(summary, field))
    end)
  end

  defp validate_operational_quality_gate_import_readiness_summary_assumptions(
         issues,
         path,
         summary
       ) do
    case Map.get(summary, "assumptions") do
      %{} = assumptions ->
        [
          {"source", "quality_gate_report.v1"},
          {"execution_boundary", "artifact_only_no_cadence_write"},
          {"operator_authority", "not_granted_by_import_readiness_summary"},
          {"cadence_write", "not_performed_by_summary"},
          {"command_execution", "not_performed_by_summary"}
        ]
        |> Enum.reduce(issues, fn {field, expected}, acc ->
          expect_equal(acc, path <> ".assumptions", assumptions, field, expected)
        end)

      _assumptions ->
        issues
    end
  end

  defp validate_operational_quality_gate_import_readiness_summary_counts(
         issues,
         path,
         summary
       ) do
    freshness_counts = Map.get(summary, "freshness_status_counts")
    import_counts = Map.get(summary, "import_status_counts")
    cadence_import_counts = Map.get(summary, "cadence_import_status_counts")

    issues
    |> expect_field_equals(
      path,
      summary,
      "import_readiness_row_count",
      stable_id_array_map_value_count(Map.get(summary, "quality_gate_row_ids_by_status")),
      "must equal quality-gate row IDs by status count"
    )
    |> expect_field_equals(
      path,
      summary,
      "ready_for_import_count",
      non_negative_integer_map_value(import_counts, "ready_for_import"),
      "must equal import_status_counts ready_for_import count"
    )
    |> expect_field_equals(
      path,
      summary,
      "manifest_review_required_count",
      non_negative_integer_map_value(import_counts, "review_required_before_import"),
      "must equal import_status_counts review_required_before_import count"
    )
    |> expect_field_equals(
      path,
      summary,
      "blocked_import_count",
      non_negative_integer_map_value(import_counts, "blocked_missing_cadence_import"),
      "must equal import_status_counts blocked_missing_cadence_import count"
    )
    |> expect_field_equals(
      path,
      summary,
      "missing_import_count",
      non_negative_integer_map_value(cadence_import_counts, "missing"),
      "must equal cadence_import_status_counts missing count"
    )
    |> expect_field_equals(
      path,
      summary,
      "invalid_cadence_import_count",
      non_negative_integer_map_value(cadence_import_counts, "invalid"),
      "must equal cadence_import_status_counts invalid count"
    )
    |> expect_field_equals(
      path,
      summary,
      "current_freshness_count",
      non_negative_integer_map_value(freshness_counts, "current"),
      "must equal freshness_status_counts current count"
    )
    |> expect_field_equals(
      path,
      summary,
      "stale_freshness_count",
      non_negative_integer_map_value(freshness_counts, "stale"),
      "must equal freshness_status_counts stale count"
    )
    |> expect_field_equals(
      path,
      summary,
      "unknown_freshness_count",
      non_negative_integer_map_value(freshness_counts, "unknown"),
      "must equal freshness_status_counts unknown count"
    )
    |> expect_field_equals(
      path,
      summary,
      "freshness_status_ids",
      positive_count_map_keys(freshness_counts),
      "must equal freshness_status_counts keys with positive counts"
    )
    |> expect_field_equals(
      path,
      summary,
      "import_status_ids",
      positive_count_map_keys(import_counts),
      "must equal import_status_counts keys with positive counts"
    )
    |> expect_field_equals(
      path,
      summary,
      "cadence_import_status_ids",
      positive_count_map_keys(cadence_import_counts),
      "must equal cadence_import_status_counts keys with positive counts"
    )
    |> expect_field_equals(
      path,
      summary,
      "freshness_review_required",
      import_readiness_freshness_review_required?(summary),
      "must match stale or unknown freshness evidence"
    )
    |> expect_field_equals(
      path,
      summary,
      "import_preparation_required",
      import_readiness_preparation_required?(summary),
      "must match review-required or missing import evidence"
    )
    |> expect_field_equals(
      path,
      summary,
      "import_blocked",
      import_readiness_blocked?(summary),
      "must match blocked or invalid import evidence"
    )
  end

  defp validate_operational_quality_gate_import_readiness_summary_id_sets(
         issues,
         path,
         summary
       ) do
    quality_gate_row_ids_by_status = Map.get(summary, "quality_gate_row_ids_by_status")

    issues
    |> expect_field_equals(
      path,
      summary,
      "review_required_quality_gate_row_ids",
      if(is_map(quality_gate_row_ids_by_status),
        do: Map.get(quality_gate_row_ids_by_status, "review_required", [])
      ),
      "must equal review-required quality-gate row IDs by status"
    )
    |> expect_field_equals(
      path,
      summary,
      "blocked_quality_gate_row_ids",
      if(is_map(quality_gate_row_ids_by_status),
        do: Map.get(quality_gate_row_ids_by_status, "blocked", [])
      ),
      "must equal blocked quality-gate row IDs by status"
    )
    |> expect_field_equals(
      path,
      summary,
      "ready_quality_gate_row_ids",
      if(is_map(quality_gate_row_ids_by_status),
        do: Map.get(quality_gate_row_ids_by_status, "passed", [])
      ),
      "must equal passed quality-gate row IDs by status"
    )
    |> expect_optional_field_equals(
      path,
      summary,
      "analysis_only_quality_gate_row_ids",
      if(is_map(quality_gate_row_ids_by_status),
        do: Map.get(quality_gate_row_ids_by_status, "analysis_only", [])
      ),
      "must equal analysis-only quality-gate row IDs by status"
    )
    |> expect_field_equals(
      path,
      summary,
      "import_readiness_gate_ids",
      stable_id_array_map_ids(Map.get(summary, "quality_gate_ids_by_status")),
      "must equal quality-gate IDs by status"
    )
    |> validate_import_readiness_routing_ids(
      path,
      summary,
      "stale_or_unknown_freshness_quality_gate_row_ids",
      import_readiness_freshness_review_required?(summary),
      "must match stale or unknown freshness routing"
    )
    |> validate_import_readiness_routing_ids(
      path,
      summary,
      "import_preparation_quality_gate_row_ids",
      import_readiness_preparation_required?(summary),
      "must match review-required or missing import routing"
    )
    |> validate_import_readiness_routing_ids(
      path,
      summary,
      "blocked_import_quality_gate_row_ids",
      import_readiness_blocked?(summary),
      "must match blocked or invalid import routing"
    )
  end

  defp validate_import_readiness_routing_ids(issues, path, summary, field, expected?, message) do
    routing_ids = Map.get(summary, field)
    row_ids = stable_id_array_map_ids(Map.get(summary, "quality_gate_row_ids_by_status"))

    cond do
      expected? == nil or not is_list(routing_ids) or not is_list(row_ids) ->
        issues

      not schema_validation_summary_subset?(routing_ids, row_ids) ->
        [error(path <> ".#{field}", "must be present in quality-gate row IDs by status") | issues]

      expected? and routing_ids == [] ->
        [error(path <> ".#{field}", message) | issues]

      not expected? and routing_ids != [] ->
        [error(path <> ".#{field}", message) | issues]

      true ->
        issues
    end
  end

  defp import_readiness_freshness_review_required?(summary) when is_map(summary) do
    with stale when is_integer(stale) <- Map.get(summary, "stale_freshness_count"),
         unknown when is_integer(unknown) <- Map.get(summary, "unknown_freshness_count") do
      stale > 0 or unknown > 0
    else
      _value -> nil
    end
  end

  defp import_readiness_preparation_required?(summary) when is_map(summary) do
    with review when is_integer(review) <- Map.get(summary, "manifest_review_required_count"),
         missing when is_integer(missing) <- Map.get(summary, "missing_import_count") do
      review > 0 or missing > 0
    else
      _value -> nil
    end
  end

  defp import_readiness_blocked?(summary) when is_map(summary) do
    with blocked when is_integer(blocked) <- Map.get(summary, "blocked_import_count"),
         invalid when is_integer(invalid) <- Map.get(summary, "invalid_cadence_import_count") do
      blocked > 0 or invalid > 0
    else
      _value -> nil
    end
  end

  defp positive_count_map_keys(counts) when is_map(counts) do
    if Enum.all?(counts, fn {_key, count} -> is_integer(count) and count >= 0 end) do
      counts
      |> Enum.filter(fn {_key, count} -> count > 0 end)
      |> Enum.map(fn {key, _count} -> key end)
      |> Enum.sort()
    end
  end

  defp positive_count_map_keys(_counts), do: nil

  defp validate_quality_gate_report(issues, path, report) do
    rows = Map.get(report, "rows", [])
    capability = OrbitalDynamics.OperationalReadiness.capabilities()

    issues
    |> expect_equal(path, report, "schema_contract", "quality_gate_report.v1")
    |> expect_equal(path, report, "model", "artifact_only_operational_quality_gate_report")
    |> validate_stable_ids(path, report, [
      "report_id",
      "source_artifact_id",
      "source_readiness_report_id"
    ])
    |> expect_one_of(path, report, "readiness_level", capability.readiness_levels)
    |> expect_one_of(path, report, "import_classification", capability.import_classifications)
    |> expect_one_of(path, report, "status", capability.gate_statuses)
    |> expect_equal(path, report, "handoff_only", true)
    |> expect_equal(path, report, "execution_allowed", false)
    |> expect_equal(path, report, "cadence_write_allowed", false)
    |> expect_equal(path, report, "operator_authority_granted", false)
    |> expect_non_negative_integer(path, report, "gate_count")
    |> expect_non_negative_integer(path, report, "passed_gate_count")
    |> expect_non_negative_integer(path, report, "review_gate_count")
    |> expect_non_negative_integer(path, report, "analysis_gate_count")
    |> expect_non_negative_integer(path, report, "blocked_gate_count")
    |> expect_type(path, report, "gate_status_counts", :map)
    |> expect_type(path, report, "gate_classification_counts", :map)
    |> validate_non_negative_integer_count_map(
      path <> ".gate_status_counts",
      Map.get(report, "gate_status_counts")
    )
    |> validate_non_negative_integer_count_map(
      path <> ".gate_classification_counts",
      Map.get(report, "gate_classification_counts")
    )
    |> expect_field_equals(
      path,
      report,
      "gate_status_counts",
      if(is_list(rows), do: frequency_map(rows, "status")),
      "must match gate status counts from rows"
    )
    |> expect_field_equals(
      path,
      report,
      "gate_classification_counts",
      if(is_list(rows), do: frequency_map(rows, "classification")),
      "must match gate classification counts from rows"
    )
    |> expect_optional_type(path, report, "gate_ids_by_status", :map)
    |> validate_stable_id_array_map(
      path <> ".gate_ids_by_status",
      Map.get(report, "gate_ids_by_status")
    )
    |> expect_field_equals(
      path,
      report,
      "gate_ids_by_status",
      quality_gate_ids_by(rows, "status"),
      "must match gate IDs grouped by row status"
    )
    |> expect_optional_type(path, report, "gate_ids_by_classification", :map)
    |> validate_stable_id_array_map(
      path <> ".gate_ids_by_classification",
      Map.get(report, "gate_ids_by_classification")
    )
    |> expect_field_equals(
      path,
      report,
      "gate_ids_by_classification",
      quality_gate_ids_by(rows, "classification"),
      "must match gate IDs grouped by row classification"
    )
    |> expect_optional_type(path, report, "quality_gate_row_ids_by_status", :map)
    |> validate_stable_id_array_map(
      path <> ".quality_gate_row_ids_by_status",
      Map.get(report, "quality_gate_row_ids_by_status")
    )
    |> expect_field_equals(
      path,
      report,
      "quality_gate_row_ids_by_status",
      quality_gate_row_ids_by(rows, "status"),
      "must match quality-gate row IDs grouped by row status"
    )
    |> expect_optional_type(path, report, "quality_gate_row_ids_by_classification", :map)
    |> validate_stable_id_array_map(
      path <> ".quality_gate_row_ids_by_classification",
      Map.get(report, "quality_gate_row_ids_by_classification")
    )
    |> expect_field_equals(
      path,
      report,
      "quality_gate_row_ids_by_classification",
      quality_gate_row_ids_by(rows, "classification"),
      "must match quality-gate row IDs grouped by row classification"
    )
    |> expect_optional_type(path, report, "passed_gate_ids", :list)
    |> validate_optional_stable_id_list(path, report, "passed_gate_ids")
    |> expect_field_equals(
      path,
      report,
      "passed_gate_ids",
      quality_gate_ids(rows, "passed"),
      "must match passed gate IDs"
    )
    |> expect_optional_type(path, report, "review_required_gate_ids", :list)
    |> validate_optional_stable_id_list(path, report, "review_required_gate_ids")
    |> expect_field_equals(
      path,
      report,
      "review_required_gate_ids",
      quality_gate_ids(rows, "review_required"),
      "must match review-required gate IDs"
    )
    |> expect_optional_type(path, report, "analysis_only_gate_ids", :list)
    |> validate_optional_stable_id_list(path, report, "analysis_only_gate_ids")
    |> expect_field_equals(
      path,
      report,
      "analysis_only_gate_ids",
      quality_gate_ids(rows, "analysis_only"),
      "must match analysis-only gate IDs"
    )
    |> expect_optional_type(path, report, "blocked_gate_ids", :list)
    |> validate_optional_stable_id_list(path, report, "blocked_gate_ids")
    |> expect_field_equals(
      path,
      report,
      "blocked_gate_ids",
      quality_gate_ids(rows, "blocked"),
      "must match blocked gate IDs"
    )
    |> expect_type(path, report, "rows", :list)
    |> validate_rows(path <> ".rows", rows, &validate_quality_gate_row/3)
    |> expect_type(path, report, "assumptions", :map)
    |> expect_type(path, report, "model_limits", :list)
    |> validate_string_list_items(path, report, "model_limits")
    |> validate_optional_exact_model_limits(
      path,
      report,
      quality_gate_report_model_limits(),
      "must match quality gate report model limits"
    )
    |> validate_quality_gate_report_assumptions(path, report)
    |> validate_quality_gate_report_classification(path, report, rows)
    |> expect_field_equals(path, report, "gate_count", if(is_list(rows), do: length(rows)))
    |> expect_field_equals(
      path,
      report,
      "passed_gate_count",
      quality_gate_status_count(rows, "passed")
    )
    |> expect_field_equals(
      path,
      report,
      "review_gate_count",
      quality_gate_status_count(rows, "review_required")
    )
    |> expect_field_equals(
      path,
      report,
      "analysis_gate_count",
      quality_gate_status_count(rows, "analysis_only")
    )
    |> expect_field_equals(
      path,
      report,
      "blocked_gate_count",
      quality_gate_status_count(rows, "blocked")
    )
  end

  defp validate_quality_gate_report_assumptions(issues, path, report) do
    case Map.get(report, "assumptions") do
      %{} = assumptions ->
        [
          {"execution_boundary", "artifact_only_no_cadence_write"},
          {"operator_authority", "not_granted_by_quality_gate_report"},
          {"source", "operational_readiness_report.v1"}
        ]
        |> Enum.reduce(issues, fn {field, expected}, acc ->
          if Map.has_key?(assumptions, field) and Map.get(assumptions, field) != expected do
            [error("#{path}.assumptions.#{field}", "must equal #{inspect(expected)}") | acc]
          else
            acc
          end
        end)

      _assumptions ->
        issues
    end
  end

  defp validate_quality_gate_report_classification(issues, path, report, rows)
       when is_list(rows) do
    import_classification = operational_readiness_import_classification(rows)
    readiness_level = operational_readiness_level(import_classification)
    status = operational_readiness_report_status(import_classification)
    execution_boundary = quality_gate_execution_boundary(import_classification)

    issues
    |> expect_field_equals(
      path,
      report,
      "import_classification",
      import_classification,
      "must match row-derived import classification"
    )
    |> expect_field_equals(
      path,
      report,
      "readiness_level",
      readiness_level,
      "must match row-derived readiness level"
    )
    |> expect_field_equals(
      path,
      report,
      "status",
      status,
      "must match row-derived report status"
    )
    |> expect_field_equals(
      path,
      report,
      "execution_boundary",
      execution_boundary,
      "must match row-derived execution boundary"
    )
  end

  defp validate_quality_gate_report_classification(issues, _path, _report, _rows), do: issues

  defp quality_gate_execution_boundary("importable"), do: "adapter_handoff_only"

  defp quality_gate_execution_boundary("review_only"),
    do: "operator_review_required_before_import"

  defp quality_gate_execution_boundary("analysis_only"), do: "analysis_only_not_for_execution"

  defp quality_gate_execution_boundary("blocked"), do: "blocked_not_for_import_or_execution"

  defp validate_quality_gate_row(issues, path, row) do
    capability = OrbitalDynamics.OperationalReadiness.capabilities()

    issues
    |> require_fields(path, row, ["id", "rank", "gate_id", "status", "classification", "reason"])
    |> validate_stable_ids(path, row, ["id"])
    |> expect_non_negative_integer(path, row, "rank")
    |> expect_one_of(path, row, "gate_id", capability.gates)
    |> expect_one_of(path, row, "status", capability.gate_statuses)
    |> expect_one_of(path, row, "classification", capability.import_classifications)
    |> expect_type(path, row, "reason", :binary)
    |> expect_optional_one_of(path, row, "analysis_mode", capability.analysis_modes)
    |> expect_optional_type(path, row, "analysis_mode_source", :binary)
    |> expect_optional_type(path, row, "source_operational_readiness_gate", :map)
    |> validate_source_operational_readiness_gate_handoff_matches(path, row)
    |> validate_source_operational_readiness_report_handoff_matches(path, row)
    |> validate_operational_readiness_resource_context(path, row)
    |> validate_operational_readiness_operator_training_context(path, row)
    |> validate_operational_readiness_adapter_boundary_context(path, row)
    |> validate_operational_readiness_cadence_import_context(path, row)
    |> validate_timeline_publication_context(path, row)
  end

  defp validate_operational_readiness_operator_training_context(issues, path, row) do
    issues
    |> expect_optional_non_negative_integer(path, row, "operator_training_requirement_count")
    |> expect_optional_type(path, row, "operator_training_requirement_counts", :map)
    |> validate_non_negative_integer_count_map(
      path <> ".operator_training_requirement_counts",
      Map.get(row, "operator_training_requirement_counts")
    )
    |> expect_field_equals(
      path,
      row,
      "operator_training_requirement_count",
      non_negative_integer_map_sum(Map.get(row, "operator_training_requirement_counts")),
      "must equal operator_training_requirement_counts sum"
    )
    |> expect_optional_type(path, row, "required_operator_roles", :list)
    |> validate_string_list_items(path, row, "required_operator_roles")
    |> expect_optional_type(path, row, "required_training_ids", :list)
    |> validate_string_list_items(path, row, "required_training_ids")
    |> expect_optional_type(path, row, "required_certification_ids", :list)
    |> validate_string_list_items(path, row, "required_certification_ids")
    |> expect_optional_type(path, row, "required_qualification_ids", :list)
    |> validate_string_list_items(path, row, "required_qualification_ids")
  end

  defp validate_operational_readiness_resource_context(issues, path, row) do
    issues
    |> expect_optional_non_negative_integer(path, row, "resource_availability_pressure_count")
    |> expect_optional_type(path, row, "resource_availability_reason_counts", :map)
    |> validate_non_negative_integer_count_map(
      path <> ".resource_availability_reason_counts",
      Map.get(row, "resource_availability_reason_counts")
    )
    |> expect_field_equals(
      path,
      row,
      "resource_availability_pressure_count",
      non_negative_integer_map_sum(Map.get(row, "resource_availability_reason_counts")),
      "must equal resource_availability_reason_counts sum"
    )
    |> expect_optional_type(path, row, "resource_availability_reason_ids", :list)
    |> validate_string_list_items(path, row, "resource_availability_reason_ids")
    |> expect_field_equals(
      path,
      row,
      "resource_availability_reason_ids",
      resource_availability_reason_ids(Map.get(row, "resource_availability_reason_counts")),
      "must equal resource_availability_reason_counts keys with positive counts"
    )
    |> expect_optional_type(path, row, "unavailable_resource_reason_ids", :list)
    |> validate_string_list_items(path, row, "unavailable_resource_reason_ids")
    |> expect_field_equals(
      path,
      row,
      "unavailable_resource_reason_ids",
      unavailable_resource_reason_ids(Map.get(row, "resource_availability_reason_counts")),
      "must equal unavailable resource reason IDs from resource_availability_reason_counts"
    )
    |> expect_optional_type(path, row, "station_availability_reason_ids", :list)
    |> validate_string_list_items(path, row, "station_availability_reason_ids")
    |> expect_field_equals(
      path,
      row,
      "station_availability_reason_ids",
      station_availability_reason_ids(Map.get(row, "resource_availability_reason_counts")),
      "must equal station availability reason IDs from resource_availability_reason_counts"
    )
    |> expect_optional_type(path, row, "station_availability_reason_counts", :map)
    |> validate_non_negative_integer_count_map(
      path <> ".station_availability_reason_counts",
      Map.get(row, "station_availability_reason_counts")
    )
    |> expect_field_equals(
      path,
      row,
      "station_availability_reason_counts",
      station_availability_reason_counts(Map.get(row, "resource_availability_reason_counts")),
      "must equal station availability reason counts from resource_availability_reason_counts"
    )
