    )
  end

  defp resource_availability_reason_ids(counts) when is_map(counts) do
    if Enum.all?(counts, fn {_reason, count} -> is_integer(count) and count >= 0 end) do
      counts
      |> Enum.filter(fn {_reason, count} -> count > 0 end)
      |> Enum.map(fn {reason, _count} -> reason end)
      |> Enum.sort()
    end
  end

  defp resource_availability_reason_ids(_counts), do: nil

  defp unavailable_resource_reason_ids(counts) when is_map(counts) do
    case resource_availability_reason_ids(counts) do
      nil ->
        nil

      reason_ids ->
        reason_ids
        |> Enum.filter(&(&1 in unavailable_resource_reasons()))
        |> Enum.sort()
    end
  end

  defp unavailable_resource_reason_ids(_counts), do: nil

  defp station_availability_reason_ids(counts) when is_map(counts) do
    case resource_availability_reason_ids(counts) do
      nil ->
        nil

      reason_ids ->
        reason_ids
        |> Enum.filter(&(&1 in station_availability_reasons()))
        |> Enum.sort()
    end
  end

  defp station_availability_reason_ids(_counts), do: nil

  defp station_availability_reason_counts(counts) when is_map(counts) do
    if Enum.all?(counts, fn {_reason, count} -> is_integer(count) and count >= 0 end) do
      counts
      |> Enum.filter(fn {reason, count} ->
        reason in station_availability_reasons() and count > 0
      end)
      |> Map.new()
    end
  end

  defp station_availability_reason_counts(_counts), do: nil

  defp unavailable_resource_reasons do
    ~w(
      antenna_unavailable
      payload_unavailable
      spacecraft_degraded_payload_unavailable
      spacecraft_unavailable
    )
  end

  defp station_availability_reasons do
    ~w(
      ground_station_capacity_zero
      ground_station_reduced_capacity_insufficient
      ground_station_reserved
      ground_station_unavailable
    )
  end

