  defp validate_cadence_source_review_row(issues, path, _row),
    do: [error(path, "must be an object") | issues]

  defp row_count_difference(report, field, subtract) do
    case Map.get(report, field) do
      value when is_number(value) -> value - subtract
      _value -> nil
    end
  end

  defp row_count_sum(report, fields) do
    values = Enum.map(fields, &Map.get(report, &1))

    if Enum.all?(values, &is_number/1) do
      Enum.sum(values)
    end
  end

  defp list_count(map, field) do
    case Map.get(map, field) do
      values when is_list(values) -> length(values)
      _value -> nil
    end
  end

  defp sum_row_numbers(rows, field) do
    Enum.reduce(rows, 0, fn row, total ->
      case Map.get(row, field) do
        value when is_number(value) -> total + value
        _value -> total
      end
    end)
  end

  defp concat_row_lists(rows, field) do
    rows
    |> Enum.flat_map(fn row ->
      case Map.get(row, field) do
        values when is_list(values) -> values
        _value -> []
      end
    end)
  end

  defp concat_optional_row_lists(rows, field) do
    case concat_row_lists(rows, field) do
      [] -> nil
      values -> values
    end
  end

  defp optional_sorted_unique_binary_list(report, field) do
    case Map.get(report, field) do
      values when is_list(values) ->
        sorted_unique_binary_values(values)

      _values ->
        nil
    end
  end

  defp sorted_unique_binary_values(values) do
    values
    |> Enum.filter(&is_binary/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp row_unique_values(rows, field) do
    rows
    |> Enum.map(&Map.get(&1, field))
    |> Enum.reject(&is_nil/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp row_ids_by_field(rows, group_field, id_field) do
    rows
    |> Enum.filter(&is_map/1)
    |> Enum.group_by(&Map.get(&1, group_field), &Map.get(&1, id_field))
    |> Enum.reject(fn {group, ids} -> is_nil(group) or Enum.all?(ids, &is_nil/1) end)
    |> Map.new(fn {group, ids} ->
      {group, ids |> Enum.reject(&is_nil/1) |> Enum.uniq() |> Enum.sort()}
    end)
  end

  defp row_ids_by_field_value(rows, field, value, id_field) do
    rows
    |> Enum.filter(&(is_map(&1) and Map.get(&1, field) == value))
    |> Enum.map(&Map.get(&1, id_field))
    |> Enum.reject(&is_nil/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp row_ids_by_string_field(rows, group_field, id_field) do
    rows
    |> row_ids_by_field(group_field, id_field)
    |> Map.new(fn {group, ids} -> {to_string(group), ids} end)
  end

  defp row_ids_by_direction_and_ground_station(rows, id_field) do
    rows
    |> Enum.filter(&is_map/1)
    |> Enum.reduce(%{}, fn row, acc ->
      direction = Map.get(row, "direction")
      ground_station_id = Map.get(row, "ground_station_id")
      id = Map.get(row, id_field)

      if direction in [nil, ""] or ground_station_id in [nil, ""] or id in [nil, ""] do
        acc
      else
        Map.update(acc, direction, %{ground_station_id => [id]}, fn station_map ->
          Map.update(station_map, ground_station_id, [id], fn ids -> [id | ids] end)
        end)
      end
    end)
    |> Map.new(fn {direction, station_map} ->
      {direction,
       Map.new(station_map, fn {ground_station_id, ids} ->
         {ground_station_id, ids |> Enum.uniq() |> Enum.sort()}
       end)}
    end)
  end

  defp id_array_count_map(id_arrays) when is_map(id_arrays) do
    Map.new(id_arrays, fn {group, ids} ->
      {group, length(Enum.filter(ids, &is_binary/1))}
    end)
  end

  defp invalid_contact_input_ids(report, field, id_field) do
    case Map.get(report, field) do
      rows when is_list(rows) ->
        rows
        |> Enum.filter(&is_map/1)
        |> Enum.map(&Map.get(&1, id_field))

      _rows ->
        []
    end
  end

  defp merge_row_count_maps(rows, field) do
    rows
    |> Enum.map(&Map.get(&1, field))
    |> Enum.filter(&is_map/1)
    |> Enum.reduce(%{}, fn counts, acc ->
      Enum.reduce(counts, acc, fn {key, value}, inner_acc ->
        if is_number(value), do: Map.update(inner_acc, key, value, &(&1 + value)), else: inner_acc
      end)
    end)
  end

  defp frequency_map(rows, field) do
    rows
    |> Enum.map(&Map.get(&1, field))
    |> Enum.reject(&is_nil/1)
    |> Enum.frequencies()
  end

  defp nested_frequency_map(rows, field, nested_field) do
    rows
    |> Enum.map(&get_in(&1, [field, nested_field]))
    |> Enum.reject(&is_nil/1)
    |> Enum.frequencies()
  end

  defp changed_field_frequency_map(rows) do
    rows
    |> Enum.flat_map(fn row ->
      case Map.get(row, "changed_fields") do
        fields when is_list(fields) -> fields
        _fields -> []
      end
    end)
    |> Enum.frequencies()
  end

  defp expect_field_equals(issues, path, map, field, nil),
    do: expect_field_equals(issues, path, map, field, nil, nil)

  defp expect_field_equals(issues, path, map, field, expected),
    do: expect_field_equals(issues, path, map, field, expected, "must equal #{expected}")

  defp expect_field_equals(issues, _path, _map, _field, nil, _message), do: issues

  defp expect_field_equals(issues, path, map, field, expected, message) do
    if Map.has_key?(map, field) and Map.get(map, field) != expected do
      [error("#{path}.#{field}", message) | issues]
    else
      issues
    end
  end

  defp expect_optional_field_equals(issues, path, map, field, expected, message) do
    if Map.has_key?(map, field) and Map.get(map, field) != expected do
      [error("#{path}.#{field}", message) | issues]
    else
      issues
    end
  end

  defp expect_field_matches_list_count(issues, path, map, count_field, list_field, message) do
    expected = list_count(map, list_field)

    if is_integer(expected) do
      expect_field_equals(issues, path, map, count_field, expected, message)
    else
      issues
    end
  end

  defp expect_optional_list_field_equals(issues, path, map, field, expected, message) do
    value = Map.get(map, field)

    cond do
      (is_nil(value) or not Map.has_key?(map, field)) and expected == [] ->
        issues

      Map.has_key?(map, field) and value != expected ->
        [error("#{path}.#{field}", message) | issues]

      true ->
        issues
    end
  end

  defp expect_number_field_equals(issues, _path, _map, _field, nil, _message), do: issues

  defp expect_number_field_equals(issues, path, map, field, expected, message)
       when is_number(expected) do
    value = Map.get(map, field)

    cond do
      not Map.has_key?(map, field) ->
        issues

      is_number(value) and abs(value - expected) <= 1.0e-9 ->
        issues

      true ->
        [error("#{path}.#{field}", message) | issues]
    end
  end

  defp expect_field_at_least(issues, _path, _map, _field, nil), do: issues

  defp expect_field_at_least(issues, path, map, field, minimum) do
    value = Map.get(map, field)

    if Map.has_key?(map, field) and is_number(value) and value < minimum do
      [error("#{path}.#{field}", "must be at least #{minimum}") | issues]
    else
      issues
    end
  end

  defp expect_field_at_most(issues, path, map, field, maximum) do
    value = Map.get(map, field)

    if Map.has_key?(map, field) and is_number(value) and value > maximum do
      [error("#{path}.#{field}", "must be at most #{maximum}") | issues]
    else
      issues
    end
  end

  defp validate_contact_fields(issues, path, activity) do
    issues
    |> expect_one_of(path, activity, "direction", [
      "downlink",
      "uplink",
      "command",
      "tracking",
      "health_check"
    ])
    |> expect_type(path, activity, "source_window", :map)
    |> expect_type(path, activity, "cadence_import", :map)
    |> require_nested(path <> ".cadence_import", Map.get(activity, "cadence_import", %{}), [
      "external_id",
      "activity_type"
    ])
    |> validate_stable_ids(path, activity, ["station_reservation_id"])
    |> expect_optional_type(path, activity, "station_contention_status", :binary)
    |> expect_optional_type(path, activity, "station_reserved_by", :binary)
    |> expect_optional_type(path, activity, "station_reservation_status", :binary)
    |> validate_stable_ids(path <> ".cadence_import", Map.get(activity, "cadence_import", %{}), [
      "external_id"
    ])
  end

  defp validate_plan_delta(issues, path, delta) do
    issues
    |> require_fields(path, delta, [
      "activity_id",
