  defp validate_source_evidence_fields(issues, path, row) do
    issues =
      Enum.reduce(source_evidence_fields(), issues, fn field, acc ->
        case Map.get(row, field) do
          %{} = source ->
            validate_source_evidence_map(acc, "#{path}.#{field}", source)

          _source ->
            acc
        end
      end)

    Enum.reduce(source_evidence_list_fields(), issues, fn field, acc ->
      case Map.get(row, field) do
        sources when is_list(sources) ->
          sources
          |> Enum.with_index()
          |> Enum.reduce(acc, fn
            {%{} = source, index}, source_acc ->
              validate_source_evidence_map(source_acc, "#{path}.#{field}[#{index}]", source)

            {_source, _index}, source_acc ->
              source_acc
          end)

        _source ->
          acc
      end
    end)
  end

