  defp resource_projection_battery_handoff_flow_values(flow_rows) do
    %{
      "total_battery_energy_consumed_wh" =>
        sum_resource_projection_flow_number(flow_rows, "battery_energy_consumed_wh"),
      "total_battery_energy_generated_wh" =>
        sum_resource_projection_flow_number(flow_rows, "battery_energy_generated_wh"),
      "net_battery_energy_delta_wh" =>
        sum_resource_projection_flow_number(flow_rows, "battery_energy_delta_wh"),
