  defp sum_resource_projection_flow_number(flow_rows, field) do
    Enum.reduce(flow_rows, 0, fn row, total ->
      case row do
        %{} ->
          case Map.get(row, field) do
            value when is_number(value) -> total + value
            _value -> total
          end

        _row ->
          total
      end
    end)
  end

  defp sum_resource_projection_remaining(rows, capacity_field, used_or_demand_field) do
    rows
    |> resource_projection_remaining_values(capacity_field, used_or_demand_field)
    |> case do
      [] -> nil
      values -> Enum.sum(values)
    end
  end

  defp min_resource_projection_remaining(rows, capacity_field, used_or_demand_field) do
    rows
    |> resource_projection_remaining_values(capacity_field, used_or_demand_field)
    |> case do
      [] -> nil
      values -> Enum.min(values)
    end
  end

  defp resource_projection_remaining_values(rows, capacity_field, used_or_demand_field) do
    rows
    |> Enum.filter(&is_map/1)
    |> Enum.flat_map(fn row ->
      capacity = Map.get(row, capacity_field)
      used_or_demand = Map.get(row, used_or_demand_field)

      if is_number(capacity) and is_number(used_or_demand) do
        [max(capacity - used_or_demand, 0.0)]
      else
        []
      end
    end)
  end

  defp max_resource_projection_flow_number(flow_rows, field) do
    flow_rows
    |> Enum.flat_map(fn
      %{} = row ->
        case Map.get(row, field) do
          value when is_number(value) -> [value]
          _value -> []
        end

      _row ->
        []
    end)
    |> case do
      [] -> 0
      values -> Enum.max(values)
    end
  end

  defp max_resource_projection_optional_flow_number(flow_rows, field) do
