  defp validate_suppression_duplicate_handoff_row_fields(issues, path, row) do
    if suppression_duplicate_handoff_row?(row) do
      issues
      |> expect_optional_type(path, row, "duplicate_suppressed_candidate_id_collision", :boolean)
      |> expect_optional_integer(path, row, "duplicate_suppressed_candidate_index")
      |> expect_field_at_least(path, row, "duplicate_suppressed_candidate_index", 0)
      |> expect_optional_integer(path, row, "duplicate_suppressed_candidate_count")
      |> expect_field_at_least(path, row, "duplicate_suppressed_candidate_count", 0)
      |> validate_duplicate_suppressed_candidate_evidence(path, row)
    else
      issues
    end
  end

  defp suppression_duplicate_handoff_row?(row) do
    Map.get(row, "review_type") in ["contact_suppression", "resource_suppression"] or
      Map.get(row, "source_review_type") in ["contact_suppression", "resource_suppression"] or
      Map.get(row, "import_action") in [
        "review_contact_suppression",
        "review_resource_suppression"
      ]
  end

  defp validate_suppression_handoff_matches_source(issues, path, row) do
    case suppression_handoff_source(row) do
      {source_key, source_row} ->
        Enum.reduce(@suppression_handoff_source_field_pairs, issues, fn {row_field, source_field},
                                                                        acc ->
          row_value = Map.get(row, row_field)
          source_value = Map.get(source_row, source_field)

          if not is_nil(row_value) and not is_nil(source_value) and row_value != source_value do
            [
              error(
                "#{path}.#{row_field}",
                "must match #{source_key}.#{source_field}"
              )
              | acc
            ]
          else
            acc
          end
        end)

      nil ->
        issues
    end
  end

  defp suppression_handoff_source(row) do
    if suppression_duplicate_handoff_row?(row) do
      cond do
        is_map(Map.get(row, "source_contact_suppression")) ->
          {"source_contact_suppression", Map.get(row, "source_contact_suppression")}

        is_map(Map.get(row, "source_resource_suppression")) ->
          {"source_resource_suppression", Map.get(row, "source_resource_suppression")}

        true ->
          nil
      end
    end
  end

  defp validate_suppression_duplicate_handoff_groups(issues, path, rows) when is_list(rows) do
    duplicate_rows =
      rows
      |> Enum.with_index()
      |> Enum.filter(fn {row, _index} ->
        is_map(row) and suppression_duplicate_handoff_row?(row) and
          Map.get(row, "duplicate_suppressed_candidate_id_collision") == true and
          present_string?(Map.get(row, "base_candidate_id"))
      end)

    duplicate_rows
    |> Enum.group_by(fn {row, _index} ->
      {
        Map.get(row, "source_review_type") || Map.get(row, "review_type"),
        Map.get(row, "source") || get_in(row, ["source_review_row", "source"]),
        Map.get(row, "base_candidate_id")
      }
    end)
    |> Enum.reduce(issues, fn {_key, group}, acc ->
      expected_count = length(group)

      acc =
        Enum.reduce(group, acc, fn {row, row_index}, row_acc ->
          expect_field_equals(
            row_acc,
            "#{path}.rows[#{row_index}]",
            row,
            "duplicate_suppressed_candidate_count",
            expected_count
          )
        end)

      indexes =
        group
        |> Enum.map(fn {row, _index} -> Map.get(row, "duplicate_suppressed_candidate_index") end)
        |> Enum.sort()

      expected_indexes = Enum.to_list(1..expected_count)

      if indexes == expected_indexes do
        acc
      else
        [
          error(
            "#{path}.rows",
            "duplicate_suppressed_candidate_index values must cover 1..#{expected_count}"
          )
          | acc
        ]
      end
    end)
  end

  defp validate_suppression_duplicate_handoff_groups(issues, _path, _rows), do: issues

  defp validate_optional_policy_escalation(issues, path, row, field) do
    case Map.get(row, field) do
      nil ->
        issues

      %{} = escalation ->
        validate_policy_escalation(issues, "#{path}.#{field}", escalation)

      _value ->
        [error("#{path}.#{field}", "must be an object") | issues]
    end
  end

  defp validate_branch(issues, path, branch) do
    issues
    |> require_fields(path, branch, [
      "branch_id",
      "probability",
      "events",
      "candidate_plan",
      "repair_result",
      "score",
      "score_terms",
      "warnings",
      "risk_indicators",
      "approval_status",
      "approval_requirements",
      "policy_decision"
    ])
    |> validate_stable_ids(path, branch, ["branch_id"])
    |> expect_number(path, branch, "probability")
    |> expect_probability_range(path, branch, "probability")
    |> expect_number(path, branch, "score")
    |> expect_type(path, branch, "events", :list)
    |> expect_type(path, branch, "candidate_plan", :map)
    |> expect_type(path, branch, "repair_result", :map)
    |> expect_type(path, branch, "score_terms", :map)
    |> expect_type(path, branch, "approval_requirements", :list)
    |> expect_type(path, branch, "policy_decision", :map)
    |> validate_numeric_map(path <> ".score_terms", Map.get(branch, "score_terms"))
    |> validate_rows(path <> ".events", Map.get(branch, "events", []), &validate_branch_event/3)
    |> validate_optional_resource_projection_report(
      path <> ".resource_projection_report",
      Map.get(branch, "resource_projection_report")
    )
    |> validate_policy_decision(
      path <> ".policy_decision",
      Map.get(branch, "policy_decision", %{})
    )
    |> validate_branch_summary_consistency(path, branch)
    |> validate_rows(
      path <> ".approval_requirements",
      Map.get(branch, "approval_requirements", []),
      &validate_approval_requirement/3
    )
  end

  defp validate_branch_summary_consistency(issues, path, branch) do
    policy_decision = Map.get(branch, "policy_decision", %{})
    approval_requirements = Map.get(branch, "approval_requirements", [])
    risk_indicators = Map.get(branch, "risk_indicators", [])

    issues =
      issues
      |> validate_branch_expected_score(path, branch)
      |> expect_field_equals(
        path <> ".policy_decision",
        policy_decision,
        "classification",
        Map.get(branch, "approval_status"),
        "must match branch approval_status"
      )

    if policy_decision_has_rule_matches?(policy_decision) do
      issues
    else
      issues
      |> expect_field_equals(
        path <> ".policy_decision",
        policy_decision,
        "approval_requirement_count",
        if(is_list(approval_requirements), do: length(approval_requirements)),
        "must match branch approval_requirements count"
      )
      |> expect_field_equals(
        path <> ".policy_decision",
        policy_decision,
        "risk_count",
        if(is_list(risk_indicators), do: length(risk_indicators)),
        "must match branch risk_indicators count"
      )
    end
  end

  defp policy_decision_has_rule_matches?(%{"rule_matches" => rule_matches})
       when is_list(rule_matches) and rule_matches != [],
       do: true

  defp policy_decision_has_rule_matches?(_policy_decision), do: false

  defp validate_branch_expected_score(
         issues,
         path,
         %{"score" => score, "score_terms" => %{"expected_score" => expected_score}}
       )
       when is_number(score) and is_number(expected_score) do
    if abs(score - expected_score) <= 1.0e-9 do
      issues
    else
      [error(path <> ".score", "must match score_terms.expected_score") | issues]
    end
  end

  defp validate_branch_expected_score(issues, _path, _branch), do: issues

