  defp validate_approval_policy(issues, path, policy) when is_map(policy) do
    issues
    |> expect_optional_number(path, policy, "auto_approvable_risk_limit")
    |> expect_optional_number(path, policy, "auto_approvable_approval_count_limit")
    |> expect_optional_number(path, policy, "operator_review_risk_limit")
    |> expect_optional_list(path, policy, "blocked_risk_types")
    |> expect_optional_list(path, policy, "action_rules")
    |> validate_optional_rows(
      path <> ".action_rules",
      Map.get(policy, "action_rules"),
      &validate_policy_action_rule/3
    )
    |> validate_unique_policy_action_rule_ids(
      path <> ".action_rules",
      Map.get(policy, "action_rules")
    )
  end

  defp validate_approval_policy(issues, path, _policy),
    do: [error(path, "must be an object") | issues]

  defp validate_unique_policy_action_rule_ids(issues, path, rules) when is_list(rules) do
    {_seen_ids, issues} =
      rules
      |> Enum.with_index()
      |> Enum.reduce({MapSet.new(), issues}, fn
        {%{} = rule, index}, {seen_ids, acc} ->
          case Map.get(rule, "id") do
            id when is_binary(id) ->
              if MapSet.member?(seen_ids, id) do
                {seen_ids,
                 [error("#{path}[#{index}].id", "must be unique within action_rules") | acc]}
              else
                {MapSet.put(seen_ids, id), acc}
              end

            _id ->
              {seen_ids, acc}
          end

        {_rule, _index}, acc ->
          acc
      end)

    issues
  end

  defp validate_unique_policy_action_rule_ids(issues, _path, _rules), do: issues

  defp validate_policy_action_rule(issues, path, rule) do
    issues
    |> require_fields(path, rule, ["id", "classification", "reason"])
    |> validate_stable_ids(path, rule, ["id"])
    |> validate_optional_string_fields(path, rule, @policy_context_string_fields)
    |> validate_optional_string_lists(path, rule, @policy_context_string_array_fields)
    |> validate_optional_string_or_array_fields(
      path,
      rule,
      @policy_context_string_or_array_fields
    )
    |> validate_optional_number_fields(path, rule, @policy_action_rule_number_fields)
    |> validate_optional_integer_fields(path, rule, @policy_action_rule_integer_fields)
    |> validate_optional_boolean_fields(path, rule, @policy_context_boolean_fields)
    |> expect_optional_one_of(path, rule, "classification", [
      "auto_approvable",
      "operator_review_required",
      "blocked_by_policy"
    ])
    |> expect_optional_type(path, rule, "action", :binary)
    |> expect_optional_type(path, rule, "actions", :list)
    |> expect_optional_type(path, rule, "activity_type", :binary)
    |> expect_optional_type(path, rule, "activity_types", :list)
    |> validate_string_list_items(path, rule, "activity_types")
    |> expect_optional_type(path, rule, "spacecraft_ids", :list)
    |> validate_string_list_items(path, rule, "spacecraft_ids")
    |> expect_optional_type(path, rule, "target_ids", :list)
    |> validate_string_list_items(path, rule, "target_ids")
    |> expect_optional_type(path, rule, "requirement_type", :binary)
    |> expect_optional_type(path, rule, "requirement_types", :list)
    |> validate_string_list_items(path, rule, "requirement_types")
