  defp validate_policy_action_rule_escalation_authority(issues, path, rule) do
    escalation_fields = [
      "escalation_level",
      "escalation_queue",
      "escalation_role",
      "sla_s"
    ]

    has_escalation_metadata? = Enum.any?(escalation_fields, &Map.has_key?(rule, &1))

    if has_escalation_metadata? and not is_binary(Map.get(rule, "required_authority")) do
      [
        error(path <> ".required_authority", "is required when escalation metadata is present")
        | issues
      ]
    else
      issues
    end
  end

  defp validate_environment_model_capability(issues, path, record) do
    issues
    |> validate_stable_ids(path, record, ["id"])
    |> expect_equal(path, record, "schema_contract", "environment_model_capability.v1")
    |> expect_type(path, record, "category", :binary)
    |> expect_type(path, record, "model", :binary)
    |> expect_type(path, record, "source", :binary)
    |> expect_type(path, record, "validation_level", :binary)
    |> expect_one_of(path, record, "validation_level", validation_tolerance_policy_level_names())
    |> expect_type(path, record, "time_span", :binary)
    |> expect_type(path, record, "supported_bodies", :list)
    |> expect_type(path, record, "network_access", :boolean)
    |> expect_type(path, record, "parameters", :map)
    |> expect_type(path, record, "known_limits", :list)
    |> validate_string_list_items(path, record, "supported_bodies")
    |> validate_string_list_items(path, record, "known_limits")
    |> validate_environment_model_contract(path, record)
    |> expect_optional_type(path, record, "coordinate_frame", :binary)
    |> expect_optional_type(path, record, "interpolation", :binary)
  end

  defp validate_environment_provider_capability(issues, path, record) do
    coverage = Map.get(record, "coverage")
    coverage_map = if is_map(coverage), do: coverage, else: %{}

    issues
    |> validate_stable_ids(path, record, ["id"])
    |> expect_equal(path, record, "schema_contract", "environment_provider_capability.v1")
    |> expect_type(path, record, "category", :binary)
    |> expect_type(path, record, "source", :binary)
    |> expect_type(path, record, "validation_level", :binary)
    |> expect_one_of(path, record, "validation_level", validation_tolerance_policy_level_names())
    |> expect_type(path, record, "coverage", :map)
    |> expect_type(path, record, "interpolation", :binary)
    |> expect_type(path, record, "supported_bodies", :list)
    |> expect_type(path, record, "network_access", :boolean)
    |> expect_type(path, record, "known_limits", :list)
    |> validate_string_list_items(path, record, "supported_bodies")
    |> validate_string_list_items(path, record, "known_limits")
    |> expect_optional_type(path, record, "outputs", :list)
    |> validate_string_list_items(path, record, "outputs")
    |> validate_environment_provider_contract(path, record)
    |> expect_optional_number(path <> ".coverage", coverage_map, "starts_at_s")
    |> expect_optional_number(path <> ".coverage", coverage_map, "ends_at_s")
    |> validate_environment_provider_coverage(path <> ".coverage", coverage_map)
  end

  defp validate_environment_provider_coverage(issues, path, %{} = coverage) do
    starts_at_s = Map.get(coverage, "starts_at_s")
    ends_at_s = Map.get(coverage, "ends_at_s")

    if is_number(starts_at_s) and is_number(ends_at_s) and ends_at_s < starts_at_s do
      [error(path <> ".ends_at_s", "must be greater than or equal to starts_at_s") | issues]
    else
      issues
    end
  end

  defp validate_environment_model_contract(issues, path, record) do
    case OrbitalDynamics.Environment.validate_capability(record) do
      :ok ->
        issues

      {:error, {:missing_trust_boundary, "network_access"}} ->
        [
          error(
            path <> ".trust_boundary",
            "is required when environment model network_access is true"
          )
          | issues
        ]

      {:error, {:invalid_field, "known_limits"}} ->
        [
          error(path <> ".known_limits", "must match Environment.model_capabilities known limits")
          | issues
        ]

      {:error, {:invalid_field, field}} ->
        [error(path <> ".#{field}", "is invalid") | issues]

      {:error, reason} ->
        [error(path, "invalid environment model capability: #{inspect(reason)}") | issues]
    end
  end

  defp validate_environment_provider_contract(issues, path, record) do
    case OrbitalDynamics.Environment.validate_provider_capability(record) do
      :ok ->
        issues

      {:error, {:missing_trust_boundary, "network_access"}} ->
        [
          error(
            path <> ".trust_boundary",
            "is required when environment provider network_access is true"
          )
          | issues
        ]

      {:error, {:invalid_field, "known_limits"}} ->
        [
          error(
            path <> ".known_limits",
            "must match Environment.provider_capabilities known limits"
          )
          | issues
        ]

      {:error, {:invalid_field, field}} ->
        [error(path <> ".#{field}", "is invalid") | issues]

      {:error, reason} ->
        [error(path, "invalid environment provider capability: #{inspect(reason)}") | issues]
    end
  end

  defp validate_schema_validation_report(issues, path, report) do
    issues
    |> expect_equal(path, report, "schema_contract", "schema_validation_report.v1")
    |> expect_equal(path, report, "model", "executable_artifact_contract_validation")
    |> expect_one_of(path, report, "validation_mode", ["artifact_map", "artifact_file"])
    |> expect_type(path, report, "validated_contract", :binary)
    |> expect_one_of(path, report, "status", schema_validation_statuses())
    |> expect_type(path, report, "error_count", :integer)
    |> expect_type(path, report, "warning_count", :integer)
    |> expect_optional_integer(path, report, "remediation_count")
    |> expect_type(path, report, "errors", :list)
    |> expect_type(path, report, "warnings", :list)
    |> expect_optional_type(path, report, "remediation", :list)
    |> expect_optional_list(path, report, "model_limits")
    |> expect_type(path, report, "assumptions", :map)
    |> expect_optional_type(path, report, "artifact_path", :binary)
    |> expect_optional_type(path, report, "validated_artifact_family", :binary)
    |> expect_optional_integer(path, report, "validated_schema_version")
    |> validate_schema_validation_model_limits(path, report)
    |> validate_rows(
      path <> ".errors",
      Map.get(report, "errors", []),
      &validate_validation_issue/3
    )
    |> validate_rows(
      path <> ".warnings",
      Map.get(report, "warnings", []),
      &validate_validation_issue/3
    )
    |> validate_rows(
      path <> ".remediation",
      Map.get(report, "remediation", []),
      &validate_validation_remediation/3
    )
    |> validate_schema_validation_report_counts(path, report)
  end

  defp validate_schema_validation_batch_entry(issues, path, entry) do
    issues
    |> require_fields(path, entry, ["path", "report"])
    |> expect_type(path, entry, "path", :binary)
    |> validate_nested_schema_validation_report(path <> ".report", Map.get(entry, "report"))
  end

  defp validate_nested_schema_validation_report(issues, path, %{} = report) do
    validate_schema_validation_report(issues, path, report)
  end

  defp validate_nested_schema_validation_report(issues, path, _report) do
    [error(path, "must be an object") | issues]
  end

  defp validate_schema_validation_skipped_artifact(issues, path, entry) do
    issues
    |> require_fields(path, entry, ["path", "reason"])
    |> expect_type(path, entry, "path", :binary)
    |> expect_type(path, entry, "reason", :binary)
  end

  defp validate_schema_validation_model_limits(issues, path, report) do
    case Map.get(report, "model_limits") do
      nil ->
        issues

      limits when is_list(limits) ->
        if limits == schema_validation_model_limits() do
          issues
        else
          [
            error(
              path <> ".model_limits",
              "must match schema validation model limits"
            )
            | issues
          ]
        end

      _limits ->
        issues
    end
  end

  defp validate_schema_validation_report_counts(issues, path, report) do
    error_count = length(Map.get(report, "errors", []))
    expected_status = if error_count == 0, do: "pass", else: "fail"

    issues
    |> expect_field_equals(path, report, "status", expected_status)
    |> expect_field_equals(path, report, "error_count", error_count)
    |> expect_field_equals(path, report, "warning_count", length(Map.get(report, "warnings", [])))
    |> expect_field_equals(
      path,
      report,
      "remediation_count",
      length(Map.get(report, "remediation", []))
    )
  end

  defp validate_schema_validation_batch_counts(issues, path, report) do
    reports = Map.get(report, "reports", [])
    skipped_artifacts = Map.get(report, "skipped_artifacts", [])

    {error_count, warning_count, remediation_count} =
      reports
      |> Enum.map(&Map.get(&1, "report"))
      |> Enum.filter(&is_map/1)
      |> Enum.reduce({0, 0, 0}, fn nested_report, {errors, warnings, remediation} ->
        {
          errors + integer_or_zero(Map.get(nested_report, "error_count")),
          warnings + integer_or_zero(Map.get(nested_report, "warning_count")),
          remediation + integer_or_zero(Map.get(nested_report, "remediation_count"))
        }
      end)

    status_counts =
      reports
      |> Enum.map(&get_in(&1, ["report", "status"]))
      |> Enum.reject(&is_nil/1)
      |> Enum.frequencies()

    issues
    |> expect_field_equals(
      path,
      report,
      "file_count",
      length(reports) + length(skipped_artifacts)
    )
    |> expect_field_equals(path, report, "artifact_count", length(reports))
    |> expect_field_equals(path, report, "skipped_count", length(skipped_artifacts))
    |> expect_field_equals(path, report, "status", if(error_count == 0, do: "pass", else: "fail"))
    |> expect_field_equals(
      path,
      report,
      "status_counts",
      status_counts,
      "must equal nested schema-validation report status counts"
    )
    |> expect_field_equals(path, report, "error_count", error_count)
    |> expect_field_equals(path, report, "warning_count", warning_count)
    |> expect_field_equals(path, report, "remediation_count", remediation_count)
  end

  defp validate_schema_migration_row(issues, path, row) do
    issues
    |> require_fields(path, row, [
      "schema_contract",
      "artifact_family",
      "schema_version",
      "status",
      "migration_action",
      "required_field_count",
      "optional_field_count",
      "nested_contract_count"
    ])
    |> expect_type(path, row, "schema_contract", :binary)
    |> expect_type(path, row, "artifact_family", :binary)
    |> expect_non_negative_integer(path, row, "schema_version")
    |> expect_one_of(
      path,
      row,
      "status",
      OrbitalDynamics.Validation.capabilities().schema_migration_row_statuses
    )
    |> expect_one_of(
      path,
      row,
      "migration_action",
      OrbitalDynamics.Validation.capabilities().schema_migration_actions
    )
    |> expect_optional_type(path, row, "replacement_contract", :binary)
    |> expect_optional_type(path, row, "deprecation_warning", :binary)
    |> expect_non_negative_integer(path, row, "required_field_count")
    |> expect_non_negative_integer(path, row, "optional_field_count")
    |> expect_non_negative_integer(path, row, "nested_contract_count")
    |> validate_schema_migration_row_action(path, row)
  end

  defp validate_schema_migration_row_action(issues, path, %{"status" => "deprecated"} = row) do
    if Map.has_key?(row, "replacement_contract") or
         Map.get(row, "migration_action") == "review_deprecated_contract" do
      issues
    else
      [
        error(
          path <> ".replacement_contract",
          "is required unless deprecated rows use review_deprecated_contract"
        )
        | issues
      ]
    end
  end

  defp validate_schema_migration_row_action(issues, _path, _row), do: issues

  defp validate_schema_migration_report_counts(issues, path, report) do
    rows = Map.get(report, "rows", [])
    status_counts = frequency_map(rows, "status")
    action_counts = frequency_map(rows, "migration_action")
    deprecated_count = Map.get(status_counts, "deprecated", 0)
    future_count = Map.get(status_counts, "future", 0)

    expected_status =
      if deprecated_count > 0 or future_count > 0, do: "review_required", else: "current"

    issues
    |> expect_field_equals(path, report, "status", expected_status)
    |> expect_field_equals(path, report, "contract_count", length(rows))
    |> expect_field_equals(path, report, "migration_row_count", length(rows))
    |> expect_field_equals(
      path,
      report,
      "current_contract_count",
      Map.get(status_counts, "current", 0)
    )
    |> expect_field_equals(path, report, "deprecated_contract_count", deprecated_count)
    |> expect_field_equals(path, report, "future_contract_count", future_count)
    |> expect_field_equals(path, report, "deprecation_warning_count", deprecated_count)
    |> expect_field_equals(
      path,
      report,
      "status_counts",
      status_counts,
      "must equal row status counts"
    )
    |> expect_field_equals(
      path,
      report,
      "migration_action_counts",
      action_counts,
      "must equal row migration-action counts"
    )
  end

  defp integer_or_zero(value) when is_integer(value), do: value
  defp integer_or_zero(_value), do: 0

  defp numeric_delta(left, right) when is_number(left) and is_number(right), do: left - right
  defp numeric_delta(_left, _right), do: nil

  defp validate_campaign_request_lint(issues, path, report) do
