    |> validate_campaign_source_plan_ref(path <> ".source_plan", Map.get(report, "source_plan"))
  end

  defp validate_campaign_request_lint_status(issues, path, report) do
    case Map.get(report, "error_count") do
      count when is_integer(count) and count == 0 ->
        expect_field_equals(
          issues,
          path,
          report,
          "status",
          "pass",
          "must be pass when error_count is zero"
        )

      count when is_integer(count) and count > 0 ->
        expect_field_equals(
          issues,
          path,
          report,
          "status",
          "fail",
          "must be fail when error_count is positive"
        )

      _count ->
        issues
    end
  end

  defp validate_campaign_request_ref(issues, path, request) do
    issues
    |> require_fields(path, request, ["path", "sha256"])
    |> expect_type(path, request, "path", :binary)
    |> expect_type(path, request, "sha256", :binary)
    |> validate_sha256_field(path, request, "sha256")
  end

  defp validate_campaign_source_plan_ref(issues, _path, nil), do: issues

  defp validate_campaign_source_plan_ref(issues, path, source_plan) when is_map(source_plan) do
    issues
    |> require_fields(path, source_plan, ["schema_contract", "status", "path", "sha256"])
    |> expect_one_of(path, source_plan, "status", ["pass", "fail"])
    |> expect_type(path, source_plan, "schema_contract", :binary)
    |> expect_type(path, source_plan, "path", :binary)
    |> expect_type(path, source_plan, "sha256", :binary)
    |> validate_sha256_field(path, source_plan, "sha256")
    |> validate_stable_ids(path, source_plan, ["plan_id"])
  end

  defp validate_campaign_source_plan_ref(issues, path, _source_plan),
    do: [error(path, "must be an object") | issues]

  defp validate_sha256_field(issues, path, map, field) do
    case Map.get(map, field) do
      value when is_binary(value) ->
        if Regex.match?(@sha256_regex, value) do
          issues
        else
          [error("#{path}.#{field}", "must be a lowercase SHA-256 hex digest") | issues]
        end

      _value ->
        issues
    end
  end

  defp validate_study_manifest_lint(issues, path, report) do
    errors = Map.get(report, "errors", [])
    warnings = Map.get(report, "warnings", [])
    supported_codes = get_in(report, ["supported", "lint_error_codes"]) || []
    expected_status = if length(errors) == 0, do: "pass", else: "fail"

    issues
    |> expect_equal(path, report, "schema_contract", "study_manifest_lint.v1")
    |> expect_equal(path, report, "schema_version", 1)
    |> expect_type(path, report, "schema_id", :binary)
    |> expect_equal(path, report, "manifest_schema_contract", "study_manifest.v1")
    |> expect_type(path, report, "manifest_schema_id", :binary)
    |> expect_equal(path, report, "validation_mode", "study_manifest_lint")
    |> expect_equal(
      path,
      report,
      "semantic_validator",
      "OrbitalDynamics.Study.Manifest.from_map/1 + OrbitalDynamics.StudyRunner.validate_run_inputs/2"
    )
    |> expect_type(path, report, "lint_task", :binary)
    |> expect_type(path, report, "schema_export_command", :binary)
    |> expect_type(path, report, "supported", :map)
    |> expect_type(path, report, "manifest", :map)
    |> expect_one_of(path, report, "status", ["pass", "fail"])
    |> expect_type(path, report, "error_count", :integer)
    |> expect_type(path, report, "warning_count", :integer)
    |> expect_type(path, report, "errors", :list)
    |> expect_type(path, report, "warnings", :list)
    |> expect_optional_type(path, report, "study_id", :binary)
    |> expect_optional_type(path, report, "scenario_count", :integer)
    |> expect_optional_type(path, report, "outputs", :list)
    |> validate_study_manifest_lint_supported(
      path <> ".supported",
      Map.get(report, "supported", %{})
    )
    |> validate_study_manifest_lint_manifest(
      path <> ".manifest",
      Map.get(report, "manifest", %{})
    )
    |> validate_rows(path <> ".errors", errors, &validate_manifest_lint_issue/3)
    |> validate_rows(path <> ".warnings", warnings, &validate_manifest_lint_issue/3)
    |> validate_manifest_lint_issue_codes(path <> ".errors", errors, supported_codes)
    |> validate_manifest_lint_issue_codes(path <> ".warnings", warnings, supported_codes)
    |> validate_string_list_items(path, report, "outputs")
    |> validate_study_manifest_lint_outputs(path, report)
    |> expect_field_equals(path, report, "status", expected_status)
    |> expect_field_equals(path, report, "error_count", length(errors))
    |> expect_field_equals(path, report, "warning_count", length(warnings))
  end

  defp validate_study_manifest_lint_outputs(issues, path, report) do
    outputs = list_value(report, "outputs")
    supported_outputs = get_in(report, ["supported", "outputs"]) || []

    issues
    |> reject_duplicate_strings(path <> ".outputs", outputs, "must not contain duplicate outputs")
    |> validate_study_manifest_lint_supported_outputs(path, outputs, supported_outputs)
  end

  defp validate_study_manifest_lint_supported_outputs(issues, path, outputs, supported_outputs)
       when is_list(outputs) and is_list(supported_outputs) do
    unsupported_outputs =
      outputs
      |> Enum.filter(&(is_binary(&1) and &1 not in supported_outputs))
      |> Enum.sort()

    if unsupported_outputs == [] do
      issues
    else
      [error(path <> ".outputs", "must be included in supported.outputs") | issues]
    end
  end

  defp validate_study_manifest_lint_supported_outputs(
         issues,
         _path,
         _outputs,
         _supported_outputs
       ),
       do: issues

  defp reject_duplicate_strings(issues, path, values, message) do
    duplicates =
      values
      |> Enum.filter(&is_binary/1)
      |> Enum.frequencies()
      |> Enum.filter(fn {_value, count} -> count > 1 end)

    if duplicates == [] do
      issues
    else
      [error(path, message) | issues]
    end
  end

  defp validate_study_manifest_lint_supported(issues, path, supported) when is_map(supported) do
    issues
    |> require_fields(path, supported, ["lint_error_codes", "outputs", "propagators"])
    |> expect_type(path, supported, "lint_error_codes", :list)
    |> expect_type(path, supported, "outputs", :list)
    |> expect_type(path, supported, "propagators", :list)
    |> validate_string_list_items(path, supported, "lint_error_codes")
    |> validate_string_list_items(path, supported, "outputs")
    |> validate_string_list_items(path, supported, "propagators")
    |> validate_string_list_items(path, supported, "search_objectives")
  end

  defp validate_study_manifest_lint_supported(issues, path, _supported),
    do: [error(path, "must be an object") | issues]

  defp validate_study_manifest_lint_manifest(issues, path, manifest) when is_map(manifest) do
    issues
    |> require_fields(path, manifest, ["path"])
    |> expect_type(path, manifest, "path", :binary)
    |> expect_optional_type(path, manifest, "sha256", :binary)
  end

  defp validate_study_manifest_lint_manifest(issues, path, _manifest),
    do: [error(path, "must be an object") | issues]

  defp validate_study_benchmark(issues, path, artifact) do
    benchmark_options = Map.get(artifact, "benchmark_options", %{})
    results = Map.get(artifact, "results", [])

    issues
    |> validate_optional_schema_contract(path, artifact, "study_benchmark.v1")
    |> validate_study_benchmark_options("#{path}.benchmark_options", benchmark_options)
    |> validate_rows("#{path}.results", results, &validate_study_benchmark_result/3)
    |> validate_study_benchmark_result_options(path, benchmark_options, results)
  end

  defp validate_study_benchmark_options(issues, path, options) when is_map(options) do
    issues
    |> expect_optional_type(path, options, "modes", :list)
    |> expect_optional_type(path, options, "propagators", :list)
    |> expect_optional_type(path, options, "task_supervisor_node", :binary)
    |> expect_optional_non_negative_integer(path, options, "max_concurrency")
    |> expect_optional_non_negative_integer(path, options, "repetitions")
    |> expect_optional_type(path, options, "max_concurrencies", :list)
    |> expect_optional_type(path, options, "monte_carlo_counts", :list)
    |> expect_optional_type(path, options, "task_chunk_sizes", :list)
    |> validate_string_list_items(path, options, "modes")
    |> validate_string_list_items(path, options, "propagators")
    |> validate_non_negative_integer_list_items(path, options, "max_concurrencies")
    |> validate_non_negative_integer_list_items(path, options, "monte_carlo_counts")
    |> validate_non_negative_integer_list_items(path, options, "task_chunk_sizes")
  end

  defp validate_study_benchmark_options(issues, _path, _options), do: issues

  defp validate_study_benchmark_result(issues, path, result) do
    issues
    |> expect_type(path, result, "id", :binary)
    |> expect_optional_type(path, result, "backend", :binary)
    |> expect_optional_type(path, result, "execution_mode", :binary)
    |> expect_optional_type(path, result, "mode", :binary)
    |> expect_optional_type(path, result, "propagator", :binary)
    |> expect_optional_type(path, result, "task_supervisor_node", :binary)
    |> expect_optional_type(path, result, "batch_propagation", :boolean)
    |> expect_optional_type(path, result, "matches_baseline", :boolean)
    |> expect_optional_type(path, result, "output_signature", :map)
    |> expect_optional_type(path, result, "per_node_trajectory_counts", :map)
    |> expect_optional_type(path, result, "runtime_telemetry", :map)
    |> validate_study_benchmark_result_integer_fields(path, result)
    |> validate_study_benchmark_result_number_fields(path, result)
    |> validate_non_negative_integer_count_map(
      "#{path}.per_node_trajectory_counts",
      Map.get(result, "per_node_trajectory_counts", %{})
    )
    |> validate_study_benchmark_output_signature(path, Map.get(result, "output_signature"))
    |> validate_study_benchmark_result_counts(path, result)
  end

  defp validate_study_benchmark_result_integer_fields(issues, path, result) do
    Enum.reduce(
      [
        "effective_task_concurrency",
        "failure_count",
        "max_concurrency",
        "monte_carlo_count",
        "repetition",
        "repetitions",
        "scenario_count",
        "task_chunk_size",
        "trajectory_count"
      ],
      issues,
      fn field, acc -> expect_optional_non_negative_integer(acc, path, result, field) end
    )
  end

  defp validate_study_benchmark_result_number_fields(issues, path, result) do
    Enum.reduce(
      [
        "artifact_build_ms",
        "duration_ms",
        "event_detection_ms",
        "overhead_ms",
        "overhead_percent",
        "propagation_ms",
        "scenarios_per_second"
      ],
      issues,
      fn field, acc -> expect_optional_non_negative_number(acc, path, result, field) end
    )
  end

  defp validate_study_benchmark_output_signature(issues, path, signature)
       when is_map(signature) do
    signature_path = "#{path}.output_signature"

    issues
    |> expect_optional_type(signature_path, signature, "constraints", :list)
    |> expect_optional_type(signature_path, signature, "ranking", :list)
    |> expect_optional_type(signature_path, signature, "scenario_ids", :list)
    |> validate_string_list_items(signature_path, signature, "ranking")
    |> validate_string_list_items(signature_path, signature, "scenario_ids")
  end

  defp validate_study_benchmark_output_signature(issues, _path, _signature), do: issues

  defp validate_study_benchmark_result_counts(issues, path, result) do
    signature = Map.get(result, "output_signature")

    issues
    |> expect_field_equals(
      path,
      result,
      "scenario_count",
      study_benchmark_scenario_count(signature),
      "must equal output_signature scenario_ids count"
    )
    |> expect_field_equals(
      path,
      result,
      "trajectory_count",
      study_benchmark_trajectory_count(Map.get(result, "per_node_trajectory_counts")),
      "must equal per_node_trajectory_counts sum"
    )
  end

  defp study_benchmark_scenario_count(%{"scenario_ids" => scenario_ids})
       when is_list(scenario_ids),
       do: length(scenario_ids)

  defp study_benchmark_scenario_count(_signature), do: nil

  defp study_benchmark_trajectory_count(counts) when is_map(counts) do
    values = Map.values(counts)

    if Enum.all?(values, &(is_integer(&1) and &1 >= 0)),
      do: Enum.sum(values),
      else: nil
  end

  defp study_benchmark_trajectory_count(_counts), do: nil

  defp validate_study_benchmark_result_options(issues, path, options, results)
       when is_map(options) and is_list(results) do
    repetitions = Map.get(options, "repetitions")
    modes = Map.get(options, "modes")

    results
    |> Enum.with_index()
    |> Enum.reduce(issues, fn
      {result, index}, acc when is_map(result) ->
        result_path = "#{path}.results[#{index}]"

        acc
        |> expect_field_equals(
          result_path,
          result,
          "repetitions",
          study_benchmark_option_repetitions(repetitions),
          "must equal benchmark_options repetitions"
        )
        |> expect_optional_one_of(
          result_path,
          result,
          "mode",
          study_benchmark_option_modes(modes)
        )

      {_result, _index}, acc ->
        acc
    end)
  end

  defp validate_study_benchmark_result_options(issues, _path, _options, _results), do: issues

  defp study_benchmark_option_repetitions(value) when is_integer(value) and value >= 0, do: value
  defp study_benchmark_option_repetitions(_value), do: nil

  defp study_benchmark_option_modes(modes) when is_list(modes), do: modes
  defp study_benchmark_option_modes(_modes), do: []

  defp validate_manifest_lint_issue(issues, path, issue) do
    issues
    |> require_fields(path, issue, ["code", "path", "message", "details"])
    |> expect_type(path, issue, "code", :binary)
    |> expect_type(path, issue, "path", :binary)
    |> expect_type(path, issue, "message", :binary)
    |> expect_type(path, issue, "details", :map)
  end

  defp validate_manifest_lint_issue_codes(issues, path, rows, supported_codes)
       when is_list(rows) and is_list(supported_codes) do
    rows
    |> Enum.with_index()
    |> Enum.reduce(issues, fn {row, index}, acc ->
      code = if is_map(row), do: Map.get(row, "code")

      if is_binary(code) and code not in supported_codes do
        [error("#{path}[#{index}].code", "must be one of #{inspect(supported_codes)}") | acc]
      else
        acc
      end
    end)
  end

  defp validate_manifest_lint_issue_codes(issues, _path, _rows, _supported_codes), do: issues

  defp validate_capability_catalog_schema_section(issues, artifact) do
    schema = get_in(artifact, ["validation", "schema"])

    issues =
      if is_map(schema) do
        issues
        |> require_fields("$.validation.schema", schema, [
          "artifact_contracts",
          "artifact_contract_count",
          "compatibility_policy_version",
          "identity_policy_version",
          "known_limits"
        ])
        |> expect_type("$.validation.schema", schema, "artifact_contracts", :list)
        |> expect_type("$.validation.schema", schema, "artifact_contract_count", :integer)
        |> expect_type("$.validation.schema", schema, "compatibility_policy_version", :integer)
        |> expect_type("$.validation.schema", schema, "identity_policy_version", :integer)
        |> expect_type("$.validation.schema", schema, "known_limits", :list)
        |> expect_field_equals(
          "$.validation.schema",
          schema,
          "artifact_contract_count",
          length(Map.get(schema, "artifact_contracts", []))
        )
      else
        [error("$.validation.schema", "must be an object") | issues]
      end

    validate_capability_catalog_contract_list(issues, schema)
  end

  defp validate_capability_catalog_contract_list(issues, %{} = schema) do
    case Map.get(schema, "artifact_contracts") do
      contracts when is_list(contracts) ->
        issues =
          contracts
          |> Enum.with_index()
          |> Enum.reduce(issues, fn {contract, index}, acc ->
            cond do
              not is_binary(contract) ->
                [
                  error("$.validation.schema.artifact_contracts[#{index}]", "must be a string")
                  | acc
                ]

              not Map.has_key?(@contracts, contract) ->
                [
                  error(
                    "$.validation.schema.artifact_contracts[#{index}]",
                    "must be a known executable contract"
                  )
                  | acc
                ]

              true ->
                acc
            end
          end)

        expect_field_equals(
          issues,
          "$.validation.schema",
          schema,
          "artifact_contracts",
          @contracts |> Map.keys() |> Enum.sort(),
          "must match executable contract registry"
        )

      _contracts ->
        issues
    end
  end

  defp validate_capability_catalog_contract_list(issues, _schema), do: issues

  defp validate_validation_issue(issues, path, issue) do
    issues
    |> require_fields(path, issue, ["severity", "path", "message"])
    |> expect_one_of(path, issue, "severity", ["error", "warning"])
    |> expect_type(path, issue, "path", :binary)
    |> expect_type(path, issue, "message", :binary)
    |> expect_optional_type(path, issue, "remediation", :binary)
    |> expect_optional_type(path, issue, "schema_contract", :binary)
    |> expect_optional_type(path, issue, "artifact_path", :binary)
  end

  defp validate_validation_remediation(issues, path, remediation) do
    issues
    |> require_fields(path, remediation, ["path", "category", "action", "source_message"])
    |> expect_type(path, remediation, "path", :binary)
    |> expect_type(path, remediation, "category", :binary)
    |> expect_type(path, remediation, "action", :binary)
    |> expect_type(path, remediation, "source_message", :binary)
  end

  defp validate_validation_record(issues, path, record) do
    issues
    |> expect_equal(path, record, "schema_contract", "validation_record.v1")
    |> validate_stable_ids(path, record, ["id"])
    |> expect_type(path, record, "model", :binary)
    |> expect_type(path, record, "implementation", :binary)
    |> expect_type(path, record, "validation_level", :binary)
    |> expect_one_of(path, record, "validation_level", validation_tolerance_policy_level_names())
    |> expect_type(path, record, "covered_regime", :binary)
    |> expect_type(path, record, "evidence", :list)
    |> expect_type(path, record, "known_limits", :list)
    |> expect_type(path, record, "tolerances", :map)
    |> validate_validation_record_tolerances(path <> ".tolerances", Map.get(record, "tolerances"))
    |> validate_string_list_items(path, record, "evidence")
    |> validate_string_list_items(path, record, "known_limits")
    |> validate_registered_validation_record_fields(path, record)
  end

  defp validate_embedded_validation_record(issues, path, record) do
    issues
    |> validate_optional_schema_contract(path, record, "validation_record.v1")
    |> validate_stable_ids(path, record, ["id"])
    |> expect_type(path, record, "model", :binary)
    |> expect_type(path, record, "implementation", :binary)
    |> expect_type(path, record, "validation_level", :binary)
    |> expect_one_of(path, record, "validation_level", validation_tolerance_policy_level_names())
    |> expect_type(path, record, "covered_regime", :binary)
    |> expect_type(path, record, "evidence", :list)
    |> expect_type(path, record, "known_limits", :list)
    |> expect_type(path, record, "tolerances", :map)
    |> validate_validation_record_tolerances(path <> ".tolerances", Map.get(record, "tolerances"))
    |> validate_string_list_items(path, record, "evidence")
    |> validate_string_list_items(path, record, "known_limits")
    |> validate_registered_validation_record_fields(path, record)
  end

  defp validate_registered_validation_record_fields(issues, path, record) do
    case OrbitalDynamics.Validation.record(Map.get(record, "id")) do
      {:ok, expected} ->
        issues
        |> expect_field_equals(
          path,
          record,
          "model",
          expected["model"],
          "must match registered validation record model"
        )
        |> expect_field_equals(
          path,
          record,
          "known_limits",
          expected["known_limits"],
          "must match registered validation record known limits"
        )

      :error ->
        issues
    end
  end

  defp validate_validation_record_tolerances(issues, path, tolerances) when is_map(tolerances) do
    Enum.reduce(tolerances, issues, fn {field, value}, acc ->
      if (is_number(value) and value >= 0.0) or is_binary(value) do
        acc
      else
        [error("#{path}.#{field}", "must be a non-negative number or string") | acc]
      end
    end)
  end

  defp validate_validation_record_tolerances(issues, _path, _tolerances), do: issues

  defp validate_model_acceptance_report(issues, path, report) do
    capability = OrbitalDynamics.Validation.capabilities()
    rows = Map.get(report, "rows", [])

    issues
    |> expect_equal(path, report, "schema_contract", "model_acceptance_report.v1")
    |> expect_equal(path, report, "schema_version", 1)
    |> validate_stable_ids(path, report, ["report_id"])
    |> expect_equal(path, report, "model", "registry_model_acceptance_classifier")
    |> expect_one_of(path, report, "intended_use", capability.intended_uses)
    |> expect_one_of(path, report, "status", capability.acceptance_statuses)
    |> expect_non_negative_integer(path, report, "model_count")
    |> expect_non_negative_integer(path, report, "accepted_count")
    |> expect_non_negative_integer(path, report, "review_required_count")
    |> expect_non_negative_integer(path, report, "blocked_count")
    |> expect_non_negative_integer(path, report, "unknown_model_count")
    |> expect_optional_type(path, report, "status_counts", :map)
    |> validate_non_negative_integer_count_map(
      path <> ".status_counts",
      Map.get(report, "status_counts")
    )
    |> expect_type(path, report, "validation_level_counts", :map)
    |> validate_non_negative_integer_count_map(
      path <> ".validation_level_counts",
      Map.get(report, "validation_level_counts")
    )
    |> expect_optional_type(path, report, "model_ids_by_status", :map)
    |> expect_field_equals(
      path,
      report,
      "model_ids_by_status",
      model_acceptance_model_ids_by(rows, "status"),
      "must match model IDs grouped by row status"
    )
    |> expect_optional_type(path, report, "model_ids_by_validation_level", :map)
    |> expect_field_equals(
      path,
      report,
      "model_ids_by_validation_level",
      model_acceptance_model_ids_by(rows, "validation_level"),
      "must match model IDs grouped by validation level"
    )
    |> expect_optional_type(path, report, "model_ids_by_intended_use", :map)
    |> expect_field_equals(
      path,
      report,
      "model_ids_by_intended_use",
      model_acceptance_model_ids_by_intended_use(rows, Map.get(report, "intended_use")),
      "must match model IDs grouped by intended use"
    )
    |> expect_type(path, report, "records", :list)
    |> validate_rows(
      path <> ".records",
      Map.get(report, "records", []),
      &validate_validation_record/3
    )
    |> validate_model_acceptance_records(path, report)
    |> expect_type(path, report, "rows", :list)
    |> validate_rows(path <> ".rows", rows, &validate_model_acceptance_row/3)
    |> expect_type(path, report, "assumptions", :map)
    |> validate_model_acceptance_assumptions(path, report, rows)
    |> expect_type(path, report, "model_limits", :list)
    |> validate_string_list_items(path, report, "model_limits")
    |> validate_optional_exact_model_limits(
      path,
      report,
      model_acceptance_report_model_limits(),
      "must match model acceptance report model limits"
    )
    |> expect_field_equals(
      path,
      report,
      "status",
      model_acceptance_report_status(rows),
      "must match row-derived model acceptance status"
    )
    |> expect_field_equals(path, report, "model_count", if(is_list(rows), do: length(rows)))
    |> expect_field_equals(
      path,
      report,
      "accepted_count",
      model_acceptance_row_status_count(rows, "accepted")
    )
    |> expect_field_equals(
      path,
      report,
      "review_required_count",
      model_acceptance_row_status_count(rows, "review_required")
    )
    |> expect_field_equals(
      path,
      report,
      "blocked_count",
      model_acceptance_row_status_count(rows, "blocked")
    )
    |> expect_field_equals(
      path,
      report,
      "unknown_model_count",
      model_acceptance_unknown_model_count(rows)
    )
    |> expect_field_equals(
      path,
      report,
      "status_counts",
      if(is_list(rows), do: frequency_map(rows, "status")),
      "must match row-derived status_counts"
    )
    |> expect_field_equals(
      path,
      report,
      "validation_level_counts",
      if(is_list(rows), do: frequency_map(rows, "validation_level")),
      "must match row-derived validation_level_counts"
    )
  end

  defp validate_model_acceptance_records(issues, path, report) do
    records = Map.get(report, "records")
    rows = Map.get(report, "rows")

    if is_list(records) and is_list(rows) do
      record_ids =
        records
        |> Enum.filter(&is_map/1)
        |> Enum.map(&Map.get(&1, "id"))
        |> Enum.reject(&is_nil/1)

      row_record_ids =
        rows
        |> Enum.filter(&is_map/1)
        |> Enum.map(&get_in(&1, ["validation_record", "id"]))
        |> Enum.reject(&is_nil/1)

      if record_ids == row_record_ids do
        issues
      else
        [error(path <> ".records", "must match row validation_record IDs") | issues]
      end
    else
      issues
    end
  end

  defp validate_model_acceptance_assumptions(issues, path, report, rows) when is_list(rows) do
    case Map.get(report, "assumptions") do
      %{} = assumptions ->
        model_ids =
          rows
          |> Enum.filter(&is_map/1)
          |> Enum.map(&Map.get(&1, "model_id"))
          |> Enum.reject(&is_nil/1)

        issues
        |> expect_field_equals(
          path <> ".assumptions",
          assumptions,
          "intended_use",
          Map.get(report, "intended_use"),
          "must match report intended_use"
        )
        |> expect_field_equals(
          path <> ".assumptions",
          assumptions,
          "input_model_ids",
          model_ids,
          "must match row model IDs"
        )

      _assumptions ->
        issues
    end
  end

  defp validate_model_acceptance_assumptions(issues, _path, _report, _rows), do: issues

  defp model_acceptance_report_status(rows) when is_list(rows) do
    cond do
      model_acceptance_row_status_count(rows, "blocked") > 0 -> "blocked"
      model_acceptance_row_status_count(rows, "review_required") > 0 -> "review_required"
      true -> "accepted_for_use"
    end
  end

  defp model_acceptance_report_status(_rows), do: nil

  defp validate_model_acceptance_row(issues, path, row) do
    capability = OrbitalDynamics.Validation.capabilities()

    issues
    |> require_fields(path, row, [
      "id",
      "rank",
      "model_id",
      "validation_level",
      "status",
      "reason"
    ])
    |> validate_stable_ids(path, row, ["id", "model_id"])
    |> expect_non_negative_integer(path, row, "rank")
    |> expect_type(path, row, "validation_level", :binary)
    |> expect_one_of(path, row, "status", capability.row_statuses)
    |> expect_type(path, row, "reason", :binary)
    |> expect_optional_type(path, row, "implementation", :binary)
    |> expect_optional_type(path, row, "validation_record", :map)
    |> validate_optional_model_acceptance_record(path, Map.get(row, "validation_record"))
  end

