  defp validate_validation_safety_case_summary(issues, path, report) do
    capability = OrbitalDynamics.Validation.capabilities()
    rows = Map.get(report, "evidence", [])

    issues
    |> expect_equal(path, report, "schema_contract", "validation_safety_case_summary.v1")
