  defp validate_validation_check(issues, path, check) do
    issues
    |> require_fields(path, check, ["field", "status", "expected", "observed", "tolerance"])
    |> expect_type(path, check, "field", :binary)
    |> expect_one_of(path, check, "status", ["pass", "fail"])
    |> expect_optional_number(path, check, "error")
    |> expect_optional_number(path, check, "max_abs_error")
    |> validate_validation_check_result(path, check)
  end

  defp validate_validation_check_result(issues, path, check) do
    expected = Map.get(check, "expected")
    observed = Map.get(check, "observed")
    tolerance = Map.get(check, "tolerance")

    case validation_check_result(expected, observed, tolerance) do
      {:ok, status, metric_field, metric_value} ->
        issues
        |> expect_field_equals(
          path,
          check,
          "status",
          status,
          "must match expected/observed/tolerance comparison"
        )
        |> expect_field_equals(
          path,
          check,
          metric_field,
          metric_value,
          "must match expected/observed comparison error"
        )

      {:ok, status} ->
        expect_field_equals(
          issues,
          path,
          check,
          "status",
          status,
          "must match expected/observed comparison"
        )
    end
  end

  defp validation_check_result(expected, observed, tolerance)
       when is_number(expected) and is_number(observed) and is_number(tolerance) do
    error = abs(observed - expected)
    {:ok, if(error <= tolerance, do: "pass", else: "fail"), "error", error}
  end

  defp validation_check_result(expected, observed, tolerance)
       when is_list(expected) and is_list(observed) and is_number(tolerance) do
    if validation_check_numeric_vector?(expected) and validation_check_numeric_vector?(observed) and
         length(expected) == length(observed) do
      error =
        expected
        |> Enum.zip(observed)
        |> Enum.map(fn {expected_value, observed_value} ->
          abs(observed_value - expected_value)
        end)
        |> Enum.max(fn -> 0.0 end)

      {:ok, if(error <= tolerance, do: "pass", else: "fail"), "max_abs_error", error}
    else
      {:ok, if(observed == expected, do: "pass", else: "fail")}
    end
  end

  defp validation_check_result(expected, observed, _tolerance),
    do: {:ok, if(observed == expected, do: "pass", else: "fail")}

  defp validation_check_numeric_vector?(values), do: Enum.all?(values, &is_number/1)

  defp validate_rows(issues, path, rows, validator) when is_list(rows) do
    rows
    |> Enum.with_index()
    |> Enum.reduce(issues, fn {row, index}, acc ->
      if is_map(row) do
        validator.(acc, "#{path}[#{index}]", row)
      else
        [error("#{path}[#{index}]", "must be an object") | acc]
      end
    end)
  end

  defp validate_rows(issues, _path, _rows, _validator), do: issues

  defp validate_optional_rows(issues, _path, nil, _validator), do: issues

  defp validate_optional_rows(issues, path, rows, validator) when is_list(rows),
    do: validate_rows(issues, path, rows, validator)

  defp validate_optional_rows(issues, path, _rows, _validator),
    do: [error(path, "must be a list") | issues]

