    )
    |> expect_one_of(
      path,
      row,
      "status",
      OrbitalDynamics.Timeline.capabilities().activity_precondition_statuses
    )
    |> expect_type(path, row, "field", :binary)
    |> expect_type(path, row, "reason", :binary)
  end

